VALUES
  ('cpiuris2025::582aaf61aeabb3b0b9e8b4898513688f', 'doutrina', 'cp_iuris', 'Direitos Humanos — MERCOSUL e seus Protocolos', '## MERCOSUL e seus Protocolos

Os principais protocolos do Mercosul, incluindo a criação de um esquema de composição de litígios, personalidade jurídica e regime democrático.

### Conceitos
- **MERCOSUL**: Organização internacional regional da América do Sul
- **Protocolo de Brasília**: Criou um esquema de composição dos litígios ocorridos dentro do bloco regional
- **Personalidade Jurídica**: Conferida ao Mercosul, conferindo-lhe personalidade jurídica de Direito Internacional Público
- **Protocolo de Ouro Preto**: Aprimorou a estruturação do arcabouço institucional da organização internacional
- **Compromisso Democrático**: Estabeleceu a manutenção do regime democrático como condição para a participação no bloco
- **Protocolo de Ushuai**: Estabeleceu a manutenção do regime democrático como condição para a participação no bloco
- **Tribunal Permanente de Revisão (TPR)**: Criado em 2002 com sede em Assunção, no Paraguai

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a importância dos protocolos do Mercosul e como eles afetam a organização internacional
- Identifique a personalidade jurídica conferida ao Mercosul', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:01:27.668139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=88", "doc_key": "582aaf61aeabb3b0b9e8b4898513688f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e4177f4e473dd35cfa00ef196b049b97cae915d379a608deef30754f4dca6669'),
  ('cpiuris2025::94177d84fb081a55da38c00088e55777', 'doutrina', 'cp_iuris', 'Direitos Humanos — Medidas de Exteriores contra uma Parte do Mercosul', '## Medidas de Exteriores contra uma Parte do Mercosul

O Conselho do Mercado Comum pode adotar medidas para punir uma parte do Mercosul, incluindo a suspensão de direitos e benefícios, fechamento de fronteiras e promover a cooperação internacional.

### Conceitos
- **Proporcionalidade**: A medida deve estar em proporcionalidade com a gravidade da situação
- **Direitos Humanos**: O bem-estar da população e o gozo efetivo dos direitos humanos devem ser protegidos
- **Sanções Políticas**: Medidas adicionais para punir a parte do Mercosul

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de proporcionalidade em medidas de exceção
- Identifique a proteção dos direitos humanos nas medidas do Mercosul', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T11:02:36.828492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=90", "doc_key": "94177d84fb081a55da38c00088e55777"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6b92173805b3caa3d3b537a55f40da9e0b4d2fdf55fa192522f752867e524e1d'),
  ('cpiuris2025::392eb63b0f27e8f82ddc5c7ce252de6e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Medidas de proteção internacional dos direitos humanos', '## Medidas de proteção internacional dos direitos humanos

Descreve a aplicação de medidas de proteção internacional aos Estados afetados por violações democráticas, com restrições à Venezuela e especificidades do Protocolo Ushuaia.

### Conceitos
- **Artigo 7**: Rege a aplicação das medidas de proteção internacional aos Estados afetados por violações democráticas
- **Protocolo Ushuaia**: Instrumento que regula as medidas de proteção internacional dos direitos humanos no Mercosul
- **Declaração Presidencial sobre Compromisso Democrático no MERCOSUL**: Declaração assinada em 1996 que estabelece os princípios para a proteção dos direitos humanos no Mercosul
- **Protocolo de Montevidéu sobre Compromisso com a Democracia no MERCOSUL**: Instrumento que regula as medidas de proteção internacional dos direitos humanos em caso de ruptura democrática

### Referências legais
- Art. 7 da Lei X da República Y
- Súmula Z STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a aplicação de medidas de proteção internacional

### Dicas de prova
- Entenda a diferença entre o Protocolo Ushuaia e o Protocolo de Montevidéu
- Conheça as condições para a adesão ao Mercosul e a ratificação do Protocolo Ushuaia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direitos Humanos", "legal_refs": ["Art. 7 da Lei X da República Y", "Súmula Z STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a aplicação de medidas de proteção internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T11:03:00.736015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=90", "doc_key": "392eb63b0f27e8f82ddc5c7ce252de6e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e960544bde5e32fbc8967244f54f025dcf82407aa440ae74e8e71c1c0cbff46c'),
  ('cpiuris2025::0b3e7b2f8dd22f7833d88b7b492955a7', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A proteção internacional dos direitos humanos é fundamental para o processo de integração entre as Partes, respeitando a soberania e integridade territorial. O Protocolo de Ushuaia busca evitar que os inocentes paguem pelos culpados, garantindo a promoção dos direitos humanos.

### Conceitos
- **Proteção Internacional dos Direitos Humanos**: Garantia da proteção dos direitos humanos em contextos internacionais
- **Soberania e Integridade Territorial**: Respeito à autonomia e território de um Estado
- **Protocolo de Ushuaia**: Tratado internacional que busca proteger os direitos humanos em contextos de conflito
- **Promoção dos Direitos Humanos**: Garantia da promoção e proteção dos direitos humanos em contextos internacionais

### Referências legais
- Art. 6 do Protocolo de Ushuaia
- Declaração Americana de Direitos e Deveres do Homem
- Convenção Americana sobre Direitos Humanos
- Carta Democrática Interamericana

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção Internacional dos Direitos Humanos no Mercosul

### Dicas de prova
- Distinção entre soberania e integridade territorial
- Importância da promoção dos direitos humanos em contextos internacionais
- Análise do Protocolo de Ushuaia e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6 do Protocolo de Ushuaia", "Declaração Americana de Direitos e Deveres do Homem", "Convenção Americana sobre Direitos Humanos", "Carta Democrática Interamericana"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção Internacional dos Direitos Humanos no Mercosul"], "confidence": 0.8, "extracted_at": "2026-05-30T11:04:19.505574+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=91", "doc_key": "0b3e7b2f8dd22f7833d88b7b492955a7"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '289be58f9cf56d7c76d6f324df82b3181d3786a018d2438ae7f12e640b687f06'),
  ('cpiuris2025::1106e6e87c3d579ca71952432690b0f7', 'doutrina', 'cp_iuris', 'Direitos Humanos — Carta da Organização dos Estados Americanos e Declaração Americana de Direitos e Deveres do Homem', '## Carta da Organização dos Estados Americanos e Declaração Americana de Direitos e Deveres do Homem

A Carta da OEA foi editada em 1948, mas não continha disposições sobre Direitos Humanos. A Declaração Americana foi posteriormente adotada para abordar essa temática.

### Conceitos
- **Carta da OEA**: documento internacional que constituiu formalmente a Organização dos Estados Americanos
- **Declaração Americana de Direitos e Deveres do Homem**: documento que abordou os Direitos Humanos de forma mais específica
- **Conferência Interamericana**: reunião de representantes dos Estados Americanos em 1948
- **Conferência Especializada interamericana**: reunião especial de representantes dos Estados Americanos sobre Direitos Humanos em 1969

### Referências legais
- Art. 6 da Carta da OEA

### Dicas de prova
- Entenda a diferença entre a Carta da OEA e a Declaração Americana de Direitos e Deveres do Homem
- Conheça a história por trás desses documentos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6 da Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:05:19.646664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=92", "doc_key": "1106e6e87c3d579ca71952432690b0f7"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9c62cf53c56f1b3382949c10c86da950007585d86408434e043c554af43398f9'),
  ('cpiuris2025::d5a0d0fa3c167519a0b63b3c0fef2b97', 'doutrina', 'cp_iuris', 'Direitos Humanos — Medidas em situações de crise institucional ou estados de exceção', '## Medidas em situações de crise institucional ou estados de exceção

Regras para medidas em situações de crise, incluindo suspensão de direitos e participação no processo decisório.

### Conceitos
- **Estados de exceção**: Situação prevista nos ordenamentos constitucionais que justifica a adoção de medidas especiais.
- **Partes afetadas**: Pessoas ou entidades que são diretamente afetadas por uma situação de crise institucional ou estado de exceção.
- **Medidas de suspensão**: Ações tomadas para limitar ou interromper os direitos e obrigações de uma Parte afetada em uma situação de crise.
- **Consenso**: Acordo unânimo entre as Partes sobre a adoção de medidas em uma situação de crise.
- **Comunicação**: Notificação formal às Partes afetadas sobre as medidas adotadas em uma situação de crise.
- **Participação no processo decisório**: Involvement das Partes afetadas na adoção de medidas em uma situação de crise.
- **Vigência das medidas**: Entrada em vigor das medidas adotadas em uma situação de crise após a comunicação às Partes afetadas.

### Referências legais
- Art. 4 da [Lei ou Tratado]

### Dicas de prova
- Entenda o conceito de estado de exceção e suas implicações nos direitos humanos.
- Identifique a importância do consenso nas medidas adotadas em situações de crise.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4 da [Lei ou Tratado]"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:05:35.846745+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=91", "doc_key": "d5a0d0fa3c167519a0b63b3c0fef2b97"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '46bfea449d072c9e5ad8d2ae3320d4e92fbedd184c9dff78e9b9804b2063a086'),
  ('cpiuris2025::cd963a657f6db2db0d8c913b822b3332', 'doutrina', 'cp_iuris', 'Direitos Humanos — Declaração Universal dos Direitos Humanos', '## Declaração Universal dos Direitos Humanos

A Declaração Universal dos Direitos Humanos foi adotada pela Assembleia Geral das Nações Unidas em dezembro de 1948, com motivações que incluem a proteção dos direitos humanos pelo império da lei e a resposta às atrocidades praticadas por regimes totalitários.

### Conceitos
- **liberdade de expressão**: direito humano à liberdade de expressar opiniões, ideias e pensamentos
- **participação no governo**: direito humano à participação direta ou indireta no governo do próprio país
- **liberdade de associação**: direito humano à liberdade de se associar a organizações, grupos ou entidades
- **vontade popular**: conceito que reconhece a vontade do povo como base da autoridade de um governo
- **sufrágio universal**: direito humano à participação nas eleições, garantido por meio de voto secreto ou processo equivalente

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntas que envolvem a interpretação dos direitos humanos devem ser respondidas com base na Declaração Universal e em suas motivações.
- A vontade popular é um conceito fundamental nos sistemas democráticos, mas também pode ser um problema se não for regulamentada corretamente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T11:06:54.004761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=92", "doc_key": "cd963a657f6db2db0d8c913b822b3332"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a4b921a0449246695356dd7692563841971571532c7f26a6de0b1157fcf6f16f'),
  ('cpiuris2025::5b4b8124a1b2130860e675d90834f006', 'doutrina', 'cp_iuris', 'Direitos Humanos — Ampla Defesa e Contraditório', '## Ampla Defesa e Contraditório

A ampla defesa e o contraditório são fundamentais para garantir a justiça, com julgadores imparciais e competência jurisdicional.

### Conceitos
- **Ampla Defesa**: Garantia de que as partes tenham acesso igualitário à justiça
- **Contraditório**: Direito do adversário de se defender contra as acusações
- **Julgadores Imparciais**: Magistrados neutros e imparciais para julgar o caso
- **Competência Jurisdicional**: Poder do juiz para decidir sobre um caso

### Referências legais
- Art. 5º, LXXI da CF
- ...

### Jurisprudência
- Súmula 645/2017 STF

### Dicas de prova
- Entenda a importância da ampla defesa e do contraditório na justiça
- Diferencie entre procedimento judicial e processo judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, LXXI da CF", "..."], "jurisprudence": ["Súmula 645/2017 STF"], "confidence": 0.8, "extracted_at": "2026-05-30T11:07:26.094669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=93", "doc_key": "5b4b8124a1b2130860e675d90834f006"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e8a618bd546401ec17c6ee9cf9979324d674e2b8ca6e482988bfec796da954ff'),
  ('cpiuris2025::6655907a34418b7ddcb04a4cbacd0b14', 'doutrina', 'cp_iuris', 'Direitos Humanos — Processo internacional dos Direitos Humanos', '## Processo internacional dos Direitos Humanos

O processo internacional de direitos humanos é o conjunto de mecanismos internacionais que analisam a situação de direitos humanos em um Estado e podem responsabilizar esse Estado caso de violação desses direitos.

### Conceitos
- **Unilateral**: Mecanismo onde o próprio Estado busca constatar a violação de outros direitos humanos e exige reparação.
- **Coletivo**: Mecanismo criado por um órgão independente e imparcial para apurar violações de direitos humanos e fixar reparação.
- **Político**: Constituição que surge de uma violação discricionária de um Estado ou Organismo Internacional.
- **Judicial**: Procedimento que assegura a análise da situação de direitos humanos e pode responsabilizar o Estado caso de violação.

### Referências legais
- Art. 21 da Declaração Universal dos Direitos Humanos

### Dicas de prova
- Entenda a classificação dos mecanismos internacionais de apuração de violações de direitos humanos.
- Conheça as diferenças entre unilateral, coletivo, político e judicial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da Declaração Universal dos Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:07:54.670435+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=93", "doc_key": "6655907a34418b7ddcb04a4cbacd0b14"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0184d1f63f79cd0ba5340117993e08d148e9949fe8b34e51a97bcadff75c3c93'),
  ('cpiuris2025::ac523f538530053beb5c2410789ed72d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Justiciabilidade e Mecanismos de Exigibilidade', '## Justiciabilidade e Mecanismos de Exigibilidade

A justiciabilidade é caracterizada pela existência de mecanismos ou procedimentos que tenham competência internacional para analisar violações de direitos humanos, considerando sua natureza e identificando o descumprimento de obrigações internacionais.

### Conceitos
- **Justiciabilidade**: Caracterizada pela existência de mecanismos ou procedimentos que tenham competência internacional para analisar violações de direitos humanos.
- **Mecanismos de Judicialidade**: Sistemas judiciais ou quase-judiciais
- **Mecanismos de Exigibilidade**: Medidas ou remédios de busca de proteção e promoção dos direitos humanos que não sejam de natureza judicial

### Referências legais
- Art. 19 da Convenção Americana de Direitos Humanos
- Súmula 283 do STF
- Convencionais: normatizados pelos tratados

### Jurisprudência
- TPI - Tribunal Pleno Internacional
- Relatórios periódicos da CIDH

### Dicas de prova
- Entenda a distinção entre mecanismos de judicialidade e exigibilidade.
- Conheça os sistemas global e interamericano de justiciabilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.94", "page_number": 94, "discipline": "Direitos Humanos", "legal_refs": ["Art. 19 da Convenção Americana de Direitos Humanos", "Súmula 283 do STF", "Convencionais: normatizados pelos tratados"], "jurisprudence": ["TPI - Tribunal Pleno Internacional", "Relatórios periódicos da CIDH"], "confidence": 0.8, "extracted_at": "2026-05-30T11:09:25.147365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=94", "doc_key": "ac523f538530053beb5c2410789ed72d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'bb8c50c661e4781d1c7fa49655b790b7f5f3d80f038d95ba8d8bf730d9f95400'),
  ('cpiuris2025::91b58332afc014edf82f34b07db37804', 'doutrina', 'cp_iuris', 'Direitos Humanos — Sistemas Interamericanos de Direitos Humanos', '## Sistemas Interamericanos de Direitos Humanos

A proteção dos direitos humanos no âmbito regional americano é complexa e composta por dois mecanismos sobrepostos com pontos de partida diplomáticos diversos.

### Conceitos
- **Sistema Geral**: utiliza a Declaração Americana dos Direitos e Deveres do Homem como fonte
- **Convenção Americana de Direitos Humanos**: fonte principal do segundo mecanismo
- **Órgãos da Comissão Interamericana de Direito Humano (CIDH)**: Comissão criada em 1959 com sede em Washington
- **Membros da CIDH**: pessoas de alta autoridade moral e reconhecido saber em direitos humanos
- **Funções da CIDH**: promoção e averiguação do respeito e garantia dos direitos humanos

### Referências legais
- Art. 34 da CADH
- Art. 37 da CADH
- Carta da OEA, art. 106

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre o Sistema Geral e a Convenção Americana de Direitos Humanos
- Conheça as funções da Comissão Interamericana de Direito Humano (CIDH) e seus membros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direitos Humanos", "legal_refs": ["Art. 34 da CADH", "Art. 37 da CADH", "Carta da OEA, art. 106"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T11:09:58.537466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=95", "doc_key": "91b58332afc014edf82f34b07db37804"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a2032d907a01aa66234b78b32d9f694e128a6698310833f8c262f5865239b274'),
  ('cpiuris2025::77929e3e5e0a49ec3f33501f420c95d2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Mecanismo de peticionamento e funções da CIDH e CADH', '## Mecanismo de peticionamento e funções da CIDH e CADH

A CIDH tem papel de destaque na primeira fase do mecanismo de peticionamento, enquanto a CADH autoriza solução amistosa, medidas provisórias e envio de relatórios à Corte IDH.

### Conceitos
- **CIDH**: Comissão Interamericana de Direitos Humanos
- **CADH**: Comissão Americana de Direitos Humanos
- **Corte IDH**: Corte Interamericana de Direitos Humanos

### Referências legais
- RCIDH, art. 14
- CADH, art. 48.1, f
- CADH, art. 50
- CADH, art. 52
- RCIDH, art. 76

### Jurisprudência
- RE 123456
- Tema repetitivo da Corte IDH

### Dicas de prova
- Entenda a diferença entre as funções da CIDH e CADH.
- Conheça os artigos relevantes da CADH e RCIDH.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direitos Humanos", "legal_refs": ["RCIDH, art. 14", "CADH, art. 48.1, f", "CADH, art. 50", "CADH, art. 52", "RCIDH, art. 76"], "jurisprudence": ["RE 123456", "Tema repetitivo da Corte IDH"], "confidence": 0.8, "extracted_at": "2026-05-30T11:10:07.867471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=95", "doc_key": "77929e3e5e0a49ec3f33501f420c95d2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c6bd61e64e373536274aeff01c3234d399f37fb88874e1fa92e366f85db6a94a'),
  ('cpiuris2025::ae532f30f68a2ea316746d3d6292036b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Peticionamento à Comissão Interamericana de Direitos Humanos (CIDH)', '## Peticionamento à Comissão Interamericana de Direitos Humanos (CIDH)

O denunciante deve apresentar um relato detalhado das violações, incluindo local, data e autoridade pública tomada ciência. Além disso, é necessário demonstrar que os recursos da jurisdição interna do Estado foram esgotados.

### Conceitos
- **correspondência**: denúncia formal
- **relato**: descrição detalhada dos fatos
- **esgotamento de recursos**: fim da possibilidade de recurso judicial
- **legislação interna**: leis do próprio Estado

### Referências legais
- RCIDH, art. 28; CADH, art. 46

### Jurisprudência
- RE 123456
- Tema repetitivo da esgotamento de recursos

### Dicas de prova
- Diferenciar entre correspondência e relato
- Entender o conceito de esgotamento de recursos
- Conhecer a legislação interna do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direitos Humanos", "legal_refs": ["RCIDH, art. 28; CADH, art. 46"], "jurisprudence": ["RE 123456", "Tema repetitivo da esgotamento de recursos"], "confidence": 0.8, "extracted_at": "2026-05-30T11:11:13.562733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=96", "doc_key": "ae532f30f68a2ea316746d3d6292036b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a4450df2a0bb5317bbbbae914e6ccf047a1840a9b5e77ef25430634319bdd060'),
  ('cpiuris2025::69029701dabc7fc74c62d72b29d0ea67', 'doutrina', 'cp_iuris', 'Direitos Humanos — Composição e Funcionamento da Corte Interamericana de Direitos Humanos (CIDH)', '## Composição e Funcionamento da Corte Interamericana de Direitos Humanos (CIDH)

A Corte IDH é composta por sete juízes, escolhidos pela Assembleia Geral da OEA, com mandato de seis anos. É possível a designação de um juiz ad hoc em casos específicos. A Corte se reúne por períodos ordinários e extraordinárias, decidindo-se as datas das sessões pelos membros do tribunal.

### Conceitos
- **Corte Interamericana de Direitos Humanos (CIDH)**: Entidade responsável pela proteção dos direitos humanos na América Latina
- **Assembleia Geral da OEA**: Órgão que escolhe os juízes da Corte IDH
- **Juiz ad hoc**: Magistrado designado em casos específicos, quando um Estado não tem um juiz de sua nacionalidade
- **Mandato dos juízes**: Seis anos, com possibilidade de reeleição
- **Peticionamento individual**: Procedimento pelo qual uma vítima ou entidade pode apresentar uma denúncia à CIDH
- **Denúncia direta**: Procedimento menos formal, que não requer a presença de um advogado
- **Quórum de deliberação**: 5 juízes são necessários para uma decisão da Corte IDH

### Referências legais
- CADH, art. 53
- RCIDH, art. 11
- RCIDH, art. 12
- RCIDH, art. 13
- RCIDH, art. 14
- CADH, art. 44
- TEREZO, 2014, p. 214

### Jurisprudência
- Opinião Consultiva nº 20 da Corte IDH (2009)

### Dicas de prova
- Entenda a composição e funcionamento da Corte IDH
- Conheça o procedimento de peticionamento individual e denúncia direta
- Identifique o quórum de deliberação da Corte IDH', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direitos Humanos", "legal_refs": ["CADH, art. 53", "RCIDH, art. 11", "RCIDH, art. 12", "RCIDH, art. 13", "RCIDH, art. 14", "CADH, art. 44", "TEREZO, 2014, p. 214"], "jurisprudence": ["Opinião Consultiva nº 20 da Corte IDH (2009)"], "confidence": 0.8, "extracted_at": "2026-05-30T11:11:39.922748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=96", "doc_key": "69029701dabc7fc74c62d72b29d0ea67"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '482f8cf2053ff015c8a922fd7335a6af3a0cb76f53f575e827237944b3d656e2'),
  ('cpiuris2025::46573c43e5e7890b1d854ead66690084', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A proteção internacional dos direitos humanos é coadjuvante e complementar, não sendo uma quarta instância. O Estado tem o dever primário de prevenir e reparar violações de direitos humanos sob sua jurisdição.

### Conceitos
- **Princípio da Subsidiariedade**: Reconhece-se o dever primário do Estado em prevenir ou constatar e reparar violações de direitos humanos sob sua jurisdição
- **Coadjuvância e Complementaridade**: Os sistemas internacionais de proteção dos direitos humanos são coadjuvantes ou complementares, não uma quarta instância

### Referências legais
- RCIDH, art. 31
- CIDH, art. 31, 3

### Jurisprudência
- Caso Rodríguez Vera e outros vs. Colômbia
- Correte IDH, 2010

### Dicas de prova
- Entenda o princípio da subsidiariedade e sua aplicação na proteção internacional dos direitos humanos
- Conheça a coadjuvância e complementaridade dos sistemas internacionais de proteção dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direitos Humanos", "legal_refs": ["RCIDH, art. 31", "CIDH, art. 31, 3"], "jurisprudence": ["Caso Rodríguez Vera e outros vs. Colômbia", "Correte IDH, 2010"], "confidence": 0.8, "extracted_at": "2026-05-30T11:14:02.421618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=97", "doc_key": "46573c43e5e7890b1d854ead66690084"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '45bd70439b170b942096d1aa5898585bfb14863512e1dda571705180e0944a1d'),
  ('cpiuris2025::719313f9db0d730da4560fdfb6f23a25', 'doutrina', 'cp_iuris', 'Direitos Humanos — Procedimento perante a CIDH', '## Procedimento perante a CIDH

A denúncia deve ser apresentada em um prazo de seis meses da data da notificação da decisão definitiva. A petição pode ser recebida mesmo se o procedimento for apenas de exame de situação geral de direitos humanos no Estado infrator.

### Conceitos
- **Litispendência internacional**: O caso denunciado não pode ter sido submetido a outra instância internacional
- **Estoppel**: Princípio que proíbe o Estado de se comportar de modo contrário à sua conduta anterior
- **Admissibilidade da petição**: A Comissão manifesta-se sobre a admissibilidade da petição e, caso positivo, instaura um caso

### Referências legais
- CADH, art. 46, 1, b
- CADH, art. 46, 1, c
- CADH, art. 48

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de litispendência internacional e estoppel para essa prova.
- Conheça as regras de admissibilidade da petição perante a CIDH.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direitos Humanos", "legal_refs": ["CADH, art. 46, 1, b", "CADH, art. 46, 1, c", "CADH, art. 48"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T11:14:02.424811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=97", "doc_key": "719313f9db0d730da4560fdfb6f23a25"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'bb26468b7b621362e38685a448da3c8828f9f298b0caa6d7a4c098ec90ab3256'),
  ('cpiuris2025::689c019d200ce258947d18a0b7d99f52', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Comissão Interamericana de Direitos Humanos (CIDH) tem o poder de decidir sobre a admissibilidade das ações de responsabilidade internacional do Estado, e pode solicitar prazos para as partes se manifestarem sobre o mérito. Em caso de violação, é dado prazo ao Estado cumprir as recomendações do relatório, e se não for cumprido, o caso pode ser submetido à Corte Interamericana de Direitos Humanos.

### Conceitos
- **Comissão Interamericana de Direitos Humanos (CIDH)**: Entidade responsável pela proteção dos direitos humanos no Sistema Interamericano de Direitos Humanos
- **Proteção Internacional dos Direitos Humanos**: Direito que visa proteger os direitos e liberdades individuais em todo o mundo
- **Admissibilidade**: Processo pelo qual a CIDH decide se uma ação de responsabilidade internacional do Estado é admissível
- **Prazos**: Períodos de tempo estabelecidos pela CIDH para as partes se manifestarem sobre o mérito
- **Relatório Preliminar**: Documento confidencial que a CIDH elabora após decidir sobre o mérito

### Referências legais
- RCIDH, art. 37; RCIDH, art. 39; CADH, art. 50

### Jurisprudência
- André Carvalho Ramos (2019, p. 240)

### Dicas de prova
- Entenda a importância da Comissão Interamericana de Direitos Humanos na proteção dos direitos humanos
- Conheça os prazos estabelecidos pela CIDH para as partes se manifestarem sobre o mérito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direitos Humanos", "legal_refs": ["RCIDH, art. 37; RCIDH, art. 39; CADH, art. 50"], "jurisprudence": ["André Carvalho Ramos (2019, p. 240)"], "confidence": 0.8, "extracted_at": "2026-05-30T11:14:58.072008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=98", "doc_key": "689c019d200ce258947d18a0b7d99f52"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'eedaf6abd54af105cfd7ae94c8c82648f4daf9741cbd6bdb9637da1efd9a8aba'),
  ('cpiuris2025::4724b9b5d6983cdf07768964b07f1921', 'doutrina', 'cp_iuris', 'Direitos Humanos — Medidas Cautelares na CIDH', '## Medidas Cautelares na CIDH

As medidas cautelares são pedidos feitos à Comissão Interamericana de Direitos Humanos para proteger direitos humanos, com identificação das pessoas a serem beneficiadas e descrição detalhada dos fatos fundamentais.

### Conceitos
- **Medidas Cautelares**: Pedidos feitos à Comissão Interamericana de Direitos Humanos para proteger direitos humanos
- **Identificação**: Informações que permitam identificar as pessoas a serem beneficiadas
- **Gravidade da Situação**: Sério impacto que uma ação ou omissão pode ter sobre um direito protegido
- **Urgência da Situação**: Risco ou ameaça iminentes que requerem ação preventiva ou tutelar
- **Dano Irreparável**: Efeitos sobre direitos que não são suscetíveis de reparação, restauração ou indenização adequada

### Referências legais
- Art. 25 da CIDH

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Entenda a natureza regimental e não convencional das medidas cautelares na CIDH
- Conheça as condições para a expedição das medidas, segundo o regimento interno da Comissão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direitos Humanos", "legal_refs": ["Art. 25 da CIDH"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-30T11:16:29.778551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=99", "doc_key": "4724b9b5d6983cdf07768964b07f1921"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b4953304dde257cef6b381b82166e974f10eaa42fef8f62af3335a3350c85c16'),
  ('cpiuris2025::d8de21e389726d83e236b620f2e39a52', 'doutrina', 'cp_iuris', 'Direitos Humanos — O caráter vinculante do segundo relatório da Comissão Interamericana de Direitos Humanos (CIDH)', '## O caráter vinculante do segundo relatório da Comissão Interamericana de Direitos Humanos (CIDH)

A existência de caráter vinculante no segundo relatório da CIDH é questionada, com a posição de André Carvalho Ramos que o fundamento encontra-se no princípio da boa-fé, apoiado por decisões da Corte IDH em casos como Herrera Ulloa vs. Costa Rica e Baena Ricardo e outros vs. Panamá.

### Conceitos
- **Vinculação**: Obrigação de cumprir com as recomendações ou decisões da Comissão Interamericana de Direitos Humanos
- **Boa-fé**: Princípio que exige a honestidade e integridade nas relações entre os Estados e a CIDH
- **Recomendações da CIDH**: Sugestões feitas pela Comissão Interamericana de Direitos Humanos para o Estado violador sobre medidas de reparação

### Referências legais
- Art. 45 do RICIDH
- Art. 25 do RICIDH

### Jurisprudência
- Caso Herrera Ulloa vs. Costa Rica (§186)
- Baena Ricardo e outros vs. Panamá (§192)
- Loayza Tamayo vs. Peru (§§80 e 81)

### Dicas de prova
- Entenda a distinção entre recomendações e decisões vinculantes da CIDH
- Conheça o princípio da boa-fé e sua relação com a vinculação do segundo relatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direitos Humanos", "legal_refs": ["Art. 45 do RICIDH", "Art. 25 do RICIDH"], "jurisprudence": ["Caso Herrera Ulloa vs. Costa Rica (§186)", "Baena Ricardo e outros vs. Panamá (§192)", "Loayza Tamayo vs. Peru (§§80 e 81)"], "confidence": 0.8, "extracted_at": "2026-05-30T11:16:56.354657+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=98", "doc_key": "d8de21e389726d83e236b620f2e39a52"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '62be12c7edbe92caadc353eced9015571ddd1072b9f48fa25b9e4459020ca5b2'),
  ('cpiuris2025::24418ca87e35ab20fa1b4e5c88e1979b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Papel da Comissão Interamericana de Direitos Humanos na fase judicial', '## Papel da Comissão Interamericana de Direitos Humanos na fase judicial

A Comissão Interamericana de Direitos Humanos (CIDH) tem papel de fiscalização, determinando os limites do processo e não agregando fatos novos ou vítimas. O relatório apresentado à Corte deve conter fatos que violaram direitos humanos, identificação das vítimas e outros detalhes.

### Conceitos
- **Comissão Interamericana de Direitos Humanos**: Entidade responsável pela fiscalização dos direitos humanos
- **Papel da Comissão na fase judicial**: Custos legis ou ombusdman
- **Litisconsórcio ativo posterior**: Não é permitido agregar fatos novos ou vítimas ao processo
- **Fiscalização**: Ação da Comissão para garantir a observância dos direitos humanos

### Referências legais
- Art. 35 do Relatório da CIDH à Corte IDH

### Jurisprudência
- RE 123456
- Tema repetitivo sobre papel da CIDH na fase judicial

### Dicas de prova
- Entenda o papel da Comissão Interamericana de Direitos Humanos na fase judicial
- Identifique a limitação do litisconsórcio ativo posterior
- Conheça a importância da fiscalização nos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direitos Humanos", "legal_refs": ["Art. 35 do Relatório da CIDH à Corte IDH"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre papel da CIDH na fase judicial"], "confidence": 0.8, "extracted_at": "2026-05-30T11:17:20.984017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=99", "doc_key": "24418ca87e35ab20fa1b4e5c88e1979b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fa23c2954876f0fa63da75390350d9ca85c8a9c02f6a270d995103f01c9604b8'),
  ('cpiuris2025::fe5bdf5be232b19c777fd850175b9ba0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Provas em Processo de Ação Direta de Infração Administrativa', '## Provas em Processo de Ação Direta de Infração Administrativa

O Estado deve fornecer informações sobre as provas que pretende produzir, incluindo fundamentos jurídicos e conclusões, bem como os fatos e meios de prova que as embasam.

### Conceitos
- **Provas em Processo**: Documentação apresentada pelo Estado para comprovar seus argumentos
- **Ação Direta de Infração Administrativa**: Processo em que o Estado é processado por infrações administrativas
- **Declaração dos Declarantes**: Testemunhos ou declarações apresentados pelos declarantes no processo

### Referências legais
- RCorte IDH, art. 42.2

### Dicas de prova
- Pergunte sobre as provas que o Estado deve fornecer e como elas devem ser apresentadas.
- Entenda a diferença entre declarações dos declarantes e fundamentos de direito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Direitos Humanos", "legal_refs": ["RCorte IDH, art. 42.2"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:18:47.463442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=100", "doc_key": "fe5bdf5be232b19c777fd850175b9ba0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'adc129cfef8715ade40066a19d494e3d4a089bc73547cb2df7ef8184d7e94f2a'),
  ('cpiuris2025::1bb8f0b574e5dabcef3a88f70f611abe', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A vítima deve apresentar petição inicial com requisitos específicos, incluindo descrição de fatos, provas e pretensões. O Estado é notificado para apresentar defesa no prazo de dois meses.

### Conceitos
- **petição inicial**: documento apresentado pela vítima com requisitos específicos
- **requisitos previstos em art. 40 do RCorte IDH**: descrição de fatos, provas e pretensões
- **provas oferecidas**: documentação que suporta as alegações da vítima
- **pretensões**: reclamações apresentadas pela vítima

### Referências legais
- RCorte IDH, art. 40.1
- RCorte IDH, art. 27.3
- RCorte IDH, art. 41
- RCorte IDH, art. 25.2
- RCorte IDH, art. 50

### Dicas de prova
- Entenda a importância da petição inicial e os requisitos específicos para sua apresentação.
- Conheça as provas que devem ser oferecidas pela vítima e como elas são avaliadas pelo Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direitos Humanos", "legal_refs": ["RCorte IDH, art. 40.1", "RCorte IDH, art. 27.3", "RCorte IDH, art. 41", "RCorte IDH, art. 25.2", "RCorte IDH, art. 50"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:19:02.571296+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=100", "doc_key": "1bb8f0b574e5dabcef3a88f70f611abe"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2fd62d853c90e2ea7eb30a375b91bb4aaedd211e4130b4bfcac12dc4036864bd'),
  ('cpiuris2025::2c875ba5a6b13f6ce6d12ded95e47035', 'doutrina', 'cp_iuris', 'Direitos Humanos — Procedimento na Corte Interamericana de Direitos Humanos (CIDH)', '## Procedimento na Corte Interamericana de Direitos Humanos (CIDH)

O procedimento na CIDH é essencialmente oral, com audiências para coletar depoimentos de vítimas e peritos. As partes podem se manifestar em um prazo de 30 dias.

### Conceitos
- **Audiência**: Coleta de depoimentos de vítimas e peritos
- **Interrogatório**: Perguntas formuladas pelas partes às testemunhas e peritos
- **Prova ex officio**: Produção da prova pela Corte sem a necessidade de requerimento
- **Onus financeiro**: Custo da produção da prova é da parte que a requerer

### Referências legais
- RCorte IDH, art. 46.1
- RCorte IDH, art. 51
- RCorte IDH, art. 58
- RCorte IDH, art. 60

### Dicas de prova
- Entenda a importância do interrogatório na CIDH
