  ('cpiuris2025::ccde8aeadf6bde21fbd721d032716c8b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Medidas Provisórias em Caso de Violação de Direitos Humanos', '## Medidas Provisórias em Caso de Violação de Direitos Humanos

A Corte pode tomar medidas provisórias para evitar danos irreparáveis às pessoas, especialmente em casos de extrema gravidade e urgência. Essas medidas podem ser tomadas a pedido da vítima ou da Comissão, ou ex officio.

### Conceitos
- **Medidas Provisórias**: Ato provisório do Estado para evitar danos irreparáveis às pessoas
- **Extrema Gravidade e Urgência**: Situção que justifica a tomada de medidas provisórias para evitar danos irreparáveis
- **Corte**: Entidade responsável por tomar decisões sobre violações de direitos humanos
- **Comissão**: Órgão que pode provocar a Corte a agir em determinadas situações

### Referências legais
- Art. 63 da Convenção sobre Direitos Humanos

### Dicas de prova
- Entenda o conceito de medidas provisórias e suas implicações
- Identifique a situação que justifica a tomada dessas medidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direitos Humanos", "legal_refs": ["Art. 63 da Convenção sobre Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:20:57.723315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=101", "doc_key": "ccde8aeadf6bde21fbd721d032716c8b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ad5fd9634941eb6f77f3ff0c1103b210c5918006c0cad8fd7263ddbbc9c6ae72'),
  ('cpiuris2025::bdf0961c015096a46804d9887f484629', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de convencionalidade e tratados internacionais', '## Controle de convencionalidade e tratados internacionais

O controle de convencionalidade é um conceito que se refere à análise da compatibilidade das leis internas com os tratados internacionais, especialmente em relação à proteção dos direitos humanos. A adequação dos Estados aos termos dos tratados pode evitar a responsabilização internacional posterior.

### Conceitos
- **Controle de convencionalidade**: Análise da compatibilidade das leis internas com os tratados internacionais
- **Tratado internacional**: Acordo entre Estados que visa proteger direitos humanos
- **Responsabilização internacional**: Consequência de não cumprir com os termos de um tratado internacional

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- OC nº 1/82
- RE 123456

### Dicas de prova
- Entenda a importância do controle de convencionalidade na proteção dos direitos humanos
- Conheça as implicações da responsabilização internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["OC nº 1/82", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T11:21:27.942410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=102", "doc_key": "bdf0961c015096a46804d9887f484629"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0fa914d1d8dbecc6763cfe3c9624f69358a613769dee7d5e9a551d9d0774eb6c'),
  ('cpiuris2025::a9e416cbbb43c50678f2d56b325017b2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência da Corte Interamericana de Direitos Humanos', '## Competência da Corte Interamericana de Direitos Humanos

A Corte Interamericana de Direitos Humanos tem competência para emitir pareceres sobre a interpretação das normas da Convenção Americana dos Direitos Humanos (CADH) e outros tratados de direitos humanos aplicáveis aos Estados americanos.

### Conceitos
- **Competência**: A capacidade ou autoridade para agir em um determinado assunto
- **Jurisdição Consultiva**: O direito da Corte de dar opiniões consultivas sobre questões jurídicas internacionais
- **Interpretação**: A ação de entender ou explicar o significado de uma norma jurídica
- **Convenção Americana dos Direitos Humanos (CADH)**: Um tratado internacional que protege os direitos humanos nos Estados americanos
- **Competência Universal**: A capacidade de agir em um determinado assunto sem restrições geográficas
- **Parecer Consultivo**: Um documento que apresenta a opinião da Corte sobre uma questão jurídica específica
- **Interpretação Dinâmica e Evolutiva**: A capacidade da Corte de interpretar as normas jurídicas de forma flexível e adaptável ao tempo

### Referências legais
- Art. 64 da CADH
- Opinião Consultiva nº 2/82 da Corte IDH

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a competência da Corte Interamericana de Direitos Humanos

### Dicas de prova
- Entenda a competência da Corte Interamericana de Direitos Humanos e sua capacidade de emitir pareceres consultivos
- Destaque a importância da interpretação dinâmica e evolutiva das normas jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direitos Humanos", "legal_refs": ["Art. 64 da CADH", "Opinião Consultiva nº 2/82 da Corte IDH"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a competência da Corte Interamericana de Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T11:22:29.981649+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=102", "doc_key": "a9e416cbbb43c50678f2d56b325017b2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '413e8e65737456210e3202d04b6b8595383778c90beec421c0dd1313d1ed1ec3'),
  ('cpiuris2025::e9ff9a6bd5cb2b0e29c38f7cd7648613', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade', '## Controle de Convencionalidade

A teoria do controle de convencionalidade desenvolvida pela Corte Interamericana de Direitos Humanos (Corte IDH) e pela doutrina internacionalista sobre o tema é diferente da conceituação convencional apresentada na doutrina pátria, que é positivista e formalista.

### Conceitos
- **Convencionalidade**: Relação normativa e valorativa entre as normas internacionais de proteção dos direitos humanos e o comportamento do Estado
- **Positivismo**: Pressuposto de que apenas tratados internacionais são fontes formais do Direito Internacional
- **Formalismo**: Critério de validade formal hierárquico para resolver as antinomias normativas

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo do controle de convencionalidade

### Dicas de prova
- Entenda a diferença entre a teoria do controle de convencionalidade e a conceituação convencional apresentada na doutrina pátria
- Conheça os pressupostos do positivismo e do formalismo no contexto do direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do controle de convencionalidade"], "confidence": 0.8, "extracted_at": "2026-05-30T11:23:24.787627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=103", "doc_key": "e9ff9a6bd5cb2b0e29c38f7cd7648613"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6ed6786afb92d3bdf69a98a0c7085ab09633bb103af6a859cc8b69117551b948'),
  ('cpiuris2025::506b103e8e30a48a18196e39f43b22c4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade', '## Controle de Convencionalidade

Análise de compatibilidade de condutas internas com normas do DIDH, não restrita ao SIDH ou Corte IDH.

### Conceitos
- **Controle de Convencionalidade**: Análise de compatibilidade de atos com normas internacionais de proteção dos direitos humanos
- **Compatibilidade**: Relação entre uma conduta e as normas do DIDH
- **Justiciabilidade**: Conceito que confunde-se com o controle de convencionalidade no plano internacional
- **Sistema Interamericano de Direitos Humanos (SIDH)**: Organismo que regula a proteção dos direitos humanos na América
- **Corte Internacional de Justiça**: Entidade responsável por resolver disputas internacionais

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- A. S. Diallo (Guiné vs. R. D. Congo)

### Dicas de prova
- Entenda a distinção entre controle de convencionalidade e justiciabilidade.
- Conheça o âmbito geográfico dos sistemas de proteção específica de direitos humanos.
- Aprenda a aplicar as normas do DIDH em contextos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "A. S. Diallo (Guiné vs. R. D. Congo)"], "confidence": 0.8, "extracted_at": "2026-05-30T11:23:57.007970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=103", "doc_key": "506b103e8e30a48a18196e39f43b22c4"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '445b98c44aeb02c89b4b3a46e49ee6474c37f856384e1bb3b6bdc45afe3c6372'),
  ('cpiuris2025::7b4a43a76dc2b2416477beb16dc52f24', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade Internacional', '## Controle de Convencionalidade Internacional

O controle de convencionalidade internacional pode ser feito por órgãos políticos, judiciais e quase-judiciais. Em âmbito da OEA, o controle de natureza política é exercido pela Assembleia Geral, que tem competência para decidir ações e políticas da organização.

### Conceitos
- **Controle de Convencionalidade**: Procedimento pelo qual um Estado é responsabilizado internacionalmente por não cumprir com os tratados de direitos humanos
- **Assembleia Geral da OEA**: Órgão detentor de competência para decidir ações e políticas da Organização dos Estados Americanos
- **Comissão Interamericana de Direitos Humanos**: Órgão quase-judicial com competência para recebimento de peticionamento individual tanto pelo sistema da CADH quanto da Carta da OEA
- **Corte Interamericana de Direitos Humanos**: Órgão jurisdicional do sistema dos direitos humanos interamericanos

### Referências legais
- Art. 53 e 54 da Carta da OEA
- Resolução nº 1/91 da Assembleia Geral da OEA

### Jurisprudência
- Caso Cabrera García e Montiel Flores vs. México (CORTE IDH, 2010)

### Dicas de prova
- Distinção entre controle de convencionalidade internacional e controle de convencionalidade nacional
- Entendimento do papel da Assembleia Geral da OEA no controle de convencionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Direitos Humanos", "legal_refs": ["Art. 53 e 54 da Carta da OEA", "Resolução nº 1/91 da Assembleia Geral da OEA"], "jurisprudence": ["Caso Cabrera García e Montiel Flores vs. México (CORTE IDH, 2010)"], "confidence": 0.8, "extracted_at": "2026-05-30T11:24:53.104851+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=104", "doc_key": "7b4a43a76dc2b2416477beb16dc52f24"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '18fa5cd1058cb588c2e72a76488f4482c38e912f0abcef1f9172a8aea0ebc5ae'),
  ('cpiuris2025::f3916a22c29cb75fb0b6d7f933d337f8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade', '## Controle de Convencionalidade

O controle convencionalidade é repressivo, realizado após a perfectibilização do ato, e não vinculante em competência consultiva da Corte IDH.

### Conceitos
- **Repressivo**: Caracteriza o controle convencionalidade como uma medida que reage a um ato já realizado
- **Vinculante**: Efeito jurídico que se produz quando a Corte IDH declara a convencionalidade de uma norma ou ato administrativo interno de um Estado
- **Aferição**: Processo de avaliação da convencionalidade de uma norma ou ato administrativo interno de um Estado, sem efeitos jurídicos vinculantes

### Referências legais
- Art. 102 da Constituição Federal
- Súmula Nº 32 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Controle de Convencionalidade

### Dicas de prova
- Diferenciação entre controle repressivo e aferição
- Vinculação ou não da Corte IDH em sua competência consultiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Direitos Humanos", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula Nº 32 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Controle de Convencionalidade"], "confidence": 0.8, "extracted_at": "2026-05-30T11:24:55.342905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=104", "doc_key": "f3916a22c29cb75fb0b6d7f933d337f8"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a4abb5f4643482ac3668df2941101c19e5702bd9977fd5b27dbb4c03226b9b2b'),
  ('cpiuris2025::65ffb2a31c033ee44399d0effd598023', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência Voluntária da Corte IDH', '## Competência Voluntária da Corte IDH

A competência voluntária da Corte IDH permite que os Estados membros consultem a Corte sobre a interpretação de tratados internacionais de proteção dos direitos humanos, bem como sobre a compatibilidade de suas leis internas com esses tratados.

### Conceitos
- **Competência Voluntária**: A capacidade dos Estados membros de consultar a Corte IDH sobre questões relacionadas à interpretação e aplicação dos tratados internacionais de proteção dos direitos humanos.
- **Interpretação de Tratados**: O processo de compreensão e aplicação dos termos e disposições de um tratado internacional de proteção dos direitos humanos.
- **Compatibilidade de Leis Internas**: A verificação se as leis internas de um Estado-membro são compatíveis com os tratados internacionais de proteção dos direitos humanos.

### Referências legais
- Artigo 64 da CADH

### Jurisprudência
- Opinião Consultiva nº 5/85
- Opinião Consultiva nº 3/83

### Dicas de prova
- Entenda a distinção entre controle prévio e controle de convencionalidade posterior.
- Conheça a importância da compatibilidade de leis internas com tratados internacionais de proteção dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direitos Humanos", "legal_refs": ["Artigo 64 da CADH"], "jurisprudence": ["Opinião Consultiva nº 5/85", "Opinião Consultiva nº 3/83"], "confidence": 0.8, "extracted_at": "2026-05-30T11:27:34.730698+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=105", "doc_key": "65ffb2a31c033ee44399d0effd598023"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '26581bccd0a5068183fb30b3e78a4d5712b8e4b0d492c60b19b706937b2568ae'),
  ('cpiuris2025::0f30c195d8483eaed052854c83ebbf14', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proibição da Pena de Morte', '## Proibição da Pena de Morte

A pena de morte não pode ser expandida ou reestabelecida, e é proibido que um Estado formule uma reserva ao dispositivo. A Corte IDH considerou que a promulgação de uma lei contrária às obrigações de um Estado-parte na Convenção constitui uma violação desta.

### Conceitos
- **Pena de Morte**: execução capital
- **Reserva**: exceção ou limitação para um tratado
- **Interpretação**: análise da Corte IDH sobre o significado de um tratado
- **Vinculação**: efeito obrigatório de uma decisão da Corte IDH
- **Responsabilização Internacional**: ação do Estado ou seus agentes perante a comunidade internacional
- **Lei Contrária**: leis que vão contra as obrigações de um Estado-parte na Convenção
- **Amplitude dos Tratados Internacionais**: limites da interpretação da Corte IDH sobre os tratados internacionais

### Referências legais
- Artigo 4 da Convenção
- Artigo 27.2 da CADH
- Artigo 64.1 da CADH
- Artigo 75 da Convenção

### Jurisprudência
- Opinião Consultiva nº 1/82
- Opinião Consultiva nº 14/94
- OC 3/83

### Dicas de prova
- Entenda a importância da interpretação da Corte IDH sobre os tratados internacionais de direitos humanos.
- Conheça as limitações das reservas que um Estado pode formular em relação a um tratado internacional.
- Análise a relação entre a responsabilização internacional e a aplicação de leis contrárias às obrigações de um Estado-parte.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direitos Humanos", "legal_refs": ["Artigo 4 da Convenção", "Artigo 27.2 da CADH", "Artigo 64.1 da CADH", "Artigo 75 da Convenção"], "jurisprudence": ["Opinião Consultiva nº 1/82", "Opinião Consultiva nº 14/94", "OC 3/83"], "confidence": 0.8, "extracted_at": "2026-05-30T11:28:17.285479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=105", "doc_key": "0f30c195d8483eaed052854c83ebbf14"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c62b89903014e2905b67605631238e8f966c92ba0ffd6f3b7fcf3affb6f92dd6'),
  ('cpiuris2025::66d9c2c9ba38e0981531de17aaaafc41', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade Judicial', '## Controle de Convencionalidade Judicial

O controle de convencionalidade judicial é distinto em modelos difuso e concentrado, com a posição dominante na doutrina brasileira sendo mista, combinando sistemas incidental e abstrato.

### Conceitos
- **Controle de Convencionalidade Judicial**: Análise da compatibilidade da conduta interna com as normas de direitos humanos
- **Modelo Difuso**: Controle de convencionalidade judicial que não se restringe a uma única fonte ou norma
- **Modelo Concentrado**: Controle de convencionalidade judicial que se restringe a uma única fonte ou norma
- **Sistema Incidental**: Análise da compatibilidade da conduta interna com as normas de direitos humanos, focando em casos específicos
- **Sistema Abstrato**: Análise da compatibilidade da conduta interna com as normas de direitos humanos, sem focar em casos específicos
- **Bloco ou Parâmetro de Convencionalidade**: Conjunto de normas de direito internacional dos direitos humanos que servem como paradigma para a análise de compatibilidade da conduta interna

### Referências legais
- CADH, Artigo 4
- OC 3/83
- Artigo 2º da Convenção
- OP 21/14
- Carta da OEA
- Carta Democrática Interamericana

### Jurisprudência
- RE 123456
- ADPF 496
- Corte IDH, 2014

### Dicas de prova
- Entenda a distinção entre modelos difuso e concentrado de controle de convencionalidade judicial
- Conheça as posições dominantes na doutrina brasileira sobre o sistema nacional de controle de constitucionalidade
- Identifique o bloco ou parâmetro de convencionalidade em diferentes sistemas internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Direitos Humanos", "legal_refs": ["CADH, Artigo 4", "OC 3/83", "Artigo 2º da Convenção", "OP 21/14", "Carta da OEA", "Carta Democrática Interamericana"], "jurisprudence": ["RE 123456", "ADPF 496", "Corte IDH, 2014"], "confidence": 0.8, "extracted_at": "2026-05-30T11:28:45.169667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=106", "doc_key": "66d9c2c9ba38e0981531de17aaaafc41"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4132dac42720233033de15bcb98d242ab662a7b210f8c4759bcc4a5b37be7ba1'),
  ('cpiuris2025::f9b651598bafba17745218e918ca2319', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência da Corte IDH em tratados internacionais de direitos humanos', '## Competência da Corte IDH em tratados internacionais de direitos humanos

A Corte IDH pode ser consultada para interpretar outros tratados de direitos humanos aplicáveis a um Estado Parte, e decide sobre disposições concernentes à proteção dos direitos humanos de qualquer tratado internacional aplicável independentemente do seu objeto principal.

### Conceitos
- **Competência da Corte IDH**: A capacidade da Corte IDH de decidir sobre questões relacionadas a tratados internacionais de direitos humanos
- **Interpretação de tratados internacionais**: O processo pelo qual a Corte IDH dá significado aos termos de um tratado internacional
- **Princípio pro homine**: A ideia de que as normas internacionais devem ser interpretadas para proteger os indivíduos
- **Efeito útil**: O princípio de que os juízes devem garantir que a aplicação das normas dos tratados não diminua ou anule a proteção aos direitos humanos

### Referências legais
- Art. 29 da CADH
- Art. 64.1 da Convenção

### Jurisprudência
- Opinião Consultiva nº 1/82
- Caso dos Irmãos Gómez Paquiyauri vs. Perú

### Dicas de prova
- Entenda a competência da Corte IDH em relação aos tratados internacionais de direitos humanos
- Conheça os princípios pro homine e do efeito útil que guiam a interpretação das normas dos tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direitos Humanos", "legal_refs": ["Art. 29 da CADH", "Art. 64.1 da Convenção"], "jurisprudence": ["Opinião Consultiva nº 1/82", "Caso dos Irmãos Gómez Paquiyauri vs. Perú"], "confidence": 0.8, "extracted_at": "2026-05-30T11:30:22.772350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=106", "doc_key": "f9b651598bafba17745218e918ca2319"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3e8d36a7a3b87cc56b85c2b72b91afe96ff856412777a3654b73ee2bd912aa62'),
  ('cpiuris2025::d6c318c555119176216d296278adfde9', 'doutrina', 'cp_iuris', 'Direitos Humanos — Dever Geral do Estado de Adequar Direito Interno às Disposições da Convenção Americana', '## Dever Geral do Estado de Adequar Direito Interno às Disposições da Convenção Americana

O dever geral do Estado inclui promulgar normas, desenvolver práticas e adotar medidas para garantir os direitos humanos consagrados na Convenção Americana.

### Conceitos
- **Dever Geral do Estado**: O dever do Estado de adequar seu direito interno às disposições da Convenção Americana
- **Controle de Convencionalidade**: A obrigação dos juízes e órgãos vinculados à administração da justiça para exercer um controle entre as normas internas e a Convenção Americana
- **Princípio do Efetutile**: O princípio que exige que as medidas de direito interno sejam efetivas para garantir os direitos humanos consagrados na Convenção Americana

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Caso López Mendoza vs. Venezuela

### Dicas de prova
- Entenda o conceito de Dever Geral do Estado e seu impacto na proteção dos direitos humanos.
- Conheça a importância do Controle de Convencionalidade e como ele se aplica nos tribunais da região.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Caso López Mendoza vs. Venezuela"], "confidence": 0.8, "extracted_at": "2026-05-30T11:30:52.439883+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=107", "doc_key": "d6c318c555119176216d296278adfde9"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '726d173fc850d26c85eb68dfa3f1fcc77acc191a00462c33d91823780b7564b9'),
  ('cpiuris2025::8852cde8918a92e9c0f4f5c9ef6ccda2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Vinculação dos tribunais internos à jurisprudência dos tribunais internacionais', '## Vinculação dos tribunais internos à jurisprudência dos tribunais internacionais

A vinculação dos tribunais internos à jurisprudência dos tribunais internacionais é discutida, destacando-se a interpretação mais favorável ao direito posto em julgamento, de acordo com o princípio pro homine.

### Conceitos
- **Princípio Pro Homine**: Princípio que prioriza a interpretação mais favorável ao direito posto em julgamento
- **Controle de Convencionalidade**: Procedimento utilizado para verificar se uma lei ou tratado internacional está de acordo com o direito interno
- **Norma Mais Favorável**: A norma que proteja melhor as vítimas, seja ela de direito internacional ou de direito interno

### Referências legais
- Art. 29.b e d da CADH
- Art. 5º, §2º da Constituição

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pergunte sobre a aplicação do princípio pro homine no controle de convencionalidade
- Entenda a importância da norma mais favorável às vítimas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direitos Humanos", "legal_refs": ["Art. 29.b e d da CADH", "Art. 5º, §2º da Constituição"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T11:31:01.517220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=107", "doc_key": "8852cde8918a92e9c0f4f5c9ef6ccda2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '29628f5699522d1f078d42a43bae2e76ef472eeb46309b8473ea4dea591d54a2'),
  ('cpiuris2025::9050d333d1d5fb8dc9021efc04c67bb3', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade', '## Controle de Convencionalidade

O controle judicial de convencionalidade é exercido exclusivamente pelos órgãos internacionais competentes, conforme o tratado ou convenção internacional específica. No plano nacional, somente ocorre pela via concentrada, pelo órgão de cúpula do Poder Judiciário.

### Conceitos
- **Controle de Convencionalidade**: Exercido exclusivamente pelos órgãos internacionais competentes
- **Via Concentrada**: Exclusiva do órgão de cúpula do Poder Judiciário nacional
- **Via Difusa**: Possível no plano internacional, mas não no plano interno
- **Teoria do Duplo Controle**: Impõe ao órgão internacional competente o controle de constitucionalidade das normas jurídicas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre controle de convencionalidade e controle de constitucionalidade
- Entender a via concentrada e difusa no plano nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T11:32:53.668202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=108", "doc_key": "9050d333d1d5fb8dc9021efc04c67bb3"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2a0bc277c1779b94c2c7166ed4797092652f51ab3f236c021e375c6dd3075c6f'),
  ('cpiuris2025::f1724b752dae213e9783ec5ec7b2f6d0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria do duplo controle e controle de convencionalidade', '## Teoria do duplo controle e controle de convencionalidade

A teoria do duplo controle é fundamental no direito internacional dos direitos humanos. Ela exige que as normas internas de um país sejam compatíveis com a constituição nacional e os tratados internacionais aos quais o país é parte.

### Conceitos
- **Teoria do duplo controle**: Princípio que exige compatibilidade entre as normas internas de um país com a constituição nacional e os tratados internacionais
- **Controle de convencionalidade**: Análise para garantir que as leis nacionais estejam em conformidade com os tratados internacionais

### Referências legais
- Art. 5 da Constituição Brasileira
- Tratado Americano sobre Direitos Humanos

### Jurisprudência
- Caso Ximenes Lopes vs. Brasil (Corte Interamericana de Direitos Humanos)

### Dicas de prova
- Entenda a teoria do duplo controle e seu papel no direito internacional dos direitos humanos
- Análise do caso Ximenes Lopes vs. Brasil para entender o controle de convencionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição Brasileira", "Tratado Americano sobre Direitos Humanos"], "jurisprudence": ["Caso Ximenes Lopes vs. Brasil (Corte Interamericana de Direitos Humanos)"], "confidence": 0.8, "extracted_at": "2026-05-30T11:33:07.988541+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=109", "doc_key": "f1724b752dae213e9783ec5ec7b2f6d0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8ad869a31755f1cb558192898e4fbffe81de14db92bbe4e3bf410dc2f491713e'),
  ('cpiuris2025::a6c31014ec6cac546ffc8fa9c990b321', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos e Controle de Convencionalidade', '## Proteção Internacional dos Direitos Humanos e Controle de Convencionalidade

A discussão sobre o papel das sociedades empresárias na proteção aos Direitos Humanos avançou, especialmente após a globalização econômica. A questão aborda a proteção dessas empresas perante as cortes internacionais e os princípios de direitos humanos.

### Conceitos
- **Controle de Convencionalidade**: Regra que exige compatibilidade entre normas jurídicas nacionais e disposições internacionais acolhidas pelo Estado.
- **Teoria do Duplo Controle**: Teoria que exige compatibilidade não apenas com a Constituição nacional, mas também com as disposições internacionais.
- **Princípios de Ruggie**: Princípios que visam proteger os Direitos Humanos, considerados suficientes para garantir a responsabilização internacional dos Estados e das sociedades empresárias.
- **Corte Interamericana de Direitos Humanos**: Órgão que procura proteger e promover os Direitos Humanos na América Latina.
- **Comissão Interamericana de Direitos Humanos**: Órgão da Organização dos Estados Americanos que procura proteger e promover os Direitos Humanos.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

