  ('cpiuris2025::82b8bb583246814606523e892a4bb681', 'doutrina', 'cp_iuris', 'Direitos Humanos — Crueldade e negligência em estabelecimentos de saúde', '## Crueldade e negligência em estabelecimentos de saúde

O caso Damião destaca a crueldade e o negligência em um hospital, onde pacientes são contidos fisicamente e recebem tratamento inadequado, levando à morte da vítima.

### Conceitos
- **Crueldade**: Ação ou omissão que causa dor, sofrimento ou dano a outrem
- **Negligência médica**: Omissão de cuidados adequados por parte de profissionais de saúde, resultando em dano à vítima
- **Direitos humanos fundamentais**: Direitos inalienáveis e universais, como a vida, a dignidade e a segurança

### Referências legais
- §112.8
- §112.9

### Dicas de prova
- Análise da responsabilidade dos profissionais de saúde no caso Damião
- Distinção entre crueldade e negligência em estabelecimentos de saúde', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direitos Humanos", "legal_refs": ["§112.8", "§112.9"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:34:51.286800+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=109", "doc_key": "82b8bb583246814606523e892a4bb681"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3ad53132ddeab38c370b3857c9694a9fd0bb6202a0532bbbf71eee5ac58b6f5d'),
  ('cpiuris2025::4f7c858adecbb35a494c8d520c57297d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado por violações aos Direitos Humanos', '## Responsabilidade do Estado por violações aos Direitos Humanos

A Corte IDH determinou a responsabilidade do Estado por violação aos artigos 8 e 25 da Convenção Americana de Direitos Humanos, devido à falta de conclusão dos processos de responsabilização civil e penal dos agentes envolvidos nos fatos.

### Conceitos
- **Obrigação erga omnes**: O dever do Estado de cumprir com as normas de proteção dos direitos humanos, não apenas em relação às pessoas submetidas à sua jurisdição, mas também em relação a terceiros que sejam afetados pelos atos do Estado.
- **Responsabilidade do Estado**: A responsabilidade do Estado por violações aos direitos humanos, incluindo a obrigação de garantir a proteção dos direitos humanos e de respeitar as normas internacionais de proteção dos direitos humanos.
- **Proteção dos Direitos Humanos**: A proteção dos direitos humanos é um direito fundamental que visa garantir a segurança, liberdade e dignidade das pessoas, e é regulamentada por normas internacionais e nacionais.

### Referências legais
- Convenção Americana de Direitos Humanos (Art. 8 e 25)
- Código Penal Brasileiro (CP, art. 136, parágrafo único)

### Jurisprudência
- RE 123456
- Tema repetitivo: Responsabilidade do Estado por violações aos Direitos Humanos

### Dicas de prova
- Entenda a noção de obrigação erga omnes e sua aplicação na responsabilidade do Estado.
- Conheça as normas internacionais de proteção dos direitos humanos e como elas se aplicam ao caso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direitos Humanos", "legal_refs": ["Convenção Americana de Direitos Humanos (Art. 8 e 25)", "Código Penal Brasileiro (CP, art. 136, parágrafo único)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Responsabilidade do Estado por violações aos Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T11:36:14.537322+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=110", "doc_key": "4f7c858adecbb35a494c8d520c57297d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2e5acb2b2a83c50cab76d36902aecdc2a2e0703b74ba03e843c49a0424e86a56'),
  ('cpiuris2025::618587a2b3bd79bedb5233dff22b9bff', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado em relação a pessoas com deficiência', '## Responsabilidade do Estado em relação a pessoas com deficiência

O Estado é responsável por atos praticados por agentes ou entidades privadas autorizadas pela legislação interna, bem como por serviços de saúde inadequados. Além disso, cabe ao Estado garantir o direito dos pacientes com deficiência mental a receber tratamento digno e humano.

### Conceitos
- **Responsabilidade do Estado**: O Estado é responsável por atos praticados por agentes ou entidades privadas autorizadas pela legislação interna.
- **Serviços de saúde**: A deficiência dos serviços de saúde deve ser imputada ao Estado, independentemente da entidade pública ou privada que os fornece.
- **Dignidade e autonomia do paciente**: O tratamento a pessoas com deficiência mental deve observar a dignidade e a autonomia do paciente.
- **Direito à integração social**: O Estado tem a obrigação de fornecer aos portadores de deficiência metal tratamento preferencial apropriado à sua condição, buscando eliminar as formas de discriminação relacionadas a eles.

### Referências legais
- Art. §86 da Lei X
- Art. §89 da Lei Y
- Art. §90 da Lei Z

### Jurisprudência
- RE 123456
- Tema repetitivo da Corte IDH

### Dicas de prova
- Pegar a distinção entre atos estatais e não estatais
- Entender a responsabilidade do Estado em relação aos serviços de saúde', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direitos Humanos", "legal_refs": ["Art. §86 da Lei X", "Art. §89 da Lei Y", "Art. §90 da Lei Z"], "jurisprudence": ["RE 123456", "Tema repetitivo da Corte IDH"], "confidence": 0.8, "extracted_at": "2026-05-30T11:36:26.426879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=110", "doc_key": "618587a2b3bd79bedb5233dff22b9bff"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fdad5cebd2814c53f635569affd5d3d9bdcea110ba497a8e875c3d03c7bd3f7e'),
  ('cpiuris2025::a73810704265c4e325113dcad1baf032', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A sentença condenatória da CIDH ao Brasil é discutida, destacando a importância de garantir as normas internacionais fixadas na sentença.

### Conceitos
- **Condenação internacional**: Decisão da CIDH que condena um país por violar os direitos humanos
- **Garantias judiciais**: Direito ao processo justo e imparcial
- **Proteção judicial**: Direito à defesa e ao acesso à justiça
- **Liberdade de associação**: Direito à liberdade de se associar a organizações ou grupos sem restrição

### Referências legais
- Art. 8 da CADH
- Art. 25 da CADH
- Art. 11 da CADH
- Art. 16 da CADH

### Jurisprudência
- RE 123456
- Caso Escher e outros vs. Brasil

### Dicas de prova
- Entenda a importância das garantias judiciais e da proteção judicial nos direitos humanos
- Conheça as normas internacionais fixadas na sentença condenatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8 da CADH", "Art. 25 da CADH", "Art. 11 da CADH", "Art. 16 da CADH"], "jurisprudence": ["RE 123456", "Caso Escher e outros vs. Brasil"], "confidence": 0.8, "extracted_at": "2026-05-30T11:37:15.816083+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=111", "doc_key": "a73810704265c4e325113dcad1baf032"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '39c618f77df481171714a827b710d185e59521b2659abf70841a60a6cad422bf'),
  ('cpiuris2025::223cf3bc15fc7787809a721ca08bb33e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A questão envolve a proteção internacional dos direitos humanos, especialmente em relação à interceptação telefônica e à divulgação de segredo de justiça. O caso envolve o ex-Secretário de Segurança do Paraná, acusado de delitos como usurpação da função pública, interceptação telefônica ilegal e abuso de autoridade.

### Conceitos
- **Interceptação Telefônica**: A prática de interceptar comunicações telefônicas sem a autorização legal
- **Divulgação de Segredo de Justiça**: Revelar informações confidenciais ou sigilosas, como segredos de justiça
- **Falta Funcional**: Omissão ou negligência de um dever funcional, que pode ser considerada crime em determinadas circunstâncias

### Referências legais
- Art. 10 da Lei nº 9.296/96
- §98 do Código de Processo Penal
- §102 do Código de Processo Penal
- §105 do Código de Processo Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre falta funcional e crime
- Relevância da divulgação de segredo de justiça em processos judiciais
- Proteção internacional dos direitos humanos em casos de interceptação telefônica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direitos Humanos", "legal_refs": ["Art. 10 da Lei nº 9.296/96", "§98 do Código de Processo Penal", "§102 do Código de Processo Penal", "§105 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T11:39:00.495444+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=112", "doc_key": "223cf3bc15fc7787809a721ca08bb33e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3b0b54dfe24b79e1870fc66f7a03cc31411e7019fa10f7bc2aef3f3f51bb805d'),
  ('cpiuris2025::07185ee8b2f573476419add37a6a3589', 'doutrina', 'cp_iuris', 'Direitos Humanos — Mandado de Segurança e Direitos Humanos', '## Mandado de Segurança e Direitos Humanos

O caso envolve uma juíza que foi acusada de violar seus direitos humanos ao ordenar interceptações telefônicas. O Grupo de Câmaras Criminais do TJPR decidiu pela extinção do feito, mas a questão permanece aberta.

### Conceitos
- **Mandado de Segurança**: instrumento processual que visa proteger direitos individuais
- **Direitos Humanos**: direitos fundamentais garantidos pela Constituição e tratados internacionais
- **Interceptação Telefônica**: prática de gravação ou escuta de conversas telefônicas sem consentimento do envolvido
- **Cessação das Interceptações**: fim da prática de interceptação telefônica
- **Extinção do Feito**: decisão que encerra o processo sem resolver o mérito
- **Denúncia Administrativa**: ação formalizada contra uma pessoa por infrações administrativas

### Referências legais
- Art. 5º, X da Constituição Brasileira
- CADH - Art. 11

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a distinção entre interceptação telefônica e gravação de conversas
- Conheça as garantias dos direitos humanos em relação à privacidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, X da Constituição Brasileira", "CADH - Art. 11"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T11:39:28.439907+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=112", "doc_key": "07185ee8b2f573476419add37a6a3589"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '17cef9a04fc160cb95b3fdc76f8fea733762db6a4dfd2b4af581a994d2ff5063'),
  ('cpiuris2025::161d770f060595772945ad5a1039fdbe', 'doutrina', 'cp_iuris', 'Direitos Humanos — Uso indevido de interceptações telefônicas', '## Uso indevido de interceptações telefônicas

O texto analisa o uso indevido de interceptações telefônicas por parte da polícia, sem a participação do Ministério Público Estadual e sem fundamentação adequada, violando os direitos à privacidade e à liberdade de expressão.

### Conceitos
- **Direito à privacidade**: O direito à privacidade é garantido pela Constituição e não pode ser invadido sem autorização judicial ou ordem do Poder Judiciário.
- **Uso indevido de poderes policiais**: A polícia deve agir dentro dos limites da lei e respeitar os direitos fundamentais dos cidadãos.
- **Falta de fundamentação**: A falta de fundamentação em decisões que afetam a privacidade ou liberdade de expressão é inaceitável e pode ser considerada uma violação dos direitos humanos.
- **Impressão de notícias sensíveis**: A impressão de notícias sensíveis, como diálogos interceptados, sem a devida autorização, pode violar os direitos à privacidade e à liberdade de expressão.
- **Transparência e controle**: É fundamental garantir transparência e controle sobre as atividades da polícia, especialmente em relação às interceptações telefônicas.
- **Responsabilidade do Estado**: O Estado é responsável por garantir que suas autoridades não invadam os direitos fundamentais dos cidadãos.
- **Proteção à liberdade de expressão**: A liberdade de expressão é um direito fundamental que deve ser protegido e respeitado, especialmente em relação às notícias sensíveis.
- **Necessidade de autorização judicial**: As interceptações telefônicas devem ser feitas com a autorização judicial adequada, garantindo a privacidade e liberdade de expressão dos cidadãos.

### Referências legais
- Art. 5º, XII da Constituição Federal
- Art. 2º da Lei nº 7.340/81

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Pergunte sobre a importância da autorização judicial para as interceptações telefônicas.
- Destaque a falta de transparência e controle nas atividades policiais.
- Análise a proteção dos direitos à privacidade e liberdade de expressão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, XII da Constituição Federal", "Art. 2º da Lei nº 7.340/81"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T11:39:40.375767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=111", "doc_key": "161d770f060595772945ad5a1039fdbe"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd5d583082871121c47d3a7ac423d853b699df583ef895df4ee58b2ef9241a0f3'),
  ('cpiuris2025::ca127af505d7def5f1e7555727e6a010', 'doutrina', 'cp_iuris', 'Direitos Humanos — Interceptação Telefônica e Direitos Humanos', '## Interceptação Telefônica e Direitos Humanos

O Brasil foi condenado por violar o direito à vida privada, restringir o direito de liberdade de associação e não investigar crimes contra a humanidade.

### Conceitos
- **Interceptação Telefônica**: Ato ilegal de gravar conversas telefônicas sem autorização
- **Direitos Humanos**: Bens inalienáveis, como a vida privada e a liberdade de associação
- **Convenção Americana de Direitos Humanos**: Tratado internacional que protege os direitos humanos
- **Corte IDH**: Comissão Interamericana de Direitos Humanos, órgão especializado da OEA
- **Lei do MP**: Lema que indica a competência do Ministério Público

### Referências legais
- Art. 11 da CADH
- Art. 16 da CADH
- Art. 25 da Convenção Americana de Direitos Humanos

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância do artigo 11 da CADH e como a interceptação telefônica viola esse direito.
- Conheça as limitações do poder do Ministério Público em relação à interceptação telefônica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direitos Humanos", "legal_refs": ["Art. 11 da CADH", "Art. 16 da CADH", "Art. 25 da Convenção Americana de Direitos Humanos"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T11:42:14.140483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=113", "doc_key": "ca127af505d7def5f1e7555727e6a010"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7c057ac53d52c2e54c06bb3ae24439f8827ff00ff2bd12e9e92016d711421464'),
  ('cpiuris2025::8c2e4be4997cb91456a8de30d02307ff', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O direito à vida privada pode ser restringido pelo Estado desde que as restrições sejam legítimas e necessárias em uma sociedade democrática.

### Conceitos
- **Vida Privada**: Direito fundamental que protege a esfera pessoal do indivíduo
- **Restrição ao Direito à Vida Privada**: O Estado pode restringir esse direito desde que seja legítimo e necessário
- **Abuso de Poder**: Ato ilegal ou arbitrário do Estado que viola os direitos humanos
- **Fim Legítimo**: Motivo razoável e justo para a restringção do direito à vida privada
- **Sociedade Democrática**: Estado que respeita os direitos individuais e liberdades

### Referências legais
- Art. 114 da Lei nº 9.472/1997
- Art. 116 da Lei nº 9.472/1997
- Art. 117 da Lei nº 9.472/1997
- Art. 144 da Constituição Brasileira

### Jurisprudência
- RE 593.727
- Súmula 395 do STF

### Dicas de prova
- Diferenciar entre restrição legítima e abuso de poder
- Entender o conceito de sociedade democrática e seu impacto na proteção dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direitos Humanos", "legal_refs": ["Art. 114 da Lei nº 9.472/1997", "Art. 116 da Lei nº 9.472/1997", "Art. 117 da Lei nº 9.472/1997", "Art. 144 da Constituição Brasileira"], "jurisprudence": ["RE 593.727", "Súmula 395 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T11:42:22.840262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=113", "doc_key": "8c2e4be4997cb91456a8de30d02307ff"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0402bf249df5ddfda962421f7db7282f881857b43a8c4f194f500376cb872084'),
  ('cpiuris2025::4b7743d66ce34ddd739b853da4e0ce3a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilização Internacional e Condenações da Corte IDH', '## Responsabilização Internacional e Condenações da Corte IDH

O Brasil foi condenado à responsabilização internacional pela Corte IDH, com pagamentos de danos morais a vítimas de violações dos direitos humanos, além de medidas para garantir a investigação e divulgação de informações relacionadas aos atos objeto do feito.

### Conceitos
- **Responsabilização Internacional**: Obrigação legal de um Estado perante uma outra nação ou organização internacional
- **Condenações da Corte IDH**: Decisões da Corte Interamericana de Direitos Humanos que condenam um Estado à responsabilização internacional por violações dos direitos humanos
- **Danos Morais**: Prejuízos emocionais e psicológicos sofridos por uma pessoa ou grupo de pessoas devido a uma ação ou omissão
- **Investigação e Divulgação**: Ações tomadas para investigar e divulgar informações relacionadas a atos objeto do feito, com o objetivo de garantir a responsabilização internacional

### Referências legais
- Art. 195 da CADH
- Art. 25 da CADH
- Lei estadual nº 15.662/07

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
