  ('cpiuris2025::7b70c1f0ef89989320592fcf03d607c8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Violação de direitos humanos em operações extrajudiciais', '## Violação de direitos humanos em operações extrajudiciais

A Corte IDH condenou o Brasil por violação dos artigos 8 e 25 da CADH após a morte do trabalhador sem-terra Sétimo Garibaldi durante uma operação extrajudicial de despejo em 1998.

