- **Operação Extrajudicial**: Atuação policial fora do contexto legal
- **Violação de Direitos Humanos**: Infratio dos direitos fundamentais estabelecidos na CADH
- **Condenação Internacional**: Responsabilidade internacional por atos violadores de direitos humanos
- **Caso Garibaldi vs. Brasil**: Processo em que o Brasil foi condenado pela Corte IDH
- **CADH**: Convenção Americana de Direitos Humanos

### Referências legais
- Art. 8 da CADH
- Art. 25 da CADH

