  ('cpiuris2025::bf8d1fbe223e7867f9496e6f4e197243', 'doutrina', 'cp_iuris', 'Direitos Humanos — Investigação e Sanção de Violações de Direitos Humanos', '## Investigação e Sanção de Violações de Direitos Humanos

O Estado deve garantir aos parentes da vítima acesso à justiça, investigação e sanção dos responsáveis pelas violações de direitos humanos.

### Conceitos
- **Investigação**: Ação para esclarecer os fatos de um caso
- **Sanção**: Medida aplicada ao responsável por uma violação de direitos humanos
- **Garantias judiciais**: Direitos protegidos pela lei para as partes envolvidas em um processo
- **Razoabilidade**: Ajuste razoável da duração das investigações

