  ('cpiuris2025::fb0ac5c862a7c0275e0f96e4ce8f78fb', 'doutrina', 'cp_iuris', 'Direitos Humanos — Investigação de violações de direitos humanos', '## Investigação de violações de direitos humanos

A investigação de violações de direitos humanos é uma medida positiva a ser adotada pelo Estado, garantida pela CADH. A investigação é uma obrigação do Estado, devendo ser assumida como um dever jurídico próprio e não uma mera formalidade.

### Conceitos
- **Investigação de violações de direitos humanos**: Ação realizada pelo Estado para identificar e punir aqueles responsáveis por violações dos direitos humanos
- **Obrigação do Estado**: Dever jurídico próprio do Estado de investigar e punir violações de direitos humanos
- **Medida positiva**: Ação proativa realizada pelo Estado para garantir a proteção dos direitos humanos
- **Dever jurídico**: Obrigação legal do Estado de cumprir com uma determinada ação ou medida

### Referências legais
- Art. 8 da CADH
- Art. 25 da CADH
- §112 da CADH
- §113 da CADH
- §115 da CADH

### Dicas de prova
- Entenda a distinção entre medida positiva e mera formalidade
- Conheça o conceito de dever jurídico do Estado
- Identifique a obrigação do Estado em investigar violações de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8 da CADH", "Art. 25 da CADH", "§112 da CADH", "§113 da CADH", "§115 da CADH"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:45:05.681329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=115", "doc_key": "fb0ac5c862a7c0275e0f96e4ce8f78fb"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '5b95e852c4f1a57a2a76ff562776029f12ef7693e27a62ef9b54b7d93c096b2d'),
  ('cpiuris2025::6e2eac0ec97d1dd4d87f9e2cf15dd224', 'doutrina', 'cp_iuris', 'Direitos Humanos — Leis de Anistia e Direitos Humanos', '## Leis de Anistia e Direitos Humanos

A Lei de Anistia brasileira deixou de investigar e punir responsáveis por violações dos direitos humanos, afetando as vítimas e seus familiares.

### Conceitos
- **Lei de Anistia**: Lei que exclui a responsabilidade dos militares por violações dos direitos humanos
- **Direitos Humanos**: Direitos fundamentais da pessoa humana, garantidos pela Constituição e leis internacionais
- **Competência Contenciosa**: O direito de um Estado ou organização para julgar uma questão ou caso

### Referências legais
- Art. 5º, caput, da Constituição de 1988
- Lei nº 6.683/79

