  ('cpiuris2025::86bad08064d225764edb3651a3f033a2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilização Internacional dos Direitos Humanos', '## Responsabilização Internacional dos Direitos Humanos

A Corte IDH condenou o Brasil por responsabilidade internacional, exigindo a publicação de sentenças, pagamento de indenizações e medidas para investigar e julgar os autores de atos ilegais.

### Conceitos
- **Responsabilização Internacional**: Obrigação do Estado de cumprir com os direitos humanos internacionais
- **Corte IDH**: Comissão Interamericana de Direitos Humanos, responsável por investigar e julgar reclamações sobre violações dos direitos humanos
- **Prestações Condenatórias**: Medidas exigidas pela Corte IDH para compensar as vítimas de violações dos direitos humanos
- **Lei estadual nº 15.662/07**: Lei que concedeu título de cidadã honorária a uma juíza, considerada inconstitucional pela Corte IDH

### Referências legais
- Art. 21 da CADH
- Súmula 281 do STF

### Jurisprudência
- Caso Gomes Lund e outros (''Guerrilha do Araguaia'') vs. Brasil
- Caso Escher vs. Brasil

### Dicas de prova
- Entenda a responsabilização internacional dos direitos humanos e as prestações condenatórias exigidas pela Corte IDH.
