  ('cpiuris2025::fc6de2c2fb2f75159ee896f073f57061', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade e Liberdade de Expressão', '## Controle de Convencionalidade e Liberdade de Expressão

O controle de convencionalidade é competência do judiciário, que deve considerar a interpretação da Corte Interamericana à Convenção. A liberdade de expressão abrange buscar, receber e divulgar informações e ideias de toda índole.

### Conceitos
- **Controle de Convencionalidade**: Competência do judiciário para controlar a conformidade das normas nacionais com as convenções internacionais
- **Liberdade de Expressão**: Direito à liberdade de expressar o próprio pensamento, buscar, receber e divulgar informações e ideias
- **Interpretação da Corte Interamericana**: Consideração da interpretação da Corte Interamericana à Convenção para garantir a conformidade das normas nacionais
- **Restrição Legítima**: Justificativa para restringir o acesso a informações ou afetar uma pessoa pessoalmente
- **Informações Públicas**: Informações que podem ser conhecidas por qualquer pessoa sem necessidade de comprovação de interesse direto

### Referências legais
- Art. 175 da Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre liberdade de expressão e controle de convencionalidade

### Dicas de prova
- Distinção entre restrições legítimas e não legítimas
- Importância da interpretação da Corte Interamericana para garantir a conformidade das normas nacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direitos Humanos", "legal_refs": ["Art. 175 da Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre liberdade de expressão e controle de convencionalidade"], "confidence": 0.8, "extracted_at": "2026-05-30T11:49:48.059847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=117", "doc_key": "fc6de2c2fb2f75159ee896f073f57061"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '265693c62faa3526008da3c1ee8043ed3349a9d8e4af3f7f4bffe50e76d081c1'),
  ('cpiuris2025::05ee68c02614712b9d63a992c3d5f62d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

Regras para a proteção internacional dos direitos humanos, incluindo publicação de sentenças e reconhecimento de responsabilidade internacional.

### Conceitos
- **Sentença condenatória**: Decisão do tribunal que condena um estado por violar os direitos humanos
- **Reconhecimento de responsabilidade internacional**: Ação oficial do estado para reconhecer a responsabilidade por violações dos direitos humanos
- **Publicação de sentença**: Divulgação da decisão do tribunal em público, geralmente no diário oficial e em jornais
- **Indenização**: Pagamento feito pelo estado às vítimas de violações dos direitos humanos

### Referências legais
- Art. 5º, caput, da CF/88
- Súmula 292 do STF

### Jurisprudência
- RE 123456
- CIDH - Caso Trabalhadores da Fazenda Brasil Verde vs. Brasil

### Dicas de prova
- Reconheça a importância da publicação de sentenças em casos de violações dos direitos humanos
- Entenda o conceito de reconhecimento de responsabilidade internacional e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, da CF/88", "Súmula 292 do STF"], "jurisprudence": ["RE 123456", "CIDH - Caso Trabalhadores da Fazenda Brasil Verde vs. Brasil"], "confidence": 0.8, "extracted_at": "2026-05-30T11:52:02.400214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=119", "doc_key": "05ee68c02614712b9d63a992c3d5f62d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9262f2d1f25e2170fab5bfa283e755fffd7cb0ba1b156b29ec318d84ccd68419'),
  ('cpiuris2025::ba44ce2747f4613572e8e85980041334', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Corte IDH discute a competência para julgar desaparecimentos forçados, a necessidade de marcos normativos para considerar o crime e a obrigação do Estado de investigar e punir os responsáveis.

### Conceitos
- **Competência da Corte IDH**: A competência da Corte IDH para julgar desaparecimentos forçados
- **Marco normativo**: O marco normativo necessário para considerar o crime de desaparecimento forçado
- **Investigação e punição**: A obrigação do Estado de investigar e punir os responsáveis por desaparecimentos forçados
- **Leis de Anistias**: As leis de anistia são incompatíveis com as obrigações internacionais assumidas pelos Estados
- **Impunidade**: A impunidade é impedida pela jurisprudência da Corte IDH

