- ADPF 153
- Art. 48 e 49 da CADH
- Art. 101 a 103 da CADH
- Art. 108 da CADH
- Art. 109 da CADH
- Art. 138 da CADH
- Art. 149 da CADH
- Art. 172 e 174 da CADH

### Jurisprudência
- RE 123456
- Súmula N STF

