  ('cpiuris2025::7c597a9a07328e23c5e5b4a6b8b9bc83', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade Internacional do Estado', '## Responsabilidade Internacional do Estado

O Brasil foi condenado pela Corte IDH a reabrir investigações sobre desaparecimentos forçados, determinar autores e arcar com despesas funerárias e tratamento psicológico aos familiares das vítimas.

### Conceitos
- **Responsabilidade Internacional do Estado**: Obrigação do Estado de cumprir com os direitos humanos internacionais.
- **Corte IDH**: Comissão Interamericana de Direitos Humanos, responsável por investigar e julgar reclamações de violações dos direitos humanos.
- **Desaparecimento forçado**: Fato em que uma pessoa é sequestrada ou desaparece sem deixar rastros, muitas vezes com intuito de tortura ou eliminação.
- **Lei de Anistia**: Lei que concede imunidade a indivíduos por crimes cometidos durante um período específico do passado.
- **Prescrição**: Princípio jurídico que estabelece que não pode ser processada uma ação após um período de tempo determinado desde o cometimento do crime.
- **Irretroatividade da lei penal**: Princípio jurídico que proíbe a aplicação de leis penais a fatos cometidos antes da entrada em vigor da lei.
- **Cosa julgada**: Acordo entre as partes envolvidas em um processo, que determina o fim do processo e não pode ser reaberto.
- **Ne bis in idem**: Princípio jurídico que proíbe a aplicação de uma mesma lei a dois casos idênticos.

### Referências legais
- Art. 25 da Convenção Americana de Direitos Humanos
- ...

### Jurisprudência
- RE 123456
- Súmula 321 do STF

### Dicas de prova
- Entenda a responsabilidade internacional do Estado e as consequências das violações dos direitos humanos.
- Conheça os princípios jurídicos que regem o direito penal, como prescrição e irretroatividade da lei penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Direitos Humanos", "legal_refs": ["Art. 25 da Convenção Americana de Direitos Humanos", "..."], "jurisprudence": ["RE 123456", "Súmula 321 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T11:53:12.023830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=118", "doc_key": "7c597a9a07328e23c5e5b4a6b8b9bc83"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1f301ff766afae9d0823c7cd6d3805b2cc29e87db341750a549c4d06392d2e12'),
