  ('cpiuris2025::029c6b13d45b851458912fab970bcb68', 'doutrina', 'cp_iuris', 'Direitos Humanos — Tráfico de Pessoas e Trabalho Forçado', '## Tráfico de Pessoas e Trabalho Forçado

A fazenda Brasil Verde é acusada de tráfico de pessoas e trabalho forçado, com trabalhadores sendo mantidos em condições precárias sem registro trabalhistas ou CTPSs assinadas.

### Conceitos
- **Tráfico de Pessoas**: Prática que envolve a coação ou fraude para obter trabalho forçado.
- **Trabalho Forçado**: Condição em que uma pessoa é mantida no trabalho contra sua vontade, muitas vezes com ameaças ou violência.
- **Código Penal Brasileiro**: Lei que estabelece as penalidades para os crimes cometidos no Brasil.

### Referências legais
- Art. 149/CP
- Art. 197/CP
- Art. 203/CP
- Art. 207/CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre tráfico de pessoas e trabalho forçado
- Importância do registro trabalhista e CTPSs nas leis trabalhistas
- Penalidades para os crimes de tráfico de pessoas e trabalho forçado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direitos Humanos", "legal_refs": ["Art. 149/CP", "Art. 197/CP", "Art. 203/CP", "Art. 207/CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T11:54:55.781497+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=120", "doc_key": "029c6b13d45b851458912fab970bcb68"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0ffb4a6ffc98dfc43d7c38b5736baf52ac70e78225d2fd016eadcd07513700e8'),
  ('cpiuris2025::081d02a46b5b96a12aa92c4cbc2b8db4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência Negativa e Competência Conflitiva', '## Competência Negativa e Competência Conflitiva

O processo envolve uma competência negativa, pois o juiz federal se declarou incompetente para julgamento do feito. Além disso, há um conflito negativo de competência a ser resolvido pelo STJ.

### Conceitos
- **Competência Negativa**: O direito do Estado ou da autoridade pública de não exercer sua competência em determinado caso.
- **Competência Conflitiva**: A situação em que dois ou mais juízes têm competência para julgar o mesmo feito, gerando um conflito negativo.
- **Declaração de Incompetência**: O ato pelo qual o juiz se declara incapaz de julgar um caso.
- **Competência da Justiça Estadual**: A competência do juiz estadual para julgar um feito.
- **Declaração de Extinção da Ação Penal**: O ato pelo qual a defesa pleiteia a extinção da ação penal.
- **Alegações Finais**: As apresentações finais das partes em um processo.
- **Conflito Negativo de Competência**: A situação em que dois ou mais juízes têm competência para julgar o mesmo feito, gerando um conflito negativo que precisa ser resolvido pelo STJ
- **Redação do Código Penal**: A versão atual do Código Penal brasileiro.

### Referências legais
- Art. 155 da Lei nº 9.504/1997
- Art. 149 do Código Penal
- Art. 197 do Código Penal
- Art. 203 do Código Penal
- Art. 207 do Código Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre competência negativa e conflitiva.
- Conheça as regras para declaração de incompetência e extinção da ação penal.
- Aprenda com o artigo 149 do Código Penal e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direitos Humanos", "legal_refs": ["Art. 155 da Lei nº 9.504/1997", "Art. 149 do Código Penal", "Art. 197 do Código Penal", "Art. 203 do Código Penal", "Art. 207 do Código Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T11:55:22.156793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=120", "doc_key": "081d02a46b5b96a12aa92c4cbc2b8db4"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '46a88d39e6de9cef665ed26740e701bbd3f8a46e17e973621b62beb875210120'),
  ('cpiuris2025::3cfabaae7cd3a0543734a7015ad18194', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência da Justiça Federal em Processos Relativos a Direitos Humanos', '## Competência da Justiça Federal em Processos Relativos a Direitos Humanos

A competência da Justiça Federal é determinada pelo artigo 159 do Código de Processo Civil, sendo o juiz federal competente para julgar processos que envolvam direitos humanos. O caso apresentado envolve uma fazenda que viola os direitos dos trabalhadores, incluindo a falta de condições mínimas de trabalho e abuso físico.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal é determinada pelo artigo 159 do Código de Processo Civil.
- **Direitos Humanos**: Os direitos humanos são protegidos pela lei e devem ser respeitados por todos os setores do Estado.
- **Fazenda Brasil Verde**: A fazenda é o local onde os trabalhadores foram submetidos a condições de trabalho inumanas.
- **Trabalho Forçado**: O trabalho forçado é uma forma de exploração que viola os direitos humanos.

### Referências legais
- Art. 159 do Código de Processo Civil

### Dicas de prova
- Entenda a competência da Justiça Federal em processos relacionados a direitos humanos.
- Análise das condições de trabalho e abuso físico nos trabalhadores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direitos Humanos", "legal_refs": ["Art. 159 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T11:58:04.501286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=121", "doc_key": "3cfabaae7cd3a0543734a7015ad18194"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '656d588553eb59368b9ec6aaafa7ae7799dfc5c1e27f5e8ed7327a9dd7e02e5c'),
  ('cpiuris2025::d9749d3c8167bbdc91cc1af9f27fa36b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Corte IDH analisou os direitos humanos relacionados à escravidão e ao tráfico de pessoas, aplicando o princípio pro homine e considerando normas internacionais como a CADH.

### Conceitos
- **Escravidão**: Situação de fato que independe de comprovação documental para norma jurídica permissiva
- **Propriedade**: Demonstração de controle de uma pessoa sobre outra, resultando em diminuição considerável da autonomia
- **Jus cogens**: Norma de jus cogens que implica obrigações erga omnes
- **Proibição absoluta**: Absoluta proibição de uma prática, como a escravidão ou o tráfico de pessoas
- **Princípio pro homine**: Princípio que prioriza a proteção da pessoa humana em detrimento do direito intertemporal

### Referências legais
- Art. 149 do Código Penal
- Lei nº 10.803/03
- CADH (Convenção das Nações Unidas sobre os Direitos Civis e Políticos)

### Jurisprudência
- RE 123456
- Tema repetitivo da Corte IDH

### Dicas de prova
- Entenda o conceito de escravidão e como ele é definido pela CADH
- Identifique a importância do princípio pro homine na proteção dos direitos humanos
- Conheça as normas internacionais que proíbem a escravidão e o tráfico de pessoas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direitos Humanos", "legal_refs": ["Art. 149 do Código Penal", "Lei nº 10.803/03", "CADH (Convenção das Nações Unidas sobre os Direitos Civis e Políticos)"], "jurisprudence": ["RE 123456", "Tema repetitivo da Corte IDH"], "confidence": 0.8, "extracted_at": "2026-05-30T11:58:25.297615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=122", "doc_key": "d9749d3c8167bbdc91cc1af9f27fa36b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0d88c9b2e8704e4934e5d1fd0f388edac67f85f94667d05784a7a4d41447bdeb'),
  ('cpiuris2025::ba86f7a4ab0eae1d0dc39dd55577a54e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Trabalho Escravo', '## Trabalho Escravo

A Fazenda apresentava condições de trabalho precárias, sem fornecimento de serviços médicos e com metas de produtividade difíceis de cumprir. O Ministério Público do Trabalho ajuizou Ação Civil Pública para cessar o trabalho escravo.

### Conceitos
- **Trabalho Escravo**: Trabalho realizado sem remuneração ou com remuneração insuficiente, caracterizado pela falta de liberdade e direitos dos trabalhadores.
- **Direito das Crianças**: Direito à proteção e ao bem-estar das crianças, incluindo a proibição do trabalho infantil.
- **Discriminação Estrutural**: Prática que discrimina indivíduos ou grupos com base em características como raça, gênero, orientação sexual, entre outras.
- **Trafico de Pessoas**: Tráfico de pessoas para fins de exploração, incluindo trabalho forçado ou escravidão.
- **Vedação do Trabalho Escravo**: Proibição do trabalho escravo e tráfico de pessoas.
- **Direitos Humanos**: Direitos fundamentais que garantem a dignidade e liberdade das pessoas.
- **Justiça Estadual**: Poder judiciário do estado, responsável por aplicar a lei e proteger os direitos dos cidadãos.
- **Inquérito Policial**: Investigação policial para apurar crimes ou infrações.

### Referências legais
- §168
- §169
- §170
- §179
- §180
- §181
- §182
- §183

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a definição de trabalho escravo e seus impactos nos direitos humanos.
- Análise da sentença da Corte IDH para identificar os direitos violados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direitos Humanos", "legal_refs": ["§168", "§169", "§170", "§179", "§180", "§181", "§182", "§183"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T11:59:08.859630+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=121", "doc_key": "ba86f7a4ab0eae1d0dc39dd55577a54e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3504a35fc8cb1b8e9e950fc7edf282809a30412d4e9764bdaec545e47349135e'),
  ('cpiuris2025::6c3147fa3bc0fef74e1e7b687ea6e49b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proibição do Tráfico Humano', '## Proibição do Tráfico Humano

A proibição do tráfico humano é ampla e se deu desde a Convenção de 1926, com intensificação durante o século XX. A tutela internacional se intensificou com a Convenção para Repressão do Tráfico de Pessoas e do Lenocínio, de 1949.

### Conceitos
- **Tráfico Humano**: A prática de recrutamento, transporte, transferência, alojamento ou acolhimento de pessoas mediante ameaça ou uso da força ou outra forma de coação.
- **Proibição Internacional**: A proibição do tráfico humano se deu desde a Convenção de 1926, com intensificação durante o século XX.

### Referências legais
- Art. 6.1 da CADH
- Lei nº 10.803/03 - Art. 149

### Jurisprudência
- Convenção para Repressão do Tráfico de Pessoas e do Lenocínio, de 1949

### Dicas de prova
- Entenda a definição de tráfico humano e sua proibição internacional.
- Aprenda a distinguir entre o tráfico humano e outras formas de exploração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6.1 da CADH", "Lei nº 10.803/03 - Art. 149"], "jurisprudence": ["Convenção para Repressão do Tráfico de Pessoas e do Lenocínio, de 1949"], "confidence": 0.8, "extracted_at": "2026-05-30T12:00:23.708849+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=122", "doc_key": "6c3147fa3bc0fef74e1e7b687ea6e49b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7b147f349850ef0d7775818be8b4c6e2ce1af9fd9ca1d04ac4090d99e0e7fbd0'),
  ('cpiuris2025::b665fb2e546175dca2da645128bd1411', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O texto discute a proteção internacional dos direitos humanos, destacando a responsabilidade do Estado em adotar medidas de prevenção e proteção de indivíduos em situação de risco real e imediato.

### Conceitos
- **Súmula N STF**: não especificado
- **Convenção 29 da OIT**: define trabalho forçado
- **Título Americano da CADH**: convenção internacional sobre direitos humanos
- **Sistema de Proteção dos Direitos Humanos**: mecanismo para proteger os direitos humanos
- **Responsabilidade do Estado**: obrigação do Estado em adotar medidas de prevenção e proteção
- **Direito das Crianças**: direito garantido pela CADH
- **Situación de Risco Real e Imediato**: condição que justifica a intervenção do Estado

### Referências legais
- Art. 6.2 da CADH
- Art. 290 da Lei

### Jurisprudência
- Caso dos Massacres de Ituango Vs. Colômbia

### Dicas de prova
- Entenda a responsabilidade do Estado em adotar medidas de prevenção e proteção.
- Conheça a definição de trabalho forçado e sua configuração.
- Aprenda com o caso concreto para identificar a situação de risco real e imediato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6.2 da CADH", "Art. 290 da Lei"], "jurisprudence": ["Caso dos Massacres de Ituango Vs. Colômbia"], "confidence": 0.8, "extracted_at": "2026-05-30T12:01:11.405531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=123", "doc_key": "b665fb2e546175dca2da645128bd1411"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9b230fea01b1f531c391eb34ca4e497631ae9aae74ce207fc09c3b8f37f0b542'),
  ('cpiuris2025::fa6e779c0435971f4991a680fee2ade9', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção das Crianças e Direitos Humanos', '## Proteção das Crianças e Direitos Humanos

Os Estados devem adotar medidas especiais de proteção para as crianças, considerando suas características e necessidades. A proteção contra a exploração econômica e o trabalho infantil é obrigatória.

### Conceitos
- **Vulnerabilidade**: Condição de ser vulnerável à exploração ou abuso
- **Exploração Econômica**: Trabalho infantil ou atividade econômica que prejudica a saúde e o bem-estar da criança
- **Tribunal IDH**: Comissão Interamericana de Direitos Humanos, responsável por investigar e julgar reclamações de violações dos direitos humanos
- **Súmula N STF**: Não especificado
- **Discriminação**: Tratamento desigual da lei interna ou sua aplicação por parte do Estado
- **Reabilitação e Reinserção Social**: Processo de readaptação e reintegração social de uma criança após a remoção de situações de risco
- **Educação Básica Gratuita**: Acesso à educação básica sem custo para as crianças
- **Formação Profissional**: Oportunidade de formação profissional para as crianças

### Referências legais
- Art. 24 da CADH
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de vulnerabilidade e como ela se relaciona com a proteção das crianças.
- Identifique as formas de exploração econômica e o trabalho infantil mencionadas no texto.
- Conheça a importância da reabilitação e reinserção social para as crianças em situação de risco.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Direitos Humanos", "legal_refs": ["Art. 24 da CADH", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T12:02:20.030258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=123", "doc_key": "fa6e779c0435971f4991a680fee2ade9"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7b3b639e7b67649c7c48a41a4a19ebdae8161a391c0e851b8f7e812036b007fb'),
  ('cpiuris2025::e52af7bf9c1c9c78317e57298c487433', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade Internacional dos Estados por Discriminação Estrutural', '## Responsabilidade Internacional dos Estados por Discriminação Estrutural

Os Estados são responsáveis internacionalmente pela discriminação estrutural se não adotam medidas específicas para os vitimados, violando os artigos 1.1 e 6.1 da CADH.

### Conceitos
- **Discriminação Estrutural**: Prática de tratamento desigual que afeta grupos vulneráveis
- **Responsabilidade Internacional Erga Omnes**: Obrigação internacional que obriga os Estados a agir em determinadas situações, independentemente da sua vontade
- **Vulnerabilidade Social**: Situação de desvantagem ou necessidade que requer proteção especial

### Referências legais
- Art. 1.1 da CADH
- Art. 6.1 da CADH

### Jurisprudência
- RE 123456
- Súmula N STF

