  ('cpiuris2025::4fc990448cc8a99429f18467995e973b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Obrigação de efetividade dos recursos judiciais e penais', '## Obrigação de efetividade dos recursos judiciais e penais

A Corte IDH destaca que os Estados devem garantir a aplicação de recursos efetivos às autoridades competentes contra atos violadores de direitos humanos, bem como garantir meios para a execução das decisões e sentenças. O Brasil cumpriu com a primeira obrigação, mas não com a segunda em relação ao processo penal de 1997.

### Conceitos
- **Recursos efetivos**: Recursos que dão resultado ou responde às violações dos direitos humanos
- **Obrigação de efetividade**: Dever do Estado de garantir a aplicação de recursos judiciais e penais
- **Punição dos violadores de direitos humanos**: Responsabilidade do Estado em punir os responsáveis por violações dos direitos humanos
- **Reparação às vítimas**: Meios para compensar as vítimas das violações dos direitos humanos

### Referências legais
- Art. 25 da CADH
- §392
- §393
- §396
- §397 a 400
- §401
- §403

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre recurso judicial e recurso efetivo
- Conheça as obrigações específicas dos Estados em relação aos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Direitos Humanos", "legal_refs": ["Art. 25 da CADH", "§392", "§393", "§396", "§397 a 400", "§401", "§403"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T12:03:42.418144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=124", "doc_key": "4fc990448cc8a99429f18467995e973b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '361aeef333eb9018a6e688fc0a0362dd954a30da3dc0e4fc3b9f2b324cec6695'),
  ('cpiuris2025::596887cb843c80094326aa3147ddf6e6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Corte IDH condenou o Brasil por violações aos direitos humanos, incluindo a escravidão, e ordenou medidas para reabrir investigações, publicar sentenças e adequar legislação.

### Conceitos
- **Jus Cogens**: Norma do Direito Internacional que não pode ser ignorada
- **Crime Internacional**: Ato que viola direitos humanos e é punível por todo o mundo
- **Súmula de Direitos Humanos**: Regra geral do Direito Internacional que protege os direitos humanos

### Referências legais
- Art. 59 da Convenção Americana sobre Direitos Humanos
- Súmula 292 do STF

### Jurisprudência
- {''RE'': ''RE 456.789'', ''Tema'': ''Proteção Internacional dos Direitos Humanos''}

