  ('cpiuris2025::937c9bf42896e44b31892428b9e6411f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Caso Cosme Rosa Genoveva vs. Brasil', '## Caso Cosme Rosa Genoveva vs. Brasil

O Brasil foi condenado pela Corte IDH por falhas e demoras na investigação e punição de agentes estatais por homicídio e violações a direitos humanos em uma favela.

### Conceitos
- **Caso Cosme Rosa Genoveva**: Nome do caso
- **Favela Nova Brasília**: Nome da favela onde ocorreram os eventos
- **CIDH**: Comissão Interamericana de Direitos Humanos
- **Corte IDH**: Comissão Interamericana de Direitos Humanos (córtex)
- **Punição de agentes estatais**: Investigação e punição de agentes do Estado por crimes cometidos
- **Direitos humanos**: Direitos fundamentais garantidos pela Constituição e leis internacionais

### Referências legais
- Art. 19 da Convenção Americana sobre Direitos Humanos

### Jurisprudência
- Súmula 281 do STF

### Dicas de prova
