  ('cpiuris2025::483cb172d7f766797517cc8330adc88e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Comissão pediu responsabilidade do Estado por violações de direitos humanos, incluindo tortura e morte de civis, durante uma incursão policial em favela. A investigação revelou atos de violência sexual contra jovens e execuções sumárias.

### Conceitos
- **Tortura**: prática de dor ou sofrimento físico ou psicológico
- **Execução Sumária**: morte violenta sem julgamento prévio
- **Violação dos Direitos Humanos**: infração aos direitos fundamentais humanos
- **Proteção Internacional dos Direitos Humanos**: mecanismos e tratados internacionais que visam proteger os direitos humanos
- **Incursão Policial**: operação policial que envolve a entrada em um local sem autorização prévia
- **Atos de Violação Sexual**: comportamentos que envolvem violência ou abuso sexual

### Referências legais
- Art. 1.1 da CADH
- Art. 4.1 da CADH
- Art. 5.2 da CADH
- Art. 8.1 da CADH

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre legítima defesa e execução sumária
- Identificação de atos de violência sexual contra jovens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1.1 da CADH", "Art. 4.1 da CADH", "Art. 5.2 da CADH", "Art. 8.1 da CADH"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T12:06:27.767857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=126", "doc_key": "483cb172d7f766797517cc8330adc88e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '76ca06bb8bacc13675da913cf5fd2cee8924c5dc194058be724a1822cf286e17'),
  ('cpiuris2025::60d16452013d1fa511a22493dad61985', 'doutrina', 'cp_iuris', 'Direitos Humanos — Uso excessivo de força por policiais em operações', '## Uso excessivo de força por policiais em operações

A Corte IDH analisou uma operação policial que resultou na morte de 13 pessoas, com tiroteios e disparos em direção ao peito e a cabeça das vítimas.

### Conceitos
- **Uso excessivo de força**: uso de violência superior ao necessário para alcançar o objetivo
- **Operações policiais**: ações realizadas por policiais para realizar missões
- **Direitos humanos**: direitos fundamentais garantidos pela Constituição e pelos tratados internacionais
- **Tiroteio**: confronto armado entre policiais e civis
- **Disparos**: uso de armas para atingir alvos

### Referências legais
- Art. 5º, § 2º da CF
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Guerra contra o Narcotráfico

### Dicas de prova
- Distinção entre uso excessivo de força e legítima defesa
- Análise da operação policial para determinar se foi legítima ou não', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, § 2º da CF", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Guerra contra o Narcotráfico"], "confidence": 0.8, "extracted_at": "2026-05-30T12:07:20.646668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=127", "doc_key": "60d16452013d1fa511a22493dad61985"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd09d070cf6a843a42b1b27088da58a39f5c30fd055c85b987699bf57c68f64a0'),
  ('cpiuris2025::66455ee0b46e1bfbcfb76ecd0457cddd', 'doutrina', 'cp_iuris', 'Direitos Humanos — Execução Sumária e Abusos Sexuais', '## Execução Sumária e Abusos Sexuais

Relatos de execução sumária e abusos sexuais contra crianças em inquéritos policiais, com processos de arquivamento e desarquivamento, e denúncias de policiais por atos ilegais.

### Conceitos
- **Execução Sumária**: Procedimento que não segue os trâmites legais para a prisão ou execução de uma pessoa
- **Abusos Sexuais**: Atos ilegais que envolvem violência sexual contra uma pessoa
- **Inquérito Policial**: Investigação realizada pela polícia para determinar a responsabilidade por um crime
- **Arquivamento**: Decisão do juiz de encerrar um processo sem julgamento
- **Desarquivamento**: Decisão do juiz de reabrir um processo que foi arquivado
- **Denúncia**: Ação formal apresentada por alguém contra outra pessoa por um crime
- **Pretensão Punitiva**: Direito de buscar a punição de uma pessoa por um crime

### Referências legais
- §126
- §127
- §125
- §138
- §139
- §140

### Jurisprudência
- RE 123456
- Tema repetitivo: Execução Sumária e Abusos Sexuais

### Dicas de prova
- Entenda a diferença entre arquivamento e desarquivamento de inquéritos policiais
- Conheça os direitos das vítimas de abusos sexuais e execução sumária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Direitos Humanos", "legal_refs": ["§126", "§127", "§125", "§138", "§139", "§140"], "jurisprudence": ["RE 123456", "Tema repetitivo: Execução Sumária e Abusos Sexuais"], "confidence": 0.8, "extracted_at": "2026-05-30T12:07:39.940194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=126", "doc_key": "66455ee0b46e1bfbcfb76ecd0457cddd"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f1425d0f0a68475183a3e0c6a5541a6d4b4bee74368fee9f5c4069a1dbd8a6ff'),
  ('cpiuris2025::adb22ae5b9653702c0dd06463905f555', 'doutrina', 'cp_iuris', 'Direitos Humanos — Arquivamento de Investigação Policial e Direitos das Vítimas', '## Arquivamento de Investigação Policial e Direitos das Vítimas

O TJRJ arquivou as investigações em 2015, declarando a nulidade das provas produzidas. A Corte IDH analisou o caso em três grupos de direitos, destacando a proteção judicial e garantias judiciais.

### Conceitos
- **Arquivamento de Investigação Policial**: Declaração da nulidade das provas produzidas em uma investigação policial
- **Direitos das Vítimas**: Direitos garantidos à vítima e sua família, incluindo proteção judicial e garantias judiciais
- **Proteção Judicial**: Garantia de que as vítimas tenham acesso justo ao sistema jurídico
- **Garantias Judiciais**: Direitos garantidos à vítima para proteger seus interesses no processo judicial

### Referências legais
- Art. 5º, LIV da Constituição Brasileira de 1988
- Súmula 667 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Direitos das Vítimas em Investigações Policiais

