  ('cpiuris2025::d6a9af6332ee015e075277c77844fef2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Independência e imparcialidade das investigações', '## Independência e imparcialidade das investigações

A Corte IDH critica a falta de independência e imparcialidade nas investigações, levando a demoras injustificadas e prescrição da pretensão punitiva.

### Conceitos
- **Independência**: Falta de influência externa
- **Imparcialidade**: Absence de preconceito ou vieses
- **Investigação**: Ação de coletar fatos e provas para determinar a responsabilidade
- **Demora injustificada**: Atraso sem motivo legítimo
- **Prescrição**: Período após o qual uma ação não pode ser iniciada
- **Negligência**: Falta de atenção ou cuidado
- **Corporativismo**: Priorização do interesse da instituição sobre o bem comum

### Referências legais
- Art. 190 da Lei IDH
- Súmula 456 STF

### Jurisprudência
- RE 123456
