Sentença destaca os principais pontos da proteção internacional dos direitos humanos, incluindo o dever do Estado de oferecer recursos judiciais efetivos para as vítimas de violações de direitos humanos e a importância da investigação independente e imparcial.

### Conceitos
- **Dever do Estado**: Obrigação positiva do Estado de adoção de condutas que se relacionam diretamente com o direito substantivo em discussão
- **Investigação independente**: Investigação realizada por órgãos independentes das pessoas e estruturas responsáveis pelo caso concreto
- **Devido processo legal**: Garantia de que o Estado observe procedimentos legais adequados para investigar violações de direitos humanos
- **Investigação médico-legal**: Investigação realizada por órgãos jurisdicionais para determinar a causa da morte ou lesão de uma pessoa
- **Protocolo de Minnesota**: Manual que estabelece princípios para uma eficaz prevenção e investigação das execuções extralegais, arbitrárias ou sumárias

