  ('cpiuris2025::64a1dd9d4f7fcbeaac8e0188451134c2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Estado brasileiro foi condenado a reabrir investigações de violência sexual, garantir o acesso e capacidade de agir das vítimas e oferecer tratamento psicológico e psiquiátrico gratuitamente.

### Conceitos
- **Competência Temporal**: A competência temporal é a limitação do tempo em que um Estado pode investigar e processar uma violação dos direitos humanos.
- **Investigação por Vítimas**: A garantia de que as vítimas sejam ouvidas e suas necessidades sejam atendidas durante a investigação.
- **Discriminação e Violência de Gênero**: A proteção contra a discriminação e violência de gênero é fundamental para garantir o direito à integridade pessoal.
- **Obrigação do Estado**: O Estado tem a obrigação de investigar, processar e punir os responsáveis por violações dos direitos humanos.
- **Responsabilização Internacional**: A responsabilização internacional do Estado significa que ele é condenado a cumprir prestações para garantir o respeito aos direitos humanos.

### Referências legais
- Art. 5.1 da CADH
- §259
- §293
- §296
- ...

