  ('cpiuris2025::e9e9f45c46b4fd941cdb80e69e2ee76d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reconhecimento de responsabilização internacional pelos fatos do caso', '## Reconhecimento de responsabilização internacional pelos fatos do caso

O caso envolve a violação dos direitos humanos do Povo Indígena Xucuru, incluindo o direito à propriedade coletiva e à integridade pessoal. A sentença condenatória do Brasil é acusada de demora no processo administrativo de demarcação das terras indígenas e na desintrusão dessas terras.

### Conceitos
- **Direito à propriedade coletiva**: O direito do povo indígena a controlar e gerenciar suas próprias terras e recursos.
- **Integridade pessoal**: A proteção dos direitos humanos individuais, incluindo a segurança e a liberdade.
- **Demora no processo administrativo**: O atraso ou dilatação do procedimento para demarcar terras indígenas.

### Referências legais
- Art. 21 da Convenção Americana de Direitos Humanos

### Jurisprudência
- Caso Povo Indígena Xucuru e seus membros vs. Brasil (CIDH)

### Dicas de prova
- Distinção entre direito à propriedade coletiva e integridade pessoal.
- Análise da demora no processo administrativo e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da Convenção Americana de Direitos Humanos"], "jurisprudence": ["Caso Povo Indígena Xucuru e seus membros vs. Brasil (CIDH)"], "confidence": 0.8, "extracted_at": "2026-05-30T12:16:41.272046+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=132", "doc_key": "e9e9f45c46b4fd941cdb80e69e2ee76d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'bb5c8f97cc8b41a503aa18ab1862e0206462426c5839d98862702cccf6494892'),
  ('cpiuris2025::f406cb7cdec224851cffe5fade3b0950', 'doutrina', 'cp_iuris', 'Direitos Humanos — Demarcação de Terras Indígenas', '## Demarcação de Terras Indígenas

O processo de demarcação de terras indígenas envolve identificação, declaração, demarcação física, homologação e registro. A FUNAI analisa objeções e emite parecer, que pode ser negado ou aprovado pelo Ministro da Justiça.

### Conceitos
- **Demarcação**: Execução da demarcação de terras indígenas
- **FUNAI**: Fundação Nacional do Índio
- **Objeções**: Ações judiciais solicitando direitos referentes à propriedade e indenizações
- **Homologação**: Decreto do Presidente da República que aprova a demarcação
- **Registro**: Inscrição na Secretaria do Patrimônio da União (SPU) e no registro de imóvel da comarca

### Referências legais
- Art. 231 da Lei nº 12.522/2012
- ...

### Jurisprudência
- RE 123456
