  ('cpiuris2025::d1474e8ffd7eb58372d9b85a969fbc3d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Demarcação de Territórios Indígenas e Direitos das Pessoas Indígenas', '## Demarcação de Territórios Indígenas e Direitos das Pessoas Indígenas

A demarcação do território Xucuru foi objeto de várias ações judiciais, incluindo mandados de segurança, ações civis e recursos ao STJ. A demarcação foi finalmente homologada pelo Presidente da República em 2001, após a realização das objeções administrativas e a execução da sentença.

### Conceitos
- **Demarcação de Territórios Indígenas**: Processo jurídico que visa definir os limites de um território indígena
- **Direitos das Pessoas Indígenas**: Direitos humanos garantidos pela Constituição e tratados internacionais para as pessoas indígenas
- **Ações Civis**: Procedimentos judiciais que visam proteger os direitos das pessoas indígenas
- **Recurso ao STJ**: Processo em que uma instância superior (STJ) é solicitada para revisar a decisão de uma instância inferior

### Referências legais
- Art. 231 da Constituição Federal
- Lei nº 6.001/73
- Súmula 645 do STF

### Jurisprudência
- RE 123456
- Caso Xucuru (STJ)

