  ('cpiuris2025::65c853ec024741c613fcbdc485a0df4e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção dos Direitos Indígenas', '## Proteção dos Direitos Indígenas

A sentença transitou em julgado após ações recursais relacionadas à demarcação de terra indígena, com condenação da FUNAI por perdas e danos. O caso envolve atos de violência contra o povo Xucuru.

### Conceitos
- **Demarcação de Terras Indígenas**: Procedimento para definir as fronteiras de terras indígenas
- **Ações Recursais**: Processos que visam revisar ou alterar uma decisão anterior
- **Perdas e Danos**: Condenação de uma parte por danos causados à outra
- **Violação dos Direitos Humanos**: Comportamento que viola os direitos fundamentais de uma pessoa ou grupo

### Referências legais
- Art. 231 da Lei nº 9.433/1997 (Lei Indígena)

### Jurisprudência
- RE 123456 (Relatores: [nome dos relatores])
