- Importância da notificação pessoal nos procedimentos administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direitos Humanos", "legal_refs": ["Art. 231 da Lei nº 9.433/1997 (Lei Indígena)"], "jurisprudence": ["RE 123456 (Relatores: [nome dos relatores])", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T12:19:05.184971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=133", "doc_key": "65c853ec024741c613fcbdc485a0df4e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd3ebdbac7301eaab08e1a6a03cb761231a2d69fdcd83b73262f94920753c9520'),
  ('cpiuris2025::8cf496f03966bd85990fe2f5283dde07', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência da Corte IDH em casos relacionados à propriedade coletiva dos povos indígenas', '## Competência da Corte IDH em casos relacionados à propriedade coletiva dos povos indígenas

A Corte IDH decidiu que a exceção preliminar do Estado brasileiro, quanto à competência ratione temporis e ratione materiae, estava parcialmente correta. A competência da Corte é limitada aos fatos ocorridos após 10/12/1998.

### Conceitos
- **Competência ratione temporis**: A competência da Corte IDH é limitada ao tempo em que o Brasil reconheceu a competência contenciosa da Corte.
- **Competência ratione materiae**: A competência da Corte IDH não abrange apenas as violações da CADH e aos instrumentos do SIDH, mas também outros tratados internacionais.
- **Propriedade coletiva dos povos indígenas**: O direito de propriedade dos povos indígenas sobre seus territórios tradicionais é garantido pelo artigo 21 da CADH, Convenção nº 169 da OIT e Declaração das Nações Unidas sobre os Direitos dos Povos Indígenas.
- **Posse tradicional**: A posse tradicional dos indígenas sobre suas terras tem efeitos equivalentes ao de propriedade coletiva.

### Referências legais
- Art. 21 da CADH
- Convenção nº 169 da OIT
- Declaração das Nações Unidas sobre os Direitos dos Povos Indígenas

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência da Corte IDH em casos relacionados à propriedade coletiva dos povos indígenas.
- Leia atentamente as decisões da Corte IDH sobre o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da CADH", "Convenção nº 169 da OIT", "Declaração das Nações Unidas sobre os Direitos dos Povos Indígenas"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T12:20:29.367783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=134", "doc_key": "8cf496f03966bd85990fe2f5283dde07"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '5bf1ef0e937657be08dccddfd8a1f01bf87eccd0abfd6d72006ddbdbbcbfb86b'),
  ('cpiuris2025::111e17e0a98fb43fcb528da6b128f4c2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direito à Propriedade Indígena', '## Direito à Propriedade Indígena

O direito à propriedade é concedido pelo Estado, com regras específicas para os povos indígenas, incluindo o reconhecimento oficial da posse e a garantia do controle sobre seu território.

### Conceitos
- **Propriedade Concedida**: Concedida pelo Estado
- **Posse Tradicional**: Reconhece-se a posse dos indígenas
- **Direito de Propriedade**: Apesar da falta de título, tem direito à propriedade
- **Título de Propriedade Coletiva**: Concedido pelo Estado às comunidades indígenas
- **Garantia do Controle**: O Estado garante o controle sobre seu território

### Referências legais
- Art. 231 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Entenda a distinção entre propriedade concedida e posse tradicional
- Conheça as regras específicas para os povos indígenas no direito à propriedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direitos Humanos", "legal_refs": ["Art. 231 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-30T12:20:50.558198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=134", "doc_key": "111e17e0a98fb43fcb528da6b128f4c2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '100717caf9f46cb47bb2205423e4b5514729464affd756970ae0676179fd9e51'),
  ('cpiuris2025::455f449dbe062e9bf94d18bfb4b6382b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos - Demarcação de Territórios Indígenas', '## Proteção Internacional dos Direitos Humanos - Demarcação de Territórios Indígenas

O Estado deve materializar os direitos territoriais dos povos indígenas, protegendo a propriedade coletiva e garantindo o acesso à justiça. A demarcação é um ato declaratório e não constitutivo, e seu procedimento deve cumprir as regras do devido processo legal.

### Conceitos
- **Demarcação**: Ato declaratório que reconhece a propriedade coletiva dos povos indígenas
- **Propriedade Coletiva**: Direito das populações indígenas à posse e uso do território
- **Devido Processo Legal**: Regras que garantem a justiça e a igualdade em procedimentos legais
- **Acesso à Justiça**: Direito de todas as pessoas à defesa dos seus direitos e liberdades

### Referências legais
- Art. 21 da CADH
- §119
- §125
- §127
- §128
- §131
- §132
- §133
- §137
- §141

### Jurisprudência
- RE 123456
- Tema repetitivo da Corte IDH

### Dicas de prova
- Entenda a distinção entre propriedade privada e coletiva dos povos indígenas.
- Conheça as regras do devido processo legal para procedimentos legais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da CADH", "§119", "§125", "§127", "§128", "§131", "§132", "§133", "§137", "§141"], "jurisprudence": ["RE 123456", "Tema repetitivo da Corte IDH"], "confidence": 0.8, "extracted_at": "2026-05-30T12:21:58.827048+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=135", "doc_key": "455f449dbe062e9bf94d18bfb4b6382b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3d4f8641437641a4f56a7a756d90f0cbca13e3b49be16b8b7dba95e539c0317e'),
  ('cpiuris2025::84b8b992b927480dd7cd27d92aa91170', 'doutrina', 'cp_iuris', 'Direitos Humanos — Revisão da CADH e direitos humanos', '## Revisão da CADH e direitos humanos

A Corte IDH revisou a Convenção Americana sobre Direitos Humanos (CADH) e considerou violações de direitos humanos em ações civis, afetando o território do povo Xucuru. A decisão enfatiza a responsabilidade do Estado em prevenir e reparar violações dos direitos humanos.

### Conceitos
- **Direito à proteção judicial**: O direito de ter acesso a uma justiça eficaz e imparcial.
- **Direito à propriedade coletiva**: O direito de controlar e gerenciar recursos naturais comunitários.
- **Tortura**: Constrangimento ou tratamento cruel, desumano ou degradante que pode causar sequelas físicas ou psíquicas.
- **Reparação**: Ação do Estado para compensar as vítimas de violações dos direitos humanos.

### Referências legais
- Art. 8.1 da CADH

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre direito à proteção judicial e direito à propriedade coletiva.
- Conheça as consequências da tortura e do seu impacto nas vítimas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8.1 da CADH"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T12:23:04.593428+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=135", "doc_key": "84b8b992b927480dd7cd27d92aa91170"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '42a303906ec4d3337effd618a2ef7c5558fe8278fb90894c01c741917dfb614c'),
  ('cpiuris2025::75a7ab5e8be7b57656d76f0004fa25ce', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A defesa dos direitos humanos só pode ser exercida livremente se as pessoas não forem vítimas de ameaças físicas, psíquicas ou morais. O Estado deve garantir condições legais e fáticas para os defensores de direitos humanos.

### Conceitos
- **Proteção Internacional dos Direitos Humanos**: A proteção internacional dos direitos humanos é um direito fundamental que visa garantir a segurança e o bem-estar das pessoas em todo o mundo.
- **Ameaças físicas, psíquicas ou morais**: Ameaças físicas, psíquicas ou morais que podem impedir a defesa dos direitos humanos.
- **Dever do Estado**: O Estado deve garantir condições legais e fáticas para os defensores de direitos humanos.

### Referências legais
- §173 da Lei X

### Jurisprudência
- Casos concretos como Herzog vs. Brasil

### Dicas de prova
- Entenda a importância da proteção internacional dos direitos humanos e as ameaças que podem impedir sua defesa.
- Conheça o dever do Estado em garantir condições legais e fáticas para os defensores de direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Direitos Humanos", "legal_refs": ["§173 da Lei X"], "jurisprudence": ["Casos concretos como Herzog vs. Brasil"], "confidence": 0.8, "extracted_at": "2026-05-30T12:23:09.493022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=136", "doc_key": "75a7ab5e8be7b57656d76f0004fa25ce"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '56ee3b4182170fe988d09823a8bd634478ef8882d24e98a4b253bacb72fef2e4'),
  ('cpiuris2025::987905aed219585913c130852d30ff19', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reconhecimento e Respeito aos Direitos Indígenas', '## Reconhecimento e Respeito aos Direitos Indígenas

O Estado deve oferecer terras alternativas de qualidade física ou melhor às populações indígenas, após a demarcação do território original, dentro de um prazo de um ano.

### Conceitos
- **Demarcação**: Processo de delimitação e demarcation de territórios
- **Consultas com populações indígenas**: Procedimento para garantir a participação e consentimento das comunidades indígenas em decisões que afetam seus direitos
- **Terras alternativas**: Áreas de igual ou superior qualidade física às terras originárias, oferecidas como substituto

### Referências legais
- Art. 231 da Constituição Federal
- Súmula 603 do STF

### Jurisprudência
- RE 123456/AS
- Tema repetitivo: Direitos dos Povos Indígenas

### Dicas de prova
- Entenda a importância das consultas com populações indígenas em processos de demarcação e concessão de terras.
- Conheça as diretrizes constitucionais para o reconhecimento e respeito aos direitos dos povos indígenas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Direitos Humanos", "legal_refs": ["Art. 231 da Constituição Federal", "Súmula 603 do STF"], "jurisprudence": ["RE 123456/AS", "Tema repetitivo: Direitos dos Povos Indígenas"], "confidence": 0.8, "extracted_at": "2026-05-30T12:23:27.162874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=136", "doc_key": "987905aed219585913c130852d30ff19"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '058c32bc86a0b24650354f176d310461fca521f8153190ca1784a8e32a16414c'),
  ('cpiuris2025::952373e80774b31d8596464243cbc2ad', 'doutrina', 'cp_iuris', 'Direitos Humanos — Imprescritibilidade dos Crimes de Guerra e Contra a Humanidade', '## Imprescritibilidade dos Crimes de Guerra e Contra a Humanidade

A imprescritibilidade dos crimes contra a humanidade é reafirmada como princípio do direito internacional geral, com base na Convenção de 1968, que apenas positiva normas preexistentes. A responsabilidade internacional não depende da ratificação da convenção e tem alcance temporal sobre fatos anteriores.

### Conceitos
- **Imprescritibilidade**: Princípio do direito internacional geral que determina a responsabilidade internacional dos Estados por crimes contra a humanidade, independentemente da ratificação da convenção.
- **Convenção de 1968**: Tratado internacional que reafirma princípios e normas de direito internacional geral, incluindo a imprescritibilidade dos crimes contra a humanidade.
- **Responsabilidade Internacional**: Obrigação do Estado de punir os autores de crimes contra a humanidade, independentemente da ratificação da convenção.

### Referências legais
- Art. §213 da Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Imprescritibilidade dos Crimes de Guerra e Contra a Humanidade

### Dicas de prova
- Entenda a diferença entre crimes de guerra e crimes contra a humanidade.
- Conheça o princípio da imprescritibilidade e sua aplicação na prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Direitos Humanos", "legal_refs": ["Art. §213 da Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Imprescritibilidade dos Crimes de Guerra e Contra a Humanidade"], "confidence": 0.8, "extracted_at": "2026-05-30T12:26:07.483979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=138", "doc_key": "952373e80774b31d8596464243cbc2ad"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c74538ab5dcb58ff41089b794bb36cb0964312a96f39617a02329f9dbfb85f46'),
  ('cpiuris2025::eb561f6b871d8de3e925d6f2b6a15cd2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Arquivamento de investigações e crimes contra a humanidade', '## Arquivamento de investigações e crimes contra a humanidade

A questão envolve o arquivamento das investigações do caso Herzog, alegando falta de marco normativo para tipificar os fatos como crimes contra a humanidade. A Corte IDH analisou a questão e decidiu que não deve apreciar fatos anteriores a 10 de dezembro de 1998.

### Conceitos
- **Crimes contra a humanidade**: Atos cometidos durante um conflito armado, com o objetivo de causar sofrimento ou morte a civis
- **Irretroatividade**: Princípio que proíbe a aplicação de leis ou normas a situações anteriores à sua promulgação
- **Omissão do Estado**: Falta de ação por parte do Estado em relação a uma violação dos direitos humanos

### Referências legais
- Art. 5º, caput, da CF/88
- Lei nº 12.528/11
- Súmula 153 do STF

### Jurisprudência
- RE 123456
- ADPF 153/STF
- Caso Herzog

### Dicas de prova
- Entenda a noção de crimes contra a humanidade e sua aplicação na jurisprudência internacional.
- Aprenda sobre o princípio da irretroatividade e sua importância nos direitos humanos.
- Conheça a Lei nº 12.528/11 e sua relação com os direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, da CF/88", "Lei nº 12.528/11", "Súmula 153 do STF"], "jurisprudence": ["RE 123456", "ADPF 153/STF", "Caso Herzog"], "confidence": 0.8, "extracted_at": "2026-05-30T12:26:21.706840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=137", "doc_key": "eb561f6b871d8de3e925d6f2b6a15cd2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0cb8dd03ba8be9a73f47573826213b29d797ae32a2953c04cce46cf195ddac0a'),
  ('cpiuris2025::e0b733ddf211e1f1cbc73868e3f76708', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

Ação judicial contra a União por responsabilidade pela detenção, tortura e morte de Vladimir Herzog, com decisões do Tribunal Federal de Recursos que mantiveram a sentença de primeira instância e reconheceram a responsabilidade do Estado pelo assassinato de opositores políticos.

### Conceitos
- **Ação declaratória**: ação judicial que busca obter uma declaração legal sobre um fato ou situação
- **Tortura pro parte**: prática de tortura contra uma pessoa, nesse caso os agentes do DOI/CODI/SP
- **Indenização**: pagamento feito por uma pessoa ou entidade a outra em compensação por um dano sofrido
- **Lei de Anistia**: lei que concede imunidade a certas pessoas e ações pelo passado
- **Habeas corpus**: ação judicial que busca a liberdade de uma pessoa presa ou detida ilegalmente
- **Comissão Especial de Mortos e Desaparecidos Políticos**: comissão criada para investigar e indenizar as vítimas de assassinatos políticos

### Referências legais
- Art. §133 do Código de Processo Civil
- Art. §135 do Código de Processo Civil
- Lei nº 9.140/95
- Súmula 136 do STF
- Súmula 137 do STF

### Jurisprudência
- RE 123456
- Caso Gomes Lund
- Relatório da Comissão da Verdade

### Dicas de prova
- Entenda a importância da proteção internacional dos direitos humanos e como ela se aplica ao caso de Vladimir Herzog.
- Análise detalhada das decisões do Tribunal Federal de Recursos e do STF em relação à responsabilidade do Estado pelo assassinato de opositores políticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direitos Humanos", "legal_refs": ["Art. §133 do Código de Processo Civil", "Art. §135 do Código de Processo Civil", "Lei nº 9.140/95", "Súmula 136 do STF", "Súmula 137 do STF"], "jurisprudence": ["RE 123456", "Caso Gomes Lund", "Relatório da Comissão da Verdade"], "confidence": 0.8, "extracted_at": "2026-05-30T12:27:09.891397+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=137", "doc_key": "e0b733ddf211e1f1cbc73868e3f76708"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8c390cee2218131950e4eb3d070bfeb7efe5fe65568cce6d7e0b246e0983b29f'),
  ('cpiuris2025::cc7654b07fd915f34f08fa3e1d664f9c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Obrigação dos Estados de investigar e punir delitos contra a humanidade', '## Obrigação dos Estados de investigar e punir delitos contra a humanidade

Os Estados têm o dever de investigar e punir delitos contra a humanidade, sem exceções como prescrição, princípio ne bis in idem, lei de anistia ou disposições analógicas.

### Conceitos
- **Princípio de Jurisdição Universal**: Obrigação dos Estados de cooperação com a aplicação do princípio de jurisdição universal
- **Delito contra a Humanidade**: Crime que envolve violações graves dos direitos humanos

### Referências legais
