  ('cpiuris2025::fa5786511af3036382102cd4ecb382fd', 'doutrina', 'cp_iuris', 'Direitos Humanos — Prestações para as vítimas de tortura e morte', '## Prestações para as vítimas de tortura e morte

Regras para a proteção das vítimas de tortura e morte, incluindo investigações, julgamentos e indenizações.

### Conceitos
- **Imprescritibilidade dos crimes contra a humanidade**: Crimes que não prescrevem por tempo determinado
- **Lei de Anistia**: Lei que exclui responsabilidade por certos atos
- **Ne bis in idem**: Não se pode julgar alguém duas vezes pelo mesmo crime
- **Prescrição**: Período de tempo após o qual um direito ou ação não pode ser exercida

### Referências legais
- Art. 5º, caput, da CF
- Lei nº 9.313/96

### Jurisprudência
- Súmula 326 do STF

