- Entenda a noção de imprescritibilidade dos crimes contra a humanidade
- Conheça as regras da Lei de Anistia e Ne bis in idem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, da CF", "Lei nº 9.313/96"], "jurisprudence": ["Súmula 326 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T12:30:00.277317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=140", "doc_key": "fa5786511af3036382102cd4ecb382fd"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '5a2939d167d588ea7887319281be32fc00d668eeadd274e4aeb4d54d387b9b81'),
  ('cpiuris2025::20402304a32ec6ad39ff69ec8bd40e11', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O texto discute a proteção internacional dos direitos humanos, destacando a responsabilidade do Estado em investigar e punir os agentes responsáveis por crimes contra a humanidade, bem como o direito de conhecer a verdade das vítimas.

### Conceitos
- **Crime contra a Humanidade**: Ato cometido com intenção de causar sofrimento ou morte em massa
- **Prescrição**: Prazo para processar um crime após o término do período de prescricao
- **Ne Bis in Idem**: Princípio que proíbe a aplicação da mesma pena a duas pessoas por mesmos fatos
- **Cadeja Material**: Decisão final de um tribunal que não pode ser alterada por outro tribunal
- **Lei de Anistia**: Lei que perdoa os crimes cometidos antes dela
- **Controle de Convencionalidade**: Ação do Estado para verificar se uma lei ou tratado internacional está em conformidade com as normas internacionais
- **Garantias Judiciais**: Direitos garantidos ao juiz e ao processo, como a imparcialidade e a liberdade de expressão
- **Proteção Judicial**: Direito do cidadão a ser protegido pelas autoridades judiciais

### Referências legais
- §246
- §269
- §272
- §274
- §275
- §276
- §277
- §278
- §279
- §280
- §281
- §282
- §283
- §284
- §285
- §286
- §287
- §288
- §289
- §290

### Jurisprudência
- RE 123456
- Tema repetitivo da Corte IDH

### Dicas de prova
- Entenda a importância do crime contra a humanidade e a responsabilidade do Estado em investigar e punir os agentes responsáveis.
- Conheça as diferenças entre prescrição, ne bis in idem e cadeja material.
- Aprenda sobre o controle de convencionalidade e suas implicações para o Estado.
- Entenda a importância das garantias judiciais e da proteção judicial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direitos Humanos", "legal_refs": ["§246", "§269", "§272", "§274", "§275", "§276", "§277", "§278", "§279", "§280", "§281", "§282", "§283", "§284", "§285", "§286", "§287", "§288", "§289", "§290"], "jurisprudence": ["RE 123456", "Tema repetitivo da Corte IDH"], "confidence": 0.8, "extracted_at": "2026-05-30T12:30:50.219067+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=139", "doc_key": "20402304a32ec6ad39ff69ec8bd40e11"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '67d3438d0af79073e29a2010c378e537b88a4c95df7950637ce966571dff39aa'),
  ('cpiuris2025::64ecfcfc1c7d493aa0d591d429cd2da5', 'doutrina', 'cp_iuris', 'Direitos Humanos — Trabalho Infantil e Segurança no Trabalho', '## Trabalho Infantil e Segurança no Trabalho

A produção clandestina de fogos de artifício em Santo Antônio de Jesus envolve a exploração de trabalhadores infantis, principalmente mulheres afrodescendentes de baixa renda, sem respeito às normas de segurança e saúde.

### Conceitos
- **Trabalho Infantil**: Trabalho realizado por menores de idade
- **Exploração Laboral**: Uso abusivo da força ou da coerção para obter trabalho
- **Segurança no Trabalho**: Medidas adotadas para proteger a saúde e a segurança dos trabalhadores

### Referências legais
- §62
- §63 a 65

### Dicas de prova
- Distinção entre trabalho infantil e exploração laboral
- Importância da segurança no trabalho em contextos de exploração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direitos Humanos", "legal_refs": ["§62", "§63 a 65"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T12:31:05.205677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=140", "doc_key": "64ecfcfc1c7d493aa0d591d429cd2da5"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e4849dd80e244aaa9db6781598a6ccc8579b82de93c75a0699a7cfdea10c0633'),
  ('cpiuris2025::e2f4308943c69805627265c2519d558e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A explosão em uma fábrica de explosivos causou danos irreparáveis às trabalhadoras, que foram submetidas a condições de trabalho precárias e não receberam tratamento médico adequado. A falta de segurança e regulamentações permitiu o acidente.

### Conceitos
- **Direitos Humanos**: direitos fundamentais das pessoas
- **Proteção Internacional dos Direitos Humanos**: mecanismos legais para proteger os direitos humanos em todo o mundo
- **Trabalho Infantil**: trabalho realizado por crianças antes da idade legal de início do trabalho
- **Segurança no Trabalho**: medidas para prevenir acidentes e lesões no local de trabalho
- **Falta de Segurança**: negligência que resulta em riscos à segurança dos trabalhadores
- **Responsabilidade Estatal**: obrigação do Estado de garantir a proteção dos direitos humanos

### Referências legais
- Art. 7º da Constituição Federal
- Lei nº 11.117/2005

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção dos Direitos Humanos em Situações de Trabalho Infantil

### Dicas de prova
- Distinção entre trabalho infantil e trabalho adulto
- Importância da segurança no trabalho para prevenir acidentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direitos Humanos", "legal_refs": ["Art. 7º da Constituição Federal", "Lei nº 11.117/2005"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção dos Direitos Humanos em Situações de Trabalho Infantil"], "confidence": 0.8, "extracted_at": "2026-05-30T12:32:43.557111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=141", "doc_key": "e2f4308943c69805627265c2519d558e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '77879d3661997fb03a1e1be7e793390250f0b9cc32986ac573718aa19c530484'),
  ('cpiuris2025::f0bc071d6cf678360b1540eca7152462', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reparação por danos causados à população', '## Reparação por danos causados à população

O processo envolveu a denúncia do Ministério Público contra os donos de uma fábrica e outras pessoas, resultando em condenações e absolvições. Após a condenação, foram interpostos recursos e habeas corpus, sendo concedidos alguns e extintos outros. Além disso, foi proposta uma ação civil pública contra os responsáveis pela explosão, com pedido de reparação para as vítimas.

### Conceitos
- **Reparação**: obrigação do Estado de compensar os danos causados à população
- **Denúncia**: ação do Ministério Público para denunciar um crime ou ato ilegal
- **Habeas corpus**: mandado judicial que visa garantir a liberdade de alguém preso injustamente
- **Ação civil pública**: ação jurídica que busca proteger os direitos das pessoas coletivas, como o público-interest

### Referências legais
- §82
- §83
- §84
- §85
- §86
- §87
- §88
- §89

### Dicas de prova
- Entenda a noção de reparação e sua aplicação nos processos criminais
- Conheça o papel do Ministério Público na denúncia de crimes
- A importância da concessão de habeas corpus em casos de preso injustamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direitos Humanos", "legal_refs": ["§82", "§83", "§84", "§85", "§86", "§87", "§88", "§89"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T12:33:34.452945+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=141", "doc_key": "f0bc071d6cf678360b1540eca7152462"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd44373b8979a18bdba357e979a156dd919134eb99f88277ecda1da2026a25134'),
  ('cpiuris2025::a01012d7eefc19dcf1989d0cb9b49fac', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reparação de danos e responsabilidade internacional dos Estados', '## Reparação de danos e responsabilidade internacional dos Estados

A Corte IDH analisou a responsabilidade internacional dos Estados em relação à reparação de danos causados às vítimas, estabelecendo obrigações erga omnes para garantir e respeitar as normas da Convenção Americana de Direitos Humanos.

### Conceitos
- **Reparação de danos**: compensação para as vítimas de violações dos direitos humanos
- **Responsabilidade internacional dos Estados**: obrigação erga omnes para garantir e respeitar as normas da Convenção Americana de Direitos Humanos
- **Obrigação negativa**: nenhuma pessoa pode ter sua vida privada arbitrariamente, os Estados devem adotar medidas para a proteção e preservação do direito à vida

