- Art. 19 da CADH
- §115 da CADH
- §116 da CADH
- §91 da CADH

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade internacional dos Estados

### Dicas de prova
- Entenda a noção de reparação de danos e sua importância na proteção dos direitos humanos.
- Conheça as obrigações erga omnes dos Estados em relação à Convenção Americana de Direitos Humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1.1 da CADH", "Art. 4.1 da CADH", "Art. 5.1 da CADH", "Art. 8.1 da Convenção", "Art. 19 da CADH", "§115 da CADH", "§116 da CADH", "§91 da CADH"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade internacional dos Estados"], "confidence": 0.8, "extracted_at": "2026-05-30T12:33:57.315187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=142", "doc_key": "a01012d7eefc19dcf1989d0cb9b49fac"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ba7aae523bdecf9320f8cd35fc731b9de91e158d258c7d8b1a938e9d54c33788'),
  ('cpiuris2025::936d3bf2edeb4d8418f7a7b208715924', 'doutrina', 'cp_iuris', 'Direitos Humanos — O dever do Estado de garantir proteção a direitos humanos', '## O dever do Estado de garantir proteção a direitos humanos

O Estado tem o dever de garantir proteção a direitos humanos, não apenas em relação aos seus agentes, mas também entre particulares sob sua jurisdição. A responsabilidade do Estado depende das circunstâncias do caso concreto.

### Conceitos
- **Garantia de proteção**: O dever do Estado de proteger direitos humanos
- **Vulnerabilidade**: Condição especial que torna uma pessoa mais suscetível a violações de direitos humanos
- **Responsabilidade do Estado**: Dependência das circunstâncias do caso concreto
- **Regulamentação**: Regras e normas que estabelecem os deveres do Estado
- **Fiscalização**: Ação do Estado para monitorar e controlar atividades perigosas
- **Entidade privada**: Organização não governamental que pode ser responsável por atividades perigosas
- **Concretização das obrigações de garantia**: A realização do dever do Estado em proteger direitos humanos

### Referências legais
- §116
- §117
- §118
- §119
- §120
- §122

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre responsabilidade do Estado e responsabilidade individual
- Análise das circunstâncias do caso concreto é fundamental para determinar a responsabilidade do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Direitos Humanos", "legal_refs": ["§116", "§117", "§118", "§119", "§120", "§122"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T12:35:27.124151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=142", "doc_key": "936d3bf2edeb4d8418f7a7b208715924"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1340377107ac2f7d936ad018b2ce1d16fd09c42f616513f7179ef1ffc177a6ba'),
  ('cpiuris2025::df077d69cd5dae5d066cb0321189a4e6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direito à Condição Equitativa e Satisfatória de Trabalho', '## Direito à Condição Equitativa e Satisfatória de Trabalho

O direito à condição equitativa e satisfatória de trabalho é um direito humano que obriga os estados a garantir as condições necessárias para o exercício do trabalho, sem discriminação ou violência. A exigibilidade desse direito é imediata e progressiva.

### Conceitos
- **Direito à Condição Equitativa e Satisfatória de Trabalho**: O direito humano que obriga os estados a garantir as condições necessárias para o exercício do trabalho, sem discriminação ou violência.
- **Exigibilidade Imediata**: A obrigação de garantir o direito à condição equitativa e satisfatória de trabalho imediatamente, sem a necessidade de progressão.
- **Progressividade**: O dever dos estados de avançar na forma mais eficaz possível para a plena realização do direito, na medida dos recursos disponíveis.

### Referências legais
- Art. 21 da Constituição Brasileira

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Direitos Humanos

### Dicas de prova
- Entenda a distinção entre exigibilidade imediata e progressiva do direito à condição equitativa e satisfatória de trabalho.
- Conheça o artigo 21 da Constituição Brasileira e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T12:36:30.299698+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=143", "doc_key": "df077d69cd5dae5d066cb0321189a4e6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7453e6c44b653face7ab517ed8b468e81298324064ebf7d3d079cc9b5527e059'),
  ('cpiuris2025::e5d954f20a00cc3005ea0e1bbd185023', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Corte concluiu que o Brasil cumpriu seu dever de regulamentação em relação à fábrica, mas falhou em fiscalizar seu funcionamento. Isso levou a violações dos direitos à vida e à integridade pessoal das vítimas. A sentença enfatizou a importância da proteção dos direitos das crianças, incluindo a proibição de discriminação e o trabalho infantil.

### Conceitos
- **Direito à vida**: O direito fundamental à vida, protegido pela Constituição e tratados internacionais.
- **Direito à integridade pessoal**: O direito à liberdade e segurança pessoal, também protegido pela Constituição e tratados internacionais.
- **Trabalho infantil**: A prática de empregar crianças em atividades perigosas ou prejudiciais à sua saúde e desenvolvimento.
- **Proteção das crianças**: A proteção dos direitos e bem-estar das crianças, incluindo a prevenção do trabalho infantil e a promoção de condições equitativas e satisfatórias no trabalho.
- **Interpretação evolutiva**: Um método interpretativo que considera as mudanças nas circunstâncias sociais e culturais para adaptar os tratados internacionais à realidade atual.
- **Dever de regulamentação**: A obrigação do Estado de regular e fiscalizar a atividade de uma empresa ou organização.
- **Fiscalização**: O ato de controlar e monitorar a conformidade com as leis e normas.
- **Competência**: A autoridade do Estado para tomar decisões e agir em um determinado assunto.

### Referências legais
- Art. 19 da CADH
- Art. 26 do Pacto de San José da Costa Rica
- Art. 45.b21 da Carta da OEA

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da proteção dos direitos das crianças e o impacto do trabalho infantil.
- Conheça os tratados internacionais que regulamentam o direito ao trabalho e à segurança no local de trabalho.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direitos Humanos", "legal_refs": ["Art. 19 da CADH", "Art. 26 do Pacto de San José da Costa Rica", "Art. 45.b21 da Carta da OEA"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T12:37:38.888130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=143", "doc_key": "e5d954f20a00cc3005ea0e1bbd185023"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6f14e7b365acfaac9b37c6310778c0f16cc48b858642766814adcc7091fdf006'),
  ('cpiuris2025::675a69e6b06249787f78f9aed984c8c2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Corte IDH condenou o Brasil por violar os artigos 19 e 26 da CADH, devido à discriminação contra crianças que trabalham em condições precárias. Além disso, a Corte destacou a importância do artigo 8.1 da CADH para garantir o devido processo legal e o acesso a recursos judiciais eficazes.

### Conceitos
- **Discriminação**: Ações ou medidas que discriminam indivíduos ou grupos com base em características como idade, gênero, raça ou condição econômica.
- **Igualdade Material**: O direito de todos serem tratados igualmente perante a lei e os tribunais, sem distinção de qualquer natureza.
- **Devido Processo Legal**: O direito de todos terem acesso a um processo justo e imparcial, com garantias de liberdade e segurança.

### Referências legais
- Art. 19 da CADH
- Art. 26 da CADH
- Art. 8.1 da CADH
- Art. 25 da Convenção sobre os Direitos da Criança

### Jurisprudência
- Caso Trabalhadores da Fazenda Brasil Verde vs. Brasil

### Dicas de prova
- Entenda a importância do artigo 8.1 da CADH para garantir o devido processo legal.
- Identifique as características que definem discriminação e igualdade material.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.144 (1)", "page_number": 144, "discipline": "Direitos Humanos", "legal_refs": ["Art. 19 da CADH", "Art. 26 da CADH", "Art. 8.1 da CADH", "Art. 25 da Convenção sobre os Direitos da Criança"], "jurisprudence": ["Caso Trabalhadores da Fazenda Brasil Verde vs. Brasil"], "confidence": 0.9, "extracted_at": "2026-05-30T12:37:57.154062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=144", "doc_key": "675a69e6b06249787f78f9aed984c8c2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'be68458a7263ee8fc6f01692971249ef673230acb4b0be2ecda878117238b584'),
  ('cpiuris2025::d3edab90c50c8cd68d625e68c791d138', 'doutrina', 'cp_iuris', 'Direitos Humanos — Devida Diligência e Prazo Razão', '## Devida Diligência e Prazo Razão

A devida diligência é verificada na condução de procedimentos para identificar responsáveis e reparar vítimas. O prazo razoável é calculado considerando complexidade, conduta das autoridades judiciais e prejuízo à situação jurídica da vítima.

### Conceitos
- **Devida Diligência**: Condução de procedimentos para identificar responsáveis e reparar vítimas
- **Prazo Razão**: Duração total entre distribuição do processo e sentença definitiva, considerando complexidade, conduta das autoridades judiciais e prejuízo à situação jurídica da vítima

### Referências legais
- §221
- §223
- §227

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de devida diligência e prazo razoável em processos civis, trabalhistas e administrativos.
- Identifique a importância da conduta das autoridades judiciais na determinação do prazo razoável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.144 (2)", "page_number": 144, "discipline": "Direitos Humanos", "legal_refs": ["§221", "§223", "§227"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T12:38:01.999171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=144", "doc_key": "d3edab90c50c8cd68d625e68c791d138"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8670b097b1eb747b3fe7171cdd07e9ee28d44c52bfb2e17f96b4e75d255d52a7'),
  ('cpiuris2025::0d176b47fc4b5e4900a01c760f3d87bf', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O texto destaca a importância da proteção internacional dos direitos humanos, incluindo a transmissão de informações sobre casos graves nas redes sociais e a realização de atos públicos de reconhecimento de responsabilização internacional.

### Conceitos
- **Diretrizes Nacionais sobre Empresas e Direitos Humanos**: Normas que regulamentam as empresas em relação aos direitos humanos
- **Danos Materiais**: Compensação financeira por danos causados a terceiros
- **Indenização por Danos Morais**: Compensação financeira por sofrimento emocional ou psicológico

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Caso Barbosa de Souza e outros vs. Brasil

