  ('cpiuris2025::a6255e1df4433d7878121004d0a175cc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Corte IDH analisou atrasos injustificados das autoridades judiciais na responsabilização dos donos de uma fábrica por um acidente, violando o dever do Estado de garantir um prazo razoável para o pagamento de indenizações.

### Conceitos
- **Dever do Estado**: Obrigação do Estado de agir dentro de um prazo razoável
- **Garantia de proteção judicial efetiva**: Direito à proteção eficaz dos direitos humanos por parte do Estado
- **Prazo razoável**: Prazo estabelecido pelo direito para o pagamento de indenizações

