  ('cpiuris2025::87aadd61d40cb08b6e7cd4c32ad270ae', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade Internacional do Estado por Dano a Direitos Humanos', '## Responsabilidade Internacional do Estado por Dano a Direitos Humanos

O Brasil foi condenado a cumprir com várias prestações para reparar os danos causados às vítimas da explosão da fábrica de fogos de Santo Antônio de Jesus, incluindo investigações, ressarcimento, tratamento médico e psicológico, publicação de sentenças e medidas de transparência.

### Conceitos
- **Responsabilidade Internacional do Estado**: Obrigação do Estado de reparar danos causados a indivíduos ou grupos em virtude de ações ou omissões internacionais.
- **Reparação Integral**: Conceito que abrange todas as medidas necessárias para reparar os danos causados, incluindo indenização, medidas de reparação e medidas de prevenção futuras.
- **Investigação e Punição**: Necessidade de investigar e punir os responsáveis pelos atos que causaram o dano.
- **Ressarcimento**: Pagamento feito às vítimas para compensá-las pelo dano causado.
- **Tratamento Médico e Psicológico**: Medidas de saúde necessárias para tratar os efeitos do trauma causado ao indivíduo.
- **Publicação de Sentenças**: Requisito de publicar as sentenças em diferentes meios, garantindo transparência e acesso à justiça.
- **Transparência**: Necessidade de informar o público sobre as ações do Estado em relação ao dano causado.

### Referências legais
- Art. 23 da Convenção Americana de Direitos Humanos
- Súmula 326 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Responsabilidade Internacional do Estado

### Dicas de prova
- Entenda a noção de responsabilidade internacional do estado e suas implicações.
- Conheça as diferentes medidas de reparação integral, incluindo indenização, medidas de reparação e medidas de prevenção futuras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.145 (2)", "page_number": 145, "discipline": "Direitos Humanos", "legal_refs": ["Art. 23 da Convenção Americana de Direitos Humanos", "Súmula 326 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Responsabilidade Internacional do Estado"], "confidence": 0.8, "extracted_at": "2026-05-30T12:41:45.796674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=145", "doc_key": "87aadd61d40cb08b6e7cd4c32ad270ae"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '01a3e461c3593a94fdef20148151dc4586086672a54094b995a7fec815e3c7f6'),
  ('cpiuris2025::8796cd6a077e39c02a493481bd826b35', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direito à Vida e Segurança Pessoal', '## Direito à Vida e Segurança Pessoal

A estudante Márcia Barbosa de Souza foi vítima de asfixia por sufocamento, resultante de ação mecânica, após ser ligada pelo deputado Aércio Pereira de Lima. O caso destaca a importância da segurança pessoal e do direito à vida.

### Conceitos
- **Asfixia**: Morte causada por falta de oxigênio
- **Ação mecânica**: Fato que causa morte por meio de uma força externa
- **Direito à Vida**: O direito fundamental de todos os seres humanos a viver com dignidade e segurança
- **Segurança Pessoal**: A proteção contra riscos à saúde, segurança e bem-estar pessoal
- **Evasão Escolar**: O fenômeno de menores de idade abandonarem a escola para ingressar no mercado de trabalho
- **Direitos Trabalhistas**: Os direitos garantidos pela lei trabalhista, como o salário mínimo e o descanso semanal

### Referências legais
- § 65
- § 67
- § 68

### Dicas de prova
- Perguntas sobre a responsabilidade do deputado Aércio Pereira de Lima no caso da morte de Márcia Barbosa de Souza
- Distinção entre asfixia e outras causas de morte
- Análise do direito à vida e segurança pessoal em relação às medidas de prevenção e proteção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.146 (2)", "page_number": 146, "discipline": "Direitos Humanos", "legal_refs": ["§ 65", "§ 67", "§ 68"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T12:43:11.788846+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=146", "doc_key": "8796cd6a077e39c02a493481bd826b35"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '50cf4a2e259f11c9ae5d89f76ffc8152cb7d23edabe9ac4f380f5bd66ae4a9b0'),
  ('cpiuris2025::813d4e34f767a4a6d3dc998965987996', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

Aércio Pereira de Lima foi denunciado por homicídio e condenado a 16 anos de reclusão, mas o caso foi arquivado pelo MP em 2003 devido à falta de provas. A Corte IDH fixou sua competência para julgar os fatos ocorridos após o reconhecimento de sua competência contenciosa pelo Brasil.

### Conceitos
- **Competência Contenciosa**: A capacidade do Estado ou da Corte Internacional de decidir sobre uma questão específica
- **Competência Competente**: A capacidade do Estado ou da Corte Internacional de julgar um caso, geralmente com base em sua competência contenciosa
- **Provas Insuficientes**: Falta de evidências suficientes para sustentar uma acusação ou ação judicial
- **Arquivamento do Inquérito**: Decisão do MP de encerrar o inquérito sem prosseguir com as investigações
- **Competência da Corte IDH**: A capacidade da Corte Internacional de julgar casos relacionados a direitos humanos

### Referências legais
- Art. 19 da Convenção Americana sobre Direitos Humanos

### Jurisprudência
- Súmula 283 do STF
- ...

### Dicas de prova
- Entenda a distinção entre competência contenciosa e competente.
- Conheça o conceito de provas insuficientes e como afeta o processo judicial.
- Aprenda com o caso Aércio Pereira de Lima para entender a importância da competência da Corte IDH.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Direitos Humanos", "legal_refs": ["Art. 19 da Convenção Americana sobre Direitos Humanos"], "jurisprudence": ["Súmula 283 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T12:43:35.448319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=147", "doc_key": "813d4e34f767a4a6d3dc998965987996"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '169cf8d28181be00896622c45e1036182dc5b8c45c2008782f62b50772eff1b4'),
  ('cpiuris2025::aaac46eb9a4306fa16787ece3fbaba51', 'doutrina', 'cp_iuris', 'Direitos Humanos — Garantia de Imunidade Parlamentar e Proteção Judicial', '## Garantia de Imunidade Parlamentar e Proteção Judicial

A Corte IDH analisou a imunidade parlamentar e sua relação com a proteção judicial, garantias judiciais e direito à igualdade perante a lei.

### Conceitos
- **Imunidade Parlamentar**: Instituto que visa independência do órgão legislativo em conjunto e de seus membros
- **Garantia Formal**: Regra que obriga a Assembleia Legislativa a observar a finalidade da imunidade formal no momento da análise do pedido de seu levantamento
- **Fumus Persecutionis**: Conceito jurídico que se refere à presença de um risco ou suspeita de perseguição

### Referências legais
- Art. 100 da EC nº 35/01

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre imunidade formal e imunidade pessoal
- Conheça o conceito de fumus persecutiois', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Direitos Humanos", "legal_refs": ["Art. 100 da EC nº 35/01"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T12:43:52.617323+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=147", "doc_key": "aaac46eb9a4306fa16787ece3fbaba51"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4ab7f24a40a95411ddd53b46dea0fae81b66cef4f5ab8a80fd1123e4e809bd17'),
  ('cpiuris2025::b9698fea0f6831b5de6e431ba7e0224b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Imunidade Parlamentar Processual', '## Imunidade Parlamentar Processual

A imunidade parlamentar processual é um direito que protege os membros do parlamento de serem processados por crimes cometidos no exercício de suas funções. Para levantar essa imunidade, é necessário seguir procedimento célere e incluir um teste de proporcionalidade estrito.

### Conceitos
- **Imunidade Parlamentar Processual**: Direito que protege os membros do parlamento de serem processados por crimes cometidos no exercício de suas funções.
- **Procedimento Célere**: Seguir procedimento rápido e claro para garantir o respeito às garantias do devido processo legal.
- **Teste de Proporcionalidade Estrito**: Análise que avalia a acusação contra um parlamentar e o impacto direto no acesso à justiça das pessoas afetadas pelo julgamento.

