- Entenda a importância do procedimento célere e do teste de proporcionalidade estrito para levantar a imunidade parlamentar processual.
- Análise cuidadosa das normas da época é fundamental para determinar se há regulamentação constitucional, legal ou regimental sobre o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direitos Humanos", "legal_refs": ["§110", "§111", "§114", "§115", "§116", "§117", "§118", "§119", "§120", "§121", "§122", "§123", "§124", "§125", "§126", "§127", "§128"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T12:46:00.587217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=148", "doc_key": "b9698fea0f6831b5de6e431ba7e0224b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b87822617cdcb0d5147903a547ae6168629b13e74f35a08c3d825e36c23ea011'),
  ('cpiuris2025::8b4a2a6922aa29584f6c2c2c8141df1c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção às vítimas de violência contra mulheres e investigação discriminatória', '## Proteção às vítimas de violência contra mulheres e investigação discriminatória

As autoridades estatais têm obrigação de investigar possíveis conotações discriminatórias por razão de gênero em atos de violência contra mulheres, com perspectiva de gênero e atenção às vítimas.

### Conceitos
- **Investigação discriminatória**: Investigação que considera a discriminação por razão de gênero
- **Proteção às vítimas**: Ações do Estado para proteger as vítimas de violência
- **Perspectiva de gênero**: Consideração da perspectiva feminina em investigações e processos
- **Dever de atuação com a devida diligência**: Obrigação do Estado de realizar diligências necessárias em casos de violência
- **Unidade de natureza do gênero humano**: A ideia de que o gênero é uma unidade natural e inseparável da dignidade

### Referências legais
- §129 da Lei X
- §130 da Lei X
- §132 da Lei X
- §133 da Lei X
- §134 da Lei X
- §135 da Lei X

### Jurisprudência
