- Pergunte se a investigação discriminatória é obrigatória em casos de violência contra mulheres
- Entenda o conceito de perspectiva de gênero e sua importância nas investigações
- Identifique o dever de atuação com a devida diligência e como ele é violado no caso concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direitos Humanos", "legal_refs": ["§129 da Lei X", "§130 da Lei X", "§132 da Lei X", "§133 da Lei X", "§134 da Lei X", "§135 da Lei X"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre proteção às vítimas de violência contra mulheres"], "confidence": 0.8, "extracted_at": "2026-05-30T12:46:25.566355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=148", "doc_key": "8b4a2a6922aa29584f6c2c2c8141df1c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2129e682c5e0b01ee2875a89e59a12d3ebbbe5278ef3867664616e9bd7fabf2b'),
  ('cpiuris2025::5203719c00ea8e7cd1b07b032eab376a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação e igualdade', '## Discriminação e igualdade

A discriminação e a desigualdade são incompatíveis com as normas do Direito Internacional, segundo o §138. A Corte IDH considera que os Estados devem abster-se de realizar ações que criem discriminação de fato ou de direito.

### Conceitos
- **Discriminação**: Ação ou omissão que trata um grupo com privilégios ou hostilidade, considerando-o inferior.
- **Igualdade**: Princípio de justiça e direito internacional que proíbe a discriminação e promove a igualdade entre todos os indivíduos.
- **Jus cogens**: Princípio do Direito Internacional que considera certas normas como inderrogáveis e superiores às outras fontes de direito.

### Referências legais
- §138 do Direito Internacional
- Art. 24 da CADH
- Pacto de San José da Costa Rica (Art. 1.1)
- Convenção sobre Eliminação de todas as formas de Discriminação contra a Mulher
- Convenção de Belém do Pará

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda o conceito de discriminação e igualdade no Direito Internacional.
- Conheça as normas do Jus cogens e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direitos Humanos", "legal_refs": ["§138 do Direito Internacional", "Art. 24 da CADH", "Pacto de San José da Costa Rica (Art. 1.1)", "Convenção sobre Eliminação de todas as formas de Discriminação contra a Mulher", "Convenção de Belém do Pará"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T12:46:32.527902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=149", "doc_key": "5203719c00ea8e7cd1b07b032eab376a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b43b835f4958fcd8e83a110d255ab4bd5c5820928f00b2224b76bea8da3cdaa1'),
