- **Integridade Pessoal**: Direito fundamental que protege a autonomia e a dignidade da pessoa
- **Violação dos Direitos Humanos**: Infração ao direito humano por parte do Estado ou de outra entidade
- **CADH**: Convenção Americana sobre os Direitos Humanos
- **Artigo 5.1 da CADH**: Direito à integridade pessoal

### Referências legais
- Art. 5.1 da CADH

### Jurisprudência
- RE 123456

