  ('cpiuris2025::08ae57bb6476ad4c4db0f60d24eaadcc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A decisão do TJPA extinguiu o feito sem resolução do mérito, após a Corte IDH destacar que o Estado tem o dever de investigar como uma obrigação de meio e não de resultado.

### Conceitos
- **Direito à verdade**: O direito de acesso à justiça, que inclui o direito das vítimas e seus familiares de conhecer a verdade sobre os fatos e verem punidos os responsáveis por violações de direitos humanos.
- **Dever de investigar**: O dever do Estado de investigar como uma obrigação de meio, e não de resultado, que deve ser assumido pelo Estado para proteger os direitos humanos.
- **Proteção de defensores de direitos humanos**: A responsabilidade do Estado em reforçar a sua devida diligência para proteger a atividade dos defensores de direitos humanos, criando um ambiente de proteção e reconhecimento de seu papel essencial para a democracia e o Estado de Direito.

### Referências legais
- §83 da Convenção Americana sobre os Direitos Humanos
- §85 da Convenção Americana sobre os Direitos Humanos
- §88 da Convenção Americana sobre os Direitos Humanos

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre o direito à verdade e o dever de investigar.
