- Art. 21 da Convenção Americana sobre Direitos Humanos
- Súmula 292 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Responsabilidade Internacional do Estado

### Dicas de prova
- Reconheça as prestações impostas ao Brasil em razão da responsabilização internacional do Estado
