- **Responsabilidades do Ministério Público**: obrigações de agir em prol da justiça e da proteção dos direitos humanos
- **Investigação de Violências**: investigação de crimes que envolvem violência contra indivíduos ou grupos
- **Coordenação do Grupo de Trabalho**: função de liderança e gestão do grupo de especialistas responsável pela elaboração do protocolo

