  ('cpiuris2025::90d7b16a176d99cf6b6ba8e89100f9dd', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O texto destaca a importância da proteção internacional dos direitos humanos, destacando a necessidade de considerar conceitos e padrões específicos para o trabalho de defensoras e defensores de direitos humanos no Brasil.

### Conceitos
- **Pessoa defensora de direitos humanos**: Indivíduo que defende e protege os direitos humanos
- **Devida diligência**: Ação necessária para garantir a precisão e a completeza das investigações
- **Investigação com devida diligência**: Investigação realizada com as melhores práticas e padrões internacionais
- **Prescrição**: Fenômeno jurídico que impede a ação judicial após um período determinado

### Referências legais
- Art. 5º da Constituição Brasileira de 1988

