  ('cpiuris2025::cd73551de1209598caea59cb57e5f8c2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O caso Tavares Pereira destaca a violação dos direitos humanos durante uma manifestação pacífica, com uso de força excessiva por parte da polícia, resultando na morte de um trabalhador rural. A Corte IDH analisou o caso e aplicou as normas internacionais de proteção dos direitos humanos.

### Conceitos
- **Direito à Vida**: O direito fundamental à vida, garantido pela Constituição e pelas convenções internacionais
- **Proteção Internacional dos Direitos Humanos**: A proteção internacional dos direitos humanos é assegurada por convenções e tratados internacionais
- **Uso Excessivo de Força**: O uso excessivo de força por parte das autoridades públicas pode violar os direitos humanos
- **Manifestação Pacífica**: A manifestação pacífica é um direito garantido pela Constituição e pelas convenções internacionais
- **Polícia Militar**: A polícia militar é uma instituição pública responsável por manter a ordem pública
- **Investigação Criminal**: A investigação criminal é um processo que busca identificar e punir os responsáveis por um crime
- **Habeas Corpus**: O habeas corpus é um direito fundamental que permite a liberdade de uma pessoa presa sem julgamento
- **Ação de Indenização**: A ação de indenização é um processo que busca compensar os danos causados a uma pessoa

### Referências legais
- Art. 5º, caput, da Constituição Brasileira
- Convenção Americana sobre Direitos Humanos
- ...

### Jurisprudência
- Tavares Pereira vs. Brasil
- Súmula 333 do STF

### Dicas de prova
- Distinção entre uso excessivo de força e uso legítimo de força
- Análise da manifestação pacífica e do direito à vida
- Importância da investigação criminal e do habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, da Constituição Brasileira", "Convenção Americana sobre Direitos Humanos", "..."], "jurisprudence": ["Tavares Pereira vs. Brasil", "Súmula 333 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T12:56:03.158360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=154", "doc_key": "cd73551de1209598caea59cb57e5f8c2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '15206d7c776aedf839af6276ee903ba6a5b195fc3158c28f1071312bb82e6e3d'),
  ('cpiuris2025::ad9eb15276d4f22e991606228bc04a3d', 'doutrina', 'cp_iuris', 'Direitos Humanos — O dever do Estado em relação à liberdade de pensamento e expressão durante protestos sociais', '## O dever do Estado em relação à liberdade de pensamento e expressão durante protestos sociais

O Estado deve facilitar a liberdade de pensamento e expressão, especialmente para grupos marginalizados. Limitações devem ser legais e necessárias, com parâmetros de proporcionalidade.

### Conceitos
- **liberdade de pensamento**: direito à liberdade de opinião e expressão
- **expressão**: direito à liberdade de expressar ideias, opiniões e pensamentos
- **reunião**: direito à reunião pacífica para discutir questões sociais
- **circulação**: direito à liberdade de circulação e deslocamento
- **necessidade e proporcionalidade**: parâmetros para limitar a liberdade de expressão e reunião

### Referências legais
- Art. 13 da CADH
- Art. 15 da CADH
- Art. 19 da CADH
- Art. 22 da CADH

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da liberdade de pensamento e expressão durante protestos sociais.
- Conheça os parâmetros de necessidade e proporcionalidade para limitar esses direitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Direitos Humanos", "legal_refs": ["Art. 13 da CADH", "Art. 15 da CADH", "Art. 19 da CADH", "Art. 22 da CADH"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T12:57:11.662718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=154", "doc_key": "ad9eb15276d4f22e991606228bc04a3d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '179b56d0b802dd849395669af318cfc5596b0416c0cd3a4e7aa8fa8860337f2f'),
  ('cpiuris2025::871b31e92b18ec524f6e61b15e0c3b7a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Uso excessivo de força por policial e violação dos direitos humanos', '## Uso excessivo de força por policial e violação dos direitos humanos

A Corte IDH condenou o Estado do Paraná por uso excessivo de força contra manifestantes, violando os direitos à integridade física e psíquica, liberdade de manifestação e juiz natural. A investigação militar ignorou questões afetadas pela excepcionalidade da jurisdição militar.

### Conceitos
- **Uso excessivo de força**: aplicação de mais força do que necessário para controlar uma situação
- **Violação dos direitos humanos**: infratio dos direitos fundamentais garantidos pela Constituição e leis internacionais
- **Liberdade de manifestação**: direito à expressão e ao protesto pacífico
- **Juiz natural**: juiz que julga casos em sua esfera jurisdicional, sem a necessidade de intervenção externa
- **Investigação militar**: investigação realizada por uma autoridade militar, em vez de uma autoridade civil
- **Excepcionalidade da jurisdição militar**: exceção à regra geral que permite a aplicação de leis e procedimentos militares em casos específicos

### Referências legais
- Art. 4.1 da CADH
- Art. 5.1 da CADH
- Art. 8.1 da Convenção Americana

### Jurisprudência
- RE 123456
- Tema repetitivo sobre uso excessivo de força e violação dos direitos humanos

### Dicas de prova
- Distinção entre uso excessivo de força e necessidade para controlar uma situação
- Importância da liberdade de manifestação e do juiz natural em casos de violência policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4.1 da CADH", "Art. 5.1 da CADH", "Art. 8.1 da Convenção Americana"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre uso excessivo de força e violação dos direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T12:58:00.301856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=155", "doc_key": "871b31e92b18ec524f6e61b15e0c3b7a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b2358ff3963ed9406865801a8a941b8185b926024976df1b286f6ee50aa63b6a'),
  ('cpiuris2025::61cde01b406ad6b27b823d5fe64259a0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade Internacional do Estado por Violação de Direitos Humanos', '## Responsabilidade Internacional do Estado por Violação de Direitos Humanos

A Corte IDH condenou o Brasil por violação dos direitos humanos de Tavares Pereira e seus familiares, bem como de 69 trabalhadores rurais feridos. A decisão destacou a falta de diligência do Estado em investigar as circunstâncias da morte e das lesões.

### Conceitos
- **Violação de Direitos Humanos**: A violação de direitos humanos é um ato ou omissão do Estado que causa dano a uma pessoa ou grupo de pessoas.
- **Responsabilidade Internacional do Estado**: A responsabilidade internacional do estado se refere à obrigação do Estado de cumprir com os direitos humanos e a responder por violações desses direitos.
- **Investigação Deficientes**: Uma investigação deficiente é uma investigação que não é conduzida de forma adequada ou justa, o que pode levar à falta de identificação dos responsáveis por violações de direitos humanos.
- **Reparações**: As reparações são medidas tomadas pelo Estado para compensar as vítimas de violações de direitos humanos e restaurar a dignidade e o bem-estar delas.

### Referências legais
- Art. 8.1 da Convenção Americana
- Art. 25.1 da Convenção Americana
- Art. 5.1 da CADH

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a responsabilidade internacional do Estado por violações de direitos humanos.
- Entenda o conceito de investigação deficiente e suas consequências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8.1 da Convenção Americana", "Art. 25.1 da Convenção Americana", "Art. 5.1 da CADH"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T12:59:10.888028+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=155", "doc_key": "61cde01b406ad6b27b823d5fe64259a0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7d821a44ce41a1d78df97ba978c93a9a3c19301e007c9b6896f7dcb71f9da3d8'),
  ('cpiuris2025::c8405c8a42b33fda5f397322a34e9add', 'doutrina', 'cp_iuris', 'Direitos Humanos — Derechos humanos e responsabilidade militar', '## Derechos humanos e responsabilidade militar

O texto discute a responsabilidade militar e os direitos humanos, destacando a necessidade de garantir que a Justiça Militar não tenha competência para julgar civis em certas situações.

### Conceitos
- **Responsabilidade Militar**: A responsabilidade de um militar por seus atos, independentemente da sua posição ou função.
- **Direitos Humanos**: Os direitos fundamentais das pessoas, incluindo a vida, a liberdade e a segurança.
- **Justiça Militar**: A justiça que se aplica às forças armadas de um país.
- **Competência Jurisdicional**: A capacidade do juiz ou tribunal de julgar uma causa específica.

### Referências legais
- Art. 209 da Lei nº 7.853/89

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade militar e direitos humanos

### Dicas de prova
- Distinção entre a responsabilidade militar e os direitos humanos.
- Entendimento da competência jurisdicional da Justiça Militar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Direitos Humanos", "legal_refs": ["Art. 209 da Lei nº 7.853/89"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade militar e direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T12:59:41.990482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=156", "doc_key": "c8405c8a42b33fda5f397322a34e9add"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f30d5f342a15dbe1754f2dedda7764b149eb3a1251836f06d48d1f493f543f7b'),
  ('cpiuris2025::0d3f1242dbe7802f692e2c2da4da3446', 'doutrina', 'cp_iuris', 'Direitos Humanos — Uso de armas em situações de violência', '## Uso de armas em situações de violência

Análise do uso de armas em um incidente de ônibus, considerando a presença ou não de armas nas mãos dos ocupantes e a posterior investigação.

### Conceitos
- **Uso de armas em situações de violência**: A utilização de armas em contextos de conflito ou ameaça
- **Investigação policial**: O processo de coleta e análise de evidências para determinar a responsabilidade por um crime
- **Reparação por danos**: A prestação de indenização às vítimas de violações dos direitos humanos

