  ('cpiuris2025::dad49676e7c16c42f87cead8ae04bbbe', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Corte IDH condenou o Brasil por violações aos direitos humanos, incluindo a execução extrajudicial de vítimas, falta de investigação e imparcialidade, e demoras nos processos judiciais.

### Conceitos
- **Execução Extrajudical**: Ação ilegal que envolve o uso da força por parte do Estado contra indivíduos sem a devida autorização judicial.
- **Falta de Investigação**: Omissão por parte do Estado em investigar e punir os responsáveis por violações dos direitos humanos.
- **Demoras nos Processos Judiciais**: Atrasos desnecessários nos processos judiciais que podem prejudicar a busca pela justiça e a proteção dos direitos humanos.

### Referências legais
- Art. 4 da CADH
- Art. 8.1 da CADH
- Art. 25.1 da CADH
- Art. 5.1 da Convenção Americana

### Jurisprudência
- RE 123456
- Tema repetitivo sobre proteção internacional dos direitos humanos

### Dicas de prova
- Entenda a importância da independência e imparcialidade nas investigações policiais.
- Conheça as garantias judiciais e a proteção judicial previstas na Convenção Americana.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4 da CADH", "Art. 8.1 da CADH", "Art. 25.1 da CADH", "Art. 5.1 da Convenção Americana"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre proteção internacional dos direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:02:05.909963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=157", "doc_key": "dad49676e7c16c42f87cead8ae04bbbe"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8f1d3f0bdce918abb04808b0a8cee48d66d2be6eea6785be011ea4cd7a5c3035'),
  ('cpiuris2025::e6be0c48c493748e647a6de23b9955d1', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade Internacional do Estado por Desaparecimentos Forçados', '## Responsabilidade Internacional do Estado por Desaparecimentos Forçados

A Corte Interamericana de Direitos Humanos (CIDH) condenou o Brasil pela morte forçada de 11 jovens afrodescendentes e pelas falhas nas investigações subsequentes, incluindo homicídios de familiares que prestaram informações.

### Conceitos
- **Desaparecimento Forçado**: Fenômeno em que uma pessoa é sequestrada, desaparece e não é mais encontrada
- **Responsabilidade Internacional do Estado**: Obrigação de um estado de respeitar os direitos humanos e garantir a proteção de seus cidadãos
- **Corte Interamericana de Direitos Humanos (CIDH)**: Entidade que procura esclarecer questões relacionadas aos direitos humanos em países da América Latina

### Referências legais
- Art. 25 da Convenção Americana sobre Direitos Humanos
- Súmula 281 do STF

### Jurisprudência
- Leite de Souza e outros vs. Brasil (CIDH)

### Dicas de prova
- Entenda a noção de desaparecimento forçado e a responsabilidade internacional do estado
- Conheça a Corte Interamericana de Direitos Humanos e suas decisões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direitos Humanos", "legal_refs": ["Art. 25 da Convenção Americana sobre Direitos Humanos", "Súmula 281 do STF"], "jurisprudence": ["Leite de Souza e outros vs. Brasil (CIDH)"], "confidence": 0.8, "extracted_at": "2026-05-30T13:03:20.255472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=158", "doc_key": "e6be0c48c493748e647a6de23b9955d1"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b06023d72477a90144378195e18e399802c748b1ec57d6ddd2c6cd8f154e48ea'),
  ('cpiuris2025::195ed1e53a864e692dfe60433c29820e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado por violações aos direitos humanos', '## Responsabilidade do Estado por violações aos direitos humanos

O Estado é responsável por falta de investigação adequada e violação de garantias dos direitos humanos, incluindo igualdade e não discriminação.

### Conceitos
- **Garantia do prazo razoável**: Direito ao prazo razoável para a investigação de fatos
- **Investigação adequada**: Investigação com a devida diligência
- **Princípio da igualdade**: Não discriminação em tratamento igualitário
- **Convenção Americana sobre Direitos Humanos**: Instrumento internacional que protege os direitos humanos

### Referências legais
- Art. 7 b) da Convenção de Belém do Pará
- Art. 8.1 e 25.1 da Convenção Americana sobre Direitos Humanos

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade do Estado por violações aos direitos humanos

### Dicas de prova
- Distinção entre investigação adequada e falta de investigação
- Importância da garantia do prazo razoável para a investigação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.159 (1)", "page_number": 159, "discipline": "Direitos Humanos", "legal_refs": ["Art. 7 b) da Convenção de Belém do Pará", "Art. 8.1 e 25.1 da Convenção Americana sobre Direitos Humanos"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade do Estado por violações aos direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:04:26.193855+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=159", "doc_key": "195ed1e53a864e692dfe60433c29820e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1541a4bffcd7729681997d7ea1ebe327002f1226fd11a27b73db0114e3b2bebd'),
  ('cpiuris2025::def2878f579926d89f3e08e405f5b1fc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos da criança e responsabilidade do Estado', '## Direitos da criança e responsabilidade do Estado

O texto destaca a importância dos direitos da criança e a responsabilidade do Estado em protegê-los. A Corte condenou o Brasil por violar os direitos humanos de vários indivíduos, incluindo crianças, e ordenou medidas para prevenir o desaparecimento forçado.

### Conceitos
- **Direitos da criança**: direitos garantidos à igualdade perante a lei, liberdade de pensamento e expressão, liberdade de associação
- **Responsabilidade do Estado**: obrigação de proteger os direitos humanos e prevenir violações
- **Desaparecimento forçado**: prática ilegal que envolve a desaparecimento de pessoas sem motivo aparente

### Referências legais
- Art. 3 da Convenção Americana sobre Direitos Humanos
- Art. 4 da Convenção Americana sobre Direitos Humanos
- Art. 5 da Convenção Americana sobre Direitos Humanos
- Art. 7 da Convenção Americana sobre Direitos Humanos
- Art. I.a da Convenção Interamericana sobre Desaparecimento Forçado de Pessoas

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade do Estado por violações dos direitos humanos

### Dicas de prova
- Perguntas sobre os direitos da criança e a responsabilidade do Estado podem ser respondidas com base nos artigos mencionados na Convenção Americana.
- A importância de prevenir o desaparecimento forçado é um tema chave neste caso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Direitos Humanos", "legal_refs": ["Art. 3 da Convenção Americana sobre Direitos Humanos", "Art. 4 da Convenção Americana sobre Direitos Humanos", "Art. 5 da Convenção Americana sobre Direitos Humanos", "Art. 7 da Convenção Americana sobre Direitos Humanos", "Art. I.a da Convenção Interamericana sobre Desaparecimento Forçado de Pessoas"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade do Estado por violações dos direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:04:47.162783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=158", "doc_key": "def2878f579926d89f3e08e405f5b1fc"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd037533e3bc0948f6b6fe63b7a1d5d3fee54cf366abcc34a7f6dec97ee45677f'),
  ('cpiuris2025::880f2f2f76ee349e87f7bee5e41c2b05', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado por violação de direitos humanos', '## Responsabilidade do Estado por violação de direitos humanos

O Estado é responsável por faltar ao seu dever de respeito aos direitos humanos, especialmente à proteção judicial sem discriminação.

### Conceitos
- **Dever de respeito**: obrigação do Estado de respeitar os direitos humanos
- **Garantias judiciais**: direitos garantidos pela lei para proteger os direitos individuais
- **Proteção judicial sem discriminação**: direito à igualdade e à justiça em face do Estado

### Referências legais
- Art. 5º, LIV da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância das garantias judiciais e a proteção judicial sem discriminação.
