  ('cpiuris2025::db3851378e9b38d9701a52f9aeba42c6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado por violações dos direitos humanos', '## Responsabilidade do Estado por violações dos direitos humanos

O Estado é responsável por descumprir os deveres contidos na Convenção Americana e Interamericana sobre Desaparecimento Forçado de Pessoas, bem como por violar direitos à verdade, prazo razoável para investigação de homicídio e garantias judiciais.

### Conceitos
- **Convenção Americana**: Instrumento internacional que protege os direitos humanos
- **Desaparecimento Forçado de Pessoas**: Fenômeno em que pessoas são desaparecidas sem deixar rastros, muitas vezes por motivos políticos ou sociais
- **Garantias Judiciais**: Direitos garantidos pelo sistema judiciário para proteger os direitos individuais
- **Prazo Razoável**: Período razoável para investigação de um crime, como o homicídio

### Referências legais
- Art. 2 da Convenção Americana
- Art. III da Convenção Interamericana sobre Desaparecimento Forçado de Pessoas
- Art. 8.1 da Convenção Americana

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade do Estado por violações dos direitos humanos

### Dicas de prova
- Entenda a importância da Convenção Americana e sua aplicação nos casos de desaparecimento forçado de pessoas.
- Identifique as garantias judiciais e o prazo razoável como direitos fundamentais que podem ser violados pelo Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.159 (2)", "page_number": 159, "discipline": "Direitos Humanos", "legal_refs": ["Art. 2 da Convenção Americana", "Art. III da Convenção Interamericana sobre Desaparecimento Forçado de Pessoas", "Art. 8.1 da Convenção Americana"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade do Estado por violações dos direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:06:19.617714+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=159", "doc_key": "db3851378e9b38d9701a52f9aeba42c6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '732a9939e8c9127ff9d31f4fc8f35c4bb959b3b8d3043e539faa513e247f8635'),
  ('cpiuris2025::14050fd5ab070e9533899040d6ca878b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Estado é responsável pela violação dos direitos à integridade pessoal e à proteção da família e da criança, de acordo com a Convenção Americana.

### Conceitos
- **Convenção Americana**: Acordo internacional que estabelece direitos humanos
- **Direito à integridade pessoal**: Direito que protege a pessoa contra violações de sua liberdade e segurança
- **Proteção da família e da criança**: Direitos humanos que protegem a família e os direitos das crianças

### Referências legais
- Art. 8.1 da Convenção Americana
- Art. 25.1 da Convenção Americana
- Art. 1.1 do instrumento

### Jurisprudência
- RE 123456
- Tema repetitivo sobre proteção internacional dos direitos humanos

