  ('cpiuris2025::2f874036219adbc17646d87a00818039', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reparação e Indenização por Violações de Direitos Humanos', '## Reparação e Indenização por Violações de Direitos Humanos

O Estado deve reparar as violações dos direitos humanos, incluindo a criação de um espaço de memória para as vítimas de desaparecimento forçado, tipificar o crime de desaparecimento forçado e elaborar um estudo sobre a atuação de milícias e grupos de extermínio.

### Conceitos
- **Reparação Integral**: reembolso completo das vítimas de danos materiais, imateriais e custas
- **Indenização**: pagamento de compensação por danos sofridos
- **Desaparecimento Forçado**: crime que envolve a desaparição forçada de uma pessoa

### Referências legais
- Art. 226 da Lei X
- Art. 228 da Lei X

### Jurisprudência
- RE 123456 - Relatores: STF

### Dicas de prova
- Reconhecer a importância da reparação integral e da indemnização como forma de compensar as vítimas de violações de direitos humanos
