  ('cpiuris2025::3f251b1ede54f62d2c8fa457b313b3e6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado por violações de direitos humanos', '## Responsabilidade do Estado por violações de direitos humanos

O Estado é responsável por violações de direitos humanos, como o prazo razoável no processo penal e a falta de devida diligência, em decorrência do homicídio de um trabalhador rural.

### Conceitos
- **Prazo Razoável**: Direito garantido ao acusado de ser julgado dentro de um prazo razoável
- **Devida Diligência**: Obrigação do Estado de investigar e processar um caso de forma adequada e imparcial
- **Direito à Verdade**: Direito do acusado de saber a verdade sobre o caso em julgamento

### Referências legais
- Art. 8.1 da Convenção Americana
- Art. 25.1 da Convenção Americana
- Art. 1.1 da Convenção Americana

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre responsabilidade do Estado e responsabilidade individual
- Importância do prazo razoável no processo penal
