  ('cpiuris2025::d55b56210590085f314f8367c278ccba', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade Estatal por Violações de Direitos Humanos', '## Responsabilidade Estatal por Violações de Direitos Humanos

O Estado é responsável pela violação do direito à integridade pessoal e deve oferecer reparação às vítimas, incluindo tratamento médico, psicológico e/ou psiquiátrico, além de realizar publicações e um ato público de reconhecimento de responsabilidade internacional.

### Conceitos
- **Responsabilidade Estatal**: O Estado é responsável pelas violações dos direitos humanos.
- **Reparação**: Ações tomadas pelo Estado para compensar as vítimas de violações dos direitos humanos.
- **Tratamento Médico e Psicológico**: Serviços oferecidos às vítimas para atender às suas necessidades de saúde.
- **Reconhecimento de Responsabilidade Internacional**: Ação do Estado que reconhece sua responsabilidade pelas violações dos direitos humanos.
- **Sistema Regional de Coleta de Dados**: Iniciativa do Estado para coletar e estatizar dados sobre casos de violência contra pessoas trabalhadoras rurais.

### Referências legais
- Art. 5.1 da Convenção Americana
- Parágrafos 72 a 77 da Sentença

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre responsabilidade estatal e reparação.
- Entendimento do termo ''tratamento médico'' em contexto jurídico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.161 (2)", "page_number": 161, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5.1 da Convenção Americana", "Parágrafos 72 a 77 da Sentença"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T13:09:32.620981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=161", "doc_key": "d55b56210590085f314f8367c278ccba"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e90dbb304e22e03e830481af4d69058f41567a0c89c03f408c9a86a0d3f4a974'),
  ('cpiuris2025::1b1e15a0fcc1c71f1fdb6fb5e06e06dd', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado por violações de direitos humanos', '## Responsabilidade do Estado por violações de direitos humanos

O Estado é responsável por violações de direitos humanos de Almir Muniz da Silva, incluindo reconhecimento da personalidade jurídica, vida, integridade pessoal e liberdade pessoal, além de falta de investigação e busca do desaparecido.

### Conceitos
- **Reconhecimento da personalidade jurídica**: Direito à existência como pessoa jurídica
- **Violação dos direitos humanos**: Inadimplemento de obrigações decorrentes de tratados internacionais
- **Desaparecimento forçado de pessoas**: Fenômeno em que uma pessoa é sequestrada, desaparece e não é mais encontrada

