  ('cpiuris2025::4728aa1ee5792f4a6e43d64a5c837a44', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado por violações de direitos humanos', '## Responsabilidade do Estado por violações de direitos humanos

O Estado é responsável pelas violações dos direitos humanos de vítimas de desaparecimento forçado e violação do direito à verdade, além de outros direitos garantidos pela Convenção Americana.

### Conceitos
- **Responsabilidade do Estado**: O Estado é responsável pelas violações dos direitos humanos de vítimas de desaparecimento forçado e violação do direito à verdade.
- **Convenção Americana**: Instrumento internacional que protege os direitos humanos e garantidos pela Constituição Federal.
- **Deveres contidos no artigo 2 da Convenção Americana**: Direitos humanos garantidos pela Convenção Americana, como a vida, a liberdade e a segurança pessoal.
- **Violação do direito à verdade**: O Estado é responsável pela violação do direito à verdade, que é um direito fundamental garantido pela Constituição Federal.
- **Impacto no projeto de vida**: A violação dos direitos humanos pode ter um impacto negativo no projeto de vida das vítimas.

### Referências legais
- Art. 2 da Convenção Americana
- Artigos I.D e III da CIDFP
- Artigo 1.1 da Convenção Americana

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre responsabilidade do Estado e responsabilidade individual.
- Importância de entender a Convenção Americana e seus artigos relevantes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.162 (2)", "page_number": 162, "discipline": "Direitos Humanos", "legal_refs": ["Art. 2 da Convenção Americana", "Artigos I.D e III da CIDFP", "Artigo 1.1 da Convenção Americana"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T13:11:53.946842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=162", "doc_key": "4728aa1ee5792f4a6e43d64a5c837a44"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '22a0d74d8f2e3a294640384eb65675ff645078dd39462f7ee9575f2b5784a3f2'),
  ('cpiuris2025::61a0c89acca65b8340c036e3a7e394b3', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Estado é obrigado a investigar o desaparecimento forçado de Almir Muniz da Silva, oferecer busca por seu paradeiro e fornecer tratamento médico e psicológico às vítimas. Além disso, o Estado deve realizar publicações, reconhecer responsabilidade internacional, adequar seu ordenamento jurídico e criar um protocolo de busca de pessoas desaparecidas.

### Conceitos
- **Desaparecimento forçado**: Fato que envolve a remoção ilegal e sem consentimento de uma pessoa
- **Proteção internacional dos direitos humanos**: Mecanismos e acordos internacionais destinados a proteger os direitos humanos em todo o mundo
- **Responsabilidade internacional**: Obrigação de um Estado de cumprir com seus compromissos e promessas feitas em nível internacional
- **Reconhecimento público**: Ação do Estado para reconhecer suas responsabilidades por um ato ou fato

