  ('cpiuris2025::c34e318344031e28557da0a17216fa33', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reparação por violações dos direitos humanos', '## Reparação por violações dos direitos humanos

O Estado deve reparar as vítimas com atendimento psicológico, publicações e reconhecimento de responsabilidade internacional, além de adotar medidas para combater a discriminação racial.

### Conceitos
- **Reparação**: compensação por violações dos direitos humanos
- **Discriminação racial**: tratamento desigual de indivíduos com base em sua raça ou etnia
- **Responsabilidade internacional**: obrigação do Estado de responder por suas ações no âmbito internacional
- **Atendimento psicológico**: ajuda profissional para vítimas de violações dos direitos humanos
- **Investigação interseccional**: análise que considera múltiplas formas de discriminação e opressão

### Referências legais
- Art. 1.1 da Convenção Americana
- Art. 26 da Convenção Americana

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Reconheça a importância da reparação por violações dos direitos humanos
- Entenda o conceito de discriminação racial e sua relação com os direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.164 (1)", "page_number": 164, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1.1 da Convenção Americana", "Art. 26 da Convenção Americana"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T13:14:08.661011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=164", "doc_key": "c34e318344031e28557da0a17216fa33"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4cb3fc9efe5c5fb5665fb94969be66f0f78927971669c9105f86891b8cfba140'),
  ('cpiuris2025::020566944eaf88e31272660c2f655549', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação racial no processo de contratação', '## Discriminação racial no processo de contratação

A Corte declarou que o Estado é responsável pela falta da devida diligência na investigação da violação do direito à igualdade e não discriminação em razão de raça, causando a reprodução da discriminação estrutural e racismo institucional.

### Conceitos
- **Discriminação racial**: Ação discriminatória com base na cor ou raça
- **Falta de devida diligência**: Obrigação do Estado de investigar e agir em determinadas situações
- **Violação dos direitos humanos**: Infrção aos direitos garantidos por leis internacionais, como a Convenção Americana sobre Direitos Humanos
- **Racismo institucional**: Poder e prática de um grupo dominante em relação a outro grupo subordinado
- **Acesso à justiça**: Direito do cidadão de ter acesso a uma justiça efetiva e imparcial

### Referências legais
- Art. 8.1 da Convenção Americana sobre Direitos Humanos
- Art. 24 da Constituição Brasileira

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Reconhecer a discriminação racial como uma violação dos direitos humanos
