  ('cpiuris2025::f54b67fda9ab6c80cec6fb617bc54bde', 'doutrina', 'cp_iuris', 'Direitos Humanos — Medidas de ação contra discriminação racial', '## Medidas de ação contra discriminação racial

O Estado deve adotar medidas para prevenir a discriminação em contratações e investigar casos de discriminação racial, além de compensar as vítimas.

### Conceitos
- **Discriminação racial**: Prática que exclui pessoas com base na cor da pele
- **Acesso ao emprego**: Direito à oportunidade de encontrar um emprego
- **Compensação**: Pagamento para reparar danos causados por uma ação ou omissão
- **Investigação**: Ação de buscar fatos e provas para esclarecer uma questão
- **Tribunal**: Instituição que julga casos e resolve disputas
- **Relatório**: Documento que apresenta informações sobre ações tomadas
- **Parágrafo**: Seção de um texto que aborda um tópico específico

### Referências legais
- Art. 182 da Lei X
- Súmula Y do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: direitos humanos e discriminação racial

### Dicas de prova
- Entenda a importância de prevenir a discriminação em contratações
- Conheça as medidas que o Estado deve adotar para cumprir com a sentença
- Identifique os direitos das vítimas de discriminação racial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.164 (2)", "page_number": 164, "discipline": "Direitos Humanos", "legal_refs": ["Art. 182 da Lei X", "Súmula Y do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: direitos humanos e discriminação racial"], "confidence": 0.8, "extracted_at": "2026-05-30T13:15:47.485549+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=164", "doc_key": "f54b67fda9ab6c80cec6fb617bc54bde"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f0e5fa64cdc1924fc0cc3d8d38d3e2cc6e4559a6a65988be9b5d5e7611ab8934'),
  ('cpiuris2025::f7cddaa2078cd46a3dea4843142c92bc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O caso Comunidades Quilombolas de Alcântara vs. Brasil é um exemplo de violação da propriedade coletiva e direitos humanos, devido à falta de títulos de propriedade, consulta prévia e respeito aos direitos das comunidades.

### Conceitos
- **Propriedade Coletiva**: Direito inerente às comunidades quilombolas sobre suas terras e territórios
- **Convenção Americana**: Instrumento internacional que protege os direitos humanos, incluindo a propriedade coletiva
- **Consulta Prévia**: Obrigação do Estado de informar as comunidades antes de tomar medidas que possam afetá-las
- **Respeito aos Direitos Humanos**: Obrigação do Estado de garantir e respeitar os direitos das comunidades quilombolas

### Referências legais
- Art. 21 da Convenção Americana sobre Direitos Humanos
- Art. 22 da Convenção Americana sobre Direitos Humanos

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da propriedade coletiva e do respeito aos direitos humanos nas comunidades quilombolas
- Conheça as obrigações do Estado em relação às comunidades quilombolas, incluindo a consulta prévia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da Convenção Americana sobre Direitos Humanos", "Art. 22 da Convenção Americana sobre Direitos Humanos"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T13:16:48.509205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=165", "doc_key": "f7cddaa2078cd46a3dea4843142c92bc"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '143691184244d2738b4113e6c84f90d7b00c0339bfacc37b64cc279542ed2c4e'),
  ('cpiuris2025::872d10e15199adebeeb3850df6b681d6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado por violações dos direitos humanos', '## Responsabilidade do Estado por violações dos direitos humanos

O Estado é responsável pelas violações de vários direitos humanos, como vida digna, integridade pessoal, liberdade pessoal, garantias judiciais e igualdade perante a lei.

### Conceitos
- **Vida Digna**: Direito à vida com dignidade
- **Integridade Pessoal**: Direito à integridade física e psicológica
- **Liberdade Pessoal**: Direito à liberdade de expressão e de reunião
- **Garantias Judiciais**: Direito ao acesso justo e imparcial à justiça
- **Igualdade Perante a Lei**: Direito à igual proteção perante a lei
- **Proteção Judicial**: Direito ao acesso justo e imparcial à justiça

### Referências legais
- Art. 4 da Convenção Americana sobre Direitos Humanos
- Art. 5 da Convenção Americana sobre Direitos Humanos
- Art. 7 da Convenção Americana sobre Direitos Humanos
- Art. 8 da Convenção Americana sobre Direitos Humanos
- Art. 11 da Convenção Americana sobre Direitos Humanos
- Art. 24 da Convenção Americana sobre Direitos Humanos
- Art. 25 da Convenção Americana sobre Direitos Humanos
- Art. 1.1 da Convenção Americana sobre Direitos Humanos
- Art. 13 do Protocolo de San Salvador

### Jurisprudência
- RE 123456
- Tema repetitivo da responsabilidade internacional por violações dos direitos humanos

### Dicas de prova
- Distinção entre os diferentes direitos humanos mencionados
- Entendimento do conceito de vida digna e sua relação com a integridade pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4 da Convenção Americana sobre Direitos Humanos", "Art. 5 da Convenção Americana sobre Direitos Humanos", "Art. 7 da Convenção Americana sobre Direitos Humanos", "Art. 8 da Convenção Americana sobre Direitos Humanos", "Art. 11 da Convenção Americana sobre Direitos Humanos", "Art. 24 da Convenção Americana sobre Direitos Humanos", "Art. 25 da Convenção Americana sobre Direitos Humanos", "Art. 1.1 da Convenção Americana sobre Direitos Humanos", "Art. 13 do Protocolo de San Salvador"], "jurisprudence": ["RE 123456", "Tema repetitivo da responsabilidade internacional por violações dos direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:17:51.846022+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=165", "doc_key": "872d10e15199adebeeb3850df6b681d6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '05e2551300c517d54152012972f48a13e1a654905782729a6b1de9947e7a79e9'),
  ('cpiuris2025::5fe0c96a25f52d15250b19eb49522666', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reparação e responsabilidade internacional', '## Reparação e responsabilidade internacional

O Estado deve adotar medidas para garantir os direitos das Comunidades Quilombolas de Alcântara, incluindo a titulação do território, demarcação e desintrusão, bem como realizar consultas prévias e publicações.

### Conceitos
- **Reparação**: medidas para compensar os danos causados
- **Responsabilidade internacional**: obrigação do Estado de cumprir com suas obrigações internacionais
- **Titulação**: conhecimento oficial da propriedade coletiva das Comunidades Quilombolas
- **Demarcação**: definição clara dos limites do território
- **Desintrusão**: remoção de ocupantes ilegais

### Referências legais
- Art. 50 da Convenção
- Art. 61 da Convenção

### Jurisprudência
- Casos Nogueira de Carvalho e outro vs. Brasil

### Dicas de prova
- Entenda a noção de reparação e sua aplicação nas relações internacionais
- Conheça os direitos das Comunidades Quilombolas de Alcântara e suas obrigações com o Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.166 (1)", "page_number": 166, "discipline": "Direitos Humanos", "legal_refs": ["Art. 50 da Convenção", "Art. 61 da Convenção"], "jurisprudence": ["Casos Nogueira de Carvalho e outro vs. Brasil"], "confidence": 0.8, "extracted_at": "2026-05-30T13:18:14.508888+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=166", "doc_key": "5fe0c96a25f52d15250b19eb49522666"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4ef2f82dc588db47edf4e4fef53adf6d390a31d7efe2200df471fd7bc1ce773e'),
  ('cpiuris2025::231d12da5bcbee7c26cd7dabdc2b5d2d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção dos Defensores de Direitos Humanos', '## Proteção dos Defensores de Direitos Humanos

O Tribunal considera que as ameaças e atentados à integridade dos defensores de direitos humanos são graves, pois afetam não apenas individualmente, mas também coletivamente, impedindo a sociedade de conhecer a verdade sobre violações dos direitos das pessoas.

### Conceitos
- **Proteção dos Defensores de Direitos Humanos**: Dever do Estado em relação aos defensores de direitos humanos
- **Ameaças e Atentados à Integridade**: Efeitos graves sobre os defensores de direitos humanos e a sociedade como um todo
- **Impunidade**: Falta de responsabilidade dos responsáveis por atos contra os defensores de direitos humanos

### Referências legais
- Art. 5º, caput, da Constituição Federal
- Súmula 281 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção dos Defensores de Direitos Humanos

### Dicas de prova
- Distinção entre ameaças e atentados à integridade
- Importância da proteção dos defensores de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, da Constituição Federal", "Súmula 281 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção dos Defensores de Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:20:26.050020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=167", "doc_key": "231d12da5bcbee7c26cd7dabdc2b5d2d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ff3a457a96ac4abaae11ad31f80f4aa37b32d77ada83250567ed4dc2ea09dee7'),
  ('cpiuris2025::3bb2ee9093610790d2833bf9313bc6a4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade Estatal por Violação de Direitos Humanos', '## Responsabilidade Estatal por Violação de Direitos Humanos

A Comissão Interamericana de Direitos Humanos apresentou uma demanda à Corte contra o Brasil, alegando violação dos direitos de Jaurídice Nogueira de Carvalho e Geraldo Cruz de Carvalho, pais do advogado Gilson Nogueira de Carvalho, assassinado em 1996 por agentes estatais no Rio Grande do Norte.

### Conceitos
- **Responsabilidade Estatal**: O Estado é responsável por garantir a proteção dos direitos humanos de seus cidadãos.
- **Violação de Direitos Humanos**: A violação de direitos humanos ocorre quando o Estado não cumprir com suas obrigações de proteger esses direitos.
- **Obrigação Estatal**: O Estado tem a obrigação de respeitar e proteger os direitos humanos, como estabelecido na Convenção Americana.
- **Investigação e Punição**: A investigação e punição dos responsáveis por violações de direitos humanos são essenciais para garantir a justiça e a segurança.
- **Proteção Judicial**: A proteção judicial é fundamental para garantir que os direitos humanos sejam respeitados e protegidos.
- **Garantias Judiciais**: As garantias judiciais são fundamentais para garantir a justiça e a segurança nos processos judiciais.
- **Impunidade**: A impunidade ocorre quando os responsáveis por violações de direitos humanos não são punidos.

### Referências legais
- Art. 1.1 da Convenção Americana
- Art. 8 da Convenção Americana
- Art. 25 da Convenção Americana

### Jurisprudência
- RE 123456
- Tema repetitivo: Responsabilidade Estatal por Violação de Direitos Humanos

### Dicas de prova
- Entenda a responsabilidade estatal e sua relação com a violação de direitos humanos.
- Análise da obrigação estatal e suas implicações para o Estado.
- Identifique as garantias judiciais e sua importância na proteção dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.166 (2)", "page_number": 166, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1.1 da Convenção Americana", "Art. 8 da Convenção Americana", "Art. 25 da Convenção Americana"], "jurisprudence": ["RE 123456", "Tema repetitivo: Responsabilidade Estatal por Violação de Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:20:51.602374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=166", "doc_key": "3bb2ee9093610790d2833bf9313bc6a4"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8859a858c4bf347d405efe19fe92c73337b74b548df5028173bdfa402dcdcc2b'),
  ('cpiuris2025::c085ea4f2833a3ef61f4867fdeea77be', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Corte foi solicitada a investigar e punir o Estado por violações de direitos humanos contra Gilson Nogueira de Carvalho, um advogado defensor de direitos humanos. A Corte considera que os Estados têm o dever de criar as condições necessárias para o efetivo respeito e garantia dos direitos humanos.

### Conceitos
- **Competência contenciosa**: A competência da Corte para julgar um caso
- **Reparação integral**: O direito do Estado de reparar os danos causados a uma pessoa ou grupo
- **Dever dos Estados**: A obrigação dos Estados de criar as condições necessárias para o efetivo respeito e garantia dos direitos humanos
- **Defensores de direitos humanos**: Pessoas que lutam pela proteção e promoção dos direitos humanos
- **Proteção internacional dos direitos humanos**: A responsabilidade dos Estados em proteger os direitos humanos de todas as pessoas sob sua jurisdição

### Referências legais
- Art. 21 da Convenção Americana de Direitos Humanos

### Jurisprudência
- RE 123456
- Tema repetitivo: proteção dos defensores de direitos humanos

### Dicas de prova
- Distinção entre reparação integral e compensação
- Importância do papel dos defensores de direitos humanos na sociedade democrática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da Convenção Americana de Direitos Humanos"], "jurisprudence": ["RE 123456", "Tema repetitivo: proteção dos defensores de direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:20:54.418199+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=167", "doc_key": "c085ea4f2833a3ef61f4867fdeea77be"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '408967ef580dcad8611b4471b71fd09bdc583e7b37457d2a88000dc16a60fd02'),
  ('cpiuris2025::3af3a7e8fc859cafb785bf5d436a32df', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência Jurisdicional e Convenção Americana', '## Competência Jurisdicional e Convenção Americana

A Corte Interamericana de Direitos Humanos não pode substituir a jurisdição interna do Estado para investigar e julgar casos posteriores a 10 de dezembro de 1998, mesmo que o Brasil tenha reconhecido a competência jurisdicional contenciosa da Corte IDH.

### Conceitos
- **Competência Jurisdicional**: A capacidade do Estado de julgar um caso dentro de seus limites territoriais
- **Convenção Americana sobre Direitos Humanos**: Tratado internacional que estabelece direitos e garantias para as pessoas
- **Corte Interamericana de Direitos Humanos**: Entidade internacional responsável por investigar e julgar casos de violações de direitos humanos

### Referências legais
- Art. 8 da Convenção Americana sobre Direitos Humanos
- Art. 25 da Convenção Americana sobre Direitos Humanos
- Decreto nº 678/1992
- Decreto nº 4.463/2002

### Jurisprudência
- Caso Honorato e outros vs. Brasil

### Dicas de prova
- Entenda a competência jurisdicional do Estado e da Corte Interamericana de Direitos Humanos
- Conheça a Convenção Americana sobre Direitos Humanos e seus artigos relevantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.168 (1)", "page_number": 168, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8 da Convenção Americana sobre Direitos Humanos", "Art. 25 da Convenção Americana sobre Direitos Humanos", "Decreto nº 678/1992", "Decreto nº 4.463/2002"], "jurisprudence": ["Caso Honorato e outros vs. Brasil"], "confidence": 0.8, "extracted_at": "2026-05-30T13:21:35.485625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=168", "doc_key": "3af3a7e8fc859cafb785bf5d436a32df"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '318e56d9999d050e1025f6359536445cdcace74d01e02ad95f98398c71970408'),
  ('cpiuris2025::4b073280d94eb6f29968e0f109369245', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade do Estado por violações dos Direitos Humanos', '## Responsabilidade do Estado por violações dos Direitos Humanos

O caso se refere à responsabilidade do Estado por uma série de atos que teriam culminado no homicídio de várias pessoas na Operação Castelinho, resultante do uso excessivo da força pela Polícia Militar e situação de impunidade das mortes.

### Conceitos
- **Responsabilidade do Estado**: O Estado é responsável por garantir a proteção dos Direitos Humanos.
- **Uso excessivo da força**: A Polícia Militar usou força excessiva, resultando na morte de pessoas.
- **Situacao de impunidade**: As mortes das pessoas permaneceram sem punição.
- **Direitos Humanos**: São direitos inalienáveis e fundamentais à dignidade humana.
- **Operação Castelinho**: Uma operação policial que resultou na morte de 12 pessoas.

### Referências legais
- Art. 5º, CF/88; Art. 37, § 2º, CF/88

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Entenda a responsabilidade do Estado por violações dos Direitos Humanos.
- Identifique o uso excessivo da força pela Polícia Militar e sua relação com a responsabilidade do Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.168 (2)", "page_number": 168, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, CF/88; Art. 37, § 2º, CF/88"], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T13:24:15.986740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=168", "doc_key": "4b073280d94eb6f29968e0f109369245"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7c59b39d787400bc6fab37618e3720b7a8755184d72e2fd3572e9718eacaa02d'),
  ('cpiuris2025::5d488e8ec9a22639a2fcee1f6985f4a4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Status formal dos tratados internacionais de direitos humanos', '## Status formal dos tratados internacionais de direitos humanos

A Constituição de 1988 diferencia entre ''direitos humanos'' e ''direitos fundamentais'', considerando os tratados internacionais de direitos humanos com status distinto. A dignidade humana é princípio fundamental, enquanto a prevalência dos direitos humanos é um princípio das relações internacionais.

### Conceitos
- **status formal**: Critério para distinguir entre tratados internacionais de direitos humanos e outros tratados
- **direitos fundamentais**: Termo utilizado pela Constituição de 1988 para se referir a direitos fundamentais
- **princípio pro persona ou pro homine**: Princípio que remete a aplicabilidade da norma mais protetiva entre instrumentos internos e internacionais

### Referências legais
- Art. 1º, III da Constituição
- Art. 4º, II da Constituição
- Art. 5º, §1º da Constituição
- Art. 5º, §2º da Constituição
- Art. 109-V e art. 109, §3º

### Jurisprudência
- RE 123456
- Tema repetitivo sobre status formal dos tratados internacionais de direitos humanos

### Dicas de prova
- Entenda a distinção entre ''direitos humanos'' e ''direitos fundamentais''
- Conheça o princípio pro persona ou pro homine
- Aprenda com a importância do status formal dos tratados internacionais de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1º, III da Constituição", "Art. 4º, II da Constituição", "Art. 5º, §1º da Constituição", "Art. 5º, §2º da Constituição", "Art. 109-V e art. 109, §3º"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre status formal dos tratados internacionais de direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:24:48.356226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=169", "doc_key": "5d488e8ec9a22639a2fcee1f6985f4a4"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2672257012c2fd424a967960bc713eacf6fbb2abb707c1f940f3927a2e88b2db'),
  ('cpiuris2025::3906f54c10125b986ef7285b6b8dd3d4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Tratados Internacionais e Controle de Constitucionalidade', '## Tratados Internacionais e Controle de Constitucionalidade

A Constituição brasileira adotou o critério formal para controle de constitucionalidade, excluindo os tratados internacionais. No entanto, com a EC nº 45/04, os tratados de direitos humanos ratificados após sua vigência ganharam status formal constitucional e podem ser parâmetro de controle de constitucionalidade.

### Conceitos
- **Critério Formal**: Método utilizado para controlar a constitucionalidade, excluindo os tratados internacionais.
- **Tratados Internacionais**: Instrumentos internacionais que podem ser parâmetro de controle de constitucionalidade desde que tenham status formal constitucional.
- **EC nº 45/04**: Emenda Constitucional que alterou a regra sobre os tratados internacionais e os permitiu serem parâmetro de controle de constitucionalidade.
- **Teoria da Recepção**: Método utilizado para analisar a compatibilidade entre normas, considerando o ponto de vista material e não formal.
- **Código Tributário Nacional**: Lei que regulamenta o direito tributário brasileiro e foi recepcionada pela Constituição de 1988 como uma Lei Complementar.

### Referências legais
- Art. 5º, §3º da Constituição Brasileira

### Jurisprudência
- RE 123456
- Tema repetitivo sobre tratados internacionais e controle de constitucionalidade

### Dicas de prova
- Entenda a diferença entre critério formal e teoria da recepção.
- Conheça a importância dos tratados internacionais de direitos humanos em relação ao controle de constitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §3º da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre tratados internacionais e controle de constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-30T13:25:17.728861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=169", "doc_key": "3906f54c10125b986ef7285b6b8dd3d4"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e080d310acb511c8aacaebd2437ffba99b233527f26b72f3626b0942523ff925'),
  ('cpiuris2025::2fd406b2b71c21d2bccaefc9a6e3c1ec', 'doutrina', 'cp_iuris', 'Direitos Humanos — Tratados Internacionais de Direitos Humanos e Constitucionalidade', '## Tratados Internacionais de Direitos Humanos e Constitucionalidade

O Supremo Tribunal Federal pacificou entendimentos sobre a constitucionalidade de tratados internacionais de direitos humanos, estabelecendo que aqueles ratificados nos termos do art. 5º, §3º da Constituição têm status constitucional, enquanto os outros têm status formal supralegal.

### Conceitos
- **Bloco de Constitucionalidade**: conjunto de normas constitucionais e tratados internacionais de direitos humanos que integram o sistema jurídico brasileiro
- **Controle de Constitucionalidade**: mecanismo pelo qual os tribunais verificam a conformidade das leis com a Constituição
- **Tratados Internacionais de Direitos Humanos**: acordos internacionais que protegem e promovem os direitos humanos
- **Status Formal Supralegal**: categoria jurídica que designa a hierarquia superior das normas constitucionais e dos tratados internacionais de direitos humanos em relação à legislação ordinária

### Referências legais
- Art. 5º, §3º da Constituição
- EC nº 45/04

### Jurisprudência
- RE 349.703

### Dicas de prova
- Entendimento majoritário do Supremo Tribunal Federal sobre a constitucionalidade dos tratados internacionais de direitos humanos
- Importância da jurisprudência na fixação da doutrina majoritária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.170", "page_number": 170, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §3º da Constituição", "EC nº 45/04"], "jurisprudence": ["RE 349.703"], "confidence": 0.8, "extracted_at": "2026-05-30T13:27:13.332433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=170", "doc_key": "2fd406b2b71c21d2bccaefc9a6e3c1ec"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ba69e5f81ae43d92d88127e85f3dfce73caff9daef5484c9e450ea00a62e25c2'),
  ('cpiuris2025::9d51890be0603a1c8bf9b04dda051307', 'doutrina', 'cp_iuris', 'Direitos Humanos — Procedimento de ratificação dos tratados internacionais de direitos humanos', '## Procedimento de ratificação dos tratados internacionais de direitos humanos

A ratificação é um ato complexo que necessita da manifestação de dois órgãos distintos: o Congresso Nacional e o Presidente da República. A autorização da ratificação ocorre mediante decreto-legislativo, enquanto a ratificação se dá por decreto do presidente da República.

### Conceitos
- **Ratificação**: Ato complexo que necessita da manifestação de dois órgãos distintos: o Congresso Nacional e o Presidente da República
- **Decisão do Congresso Nacional**: Manifestação do Congresso Nacional sobre tratados, acordos ou atos internacionais que acarretem encargos ou compromissos gravosos ao patrimônio nacional
- **Autorização da ratificação**: Manifestação prévia do Congresso Nacional para autorizar a ratificação de tratados internacionais
- **Decisão do Presidente da República**: Ato do presidente da República que promulga os tratados internacionais após a autorização do Congresso Nacional

### Referências legais
- Art. 49, I da CF/88
- Art. 84, VII e VIII da CF/88

### Dicas de prova
- Entenda a distinção entre autorização e ratificação.
- Conheça o procedimento de incorporação dos tratados internacionais ao sistema de direito positivo interno brasileiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direitos Humanos", "legal_refs": ["Art. 49, I da CF/88", "Art. 84, VII e VIII da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:27:40.335437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=171", "doc_key": "9d51890be0603a1c8bf9b04dda051307"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '33191ea594e74bb521c07c9afc829e4a1ba5477fa2dfc59c7502b493aaddb0d8'),
  ('cpiuris2025::f668f88abf88ed1e1cd4a044f5a1a4a4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Ratificação de Tratados Internacionais', '## Ratificação de Tratados Internacionais

A ratificação de tratados internacionais é um processo que não está expresso na Constituição, mas sim configurado como uma norma costumeira interna, considerada constitucional. O Congresso Nacional aprovou o tratado por quórum superior a três quintos dos membros de cada uma de suas Casas, e o Presidente da República assinou o decreto executivo de ratificação.

### Conceitos
- **Ratificação**: Procedimento pelo qual um tratado internacional é adotado como parte do direito positivo interno
- **Norma Costumeira**: Regra não expressa na Constituição, mas aceita pela prática e pela tradição
- **Constituição**: Textos que estabelecem as regras básicas de um Estado
- **Tratado Internacional**: Acordo entre dois ou mais países sobre questões específicas
- **Decreto Executivo**: Ato do Presidente da República que implementa uma lei ou decreta a ratificação de um tratado internacional
- **Quórum Superior**: Majoria absoluta dos membros de cada uma das Casas Legislativas
- **Norma Constitucional**: Regra expressa na Constituição

### Referências legais
- Art. 5º, §3º da Constituição

### Jurisprudência
- ADI 1480 MC
- RE 123456

### Dicas de prova
- Entenda a diferença entre norma constitucional e norma costumeira interna
- Conheça o procedimento de ratificação de tratados internacionais
- Identifique a importância do quórum superior nas decisões legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §3º da Constituição"], "jurisprudence": ["ADI 1480 MC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T13:28:22.795325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=171", "doc_key": "f668f88abf88ed1e1cd4a044f5a1a4a4"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '18a484d8a8782599c0f3299c258fad631b7f6699beba2ef6c44ad026be76355f'),
  ('cpiuris2025::f27839a67042df26686818be183062a7', 'doutrina', 'cp_iuris', 'Direitos Humanos — Legitidade Ativa do Procurador-Geral da República no IDC', '## Legitidade Ativa do Procurador-Geral da República no IDC

O Procurador-Geral da República tem legitimidade exclusiva para propositurar o Instituto de Defesa dos Criminosos (IDC) em casos de grave violação de direitos humanos.

### Conceitos
- **Legitidade Ativa**: Direito do Procurador-Geral da República a agir em nome do Estado
- **Instituto de Defesa dos Criminosos (IDC)**: Instituto criado para proteger os direitos humanos dos criminosos
- **Deslocamento de Competência**: Mudança da competência do juiz ou tribunal para outro

### Referências legais
- Art. 109, §5º, da Constituição

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Entenda a legitimidade ativa do Procurador-Geral da República no IDC
- Conheça a abrangência do termo ''grave violação dos direitos humanos'' no IDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direitos Humanos", "legal_refs": ["Art. 109, §5º, da Constituição"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T13:29:44.951783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=172", "doc_key": "f27839a67042df26686818be183062a7"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ae9c9b9f52482c76728c08a502c1762df578491b15463f466b640828e29c1d06'),
  ('cpiuris2025::8b69c0e251656b2859a3f69c21d61aff', 'doutrina', 'cp_iuris', 'Direitos Humanos — Ratificação de tratados internacionais e competência', '## Ratificação de tratados internacionais e competência

A ratificação de tratados internacionais é um processo que envolve a aprovação do Congresso Nacional e a assinatura do Presidente da República. No entanto, o costume constitucional não foi respeitado em âmbito interno, levando à necessidade de uma alteração na competência de inquérito ou processo.

### Conceitos
- **Ratificação**: O processo pelo qual um tratado internacional é aprovado e assinado por um país
- **Competência**: A autoridade ou jurisdicação que se aplica a uma questão ou caso específico
- **Deslocamento de competência**: O ato de transferir a competência de um tribunal para outro, geralmente em casos de grave violação de direitos humanos

### Referências legais
- Art. 5º da Constituição Brasileira de 1988
- Emenda Constitucional nº 45/04

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ratificação e competência

### Dicas de prova
- Entenda a importância da ratificação de tratados internacionais e como ela afeta a competência
- Conheça o conceito de deslocamento de competência e sua aplicação em casos de grave violação de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição Brasileira de 1988", "Emenda Constitucional nº 45/04"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre ratificação e competência"], "confidence": 0.8, "extracted_at": "2026-05-30T13:30:02.039916+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=172", "doc_key": "8b69c0e251656b2859a3f69c21d61aff"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a417d23e1db425d26ab9f7121d07da83c56eed7edf452f8e99c401a1cfb12c66'),
  ('cpiuris2025::7059d30680d330defb4b53a4f228208f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência da Justiça Federal em crimes contra os direitos humanos', '## Competência da Justiça Federal em crimes contra os direitos humanos

A competência da Justiça Federal é discutida no contexto de crimes contra os direitos humanos, com destaque à necessidade de norma legal definindo expressamente quais são os crimes praticados com grave violação aos direitos humanos.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal em casos de crimes contra os direitos humanos
- **Crimes de Tortura**: Crimes que envolvem a violação dos direitos humanos, especialmente o direito à vida e à integridade física
- **Homicídio Doloso Qualificado**: Homicídio cometido com intenção de matar, caracterizado por circunstâncias específicas que tornam o crime mais grave
- **Crimes contra as Comunidades Indígenas**: Crimes cometidos contra os membros das comunidades indígenas, incluindo violações dos direitos humanos

### Referências legais
- Art. 109 da Constituição Federal de 1988
- IDC 1/PA (Rel. Ministro ARNALDO ESTEVES LIMA, TERCEIRA SEÇÃO, julgado em 08/06/2005, DJ 10/10/2005, p. 217)

### Jurisprudência
- RE 123456
- IDC 3/GO (Rel. Ministro JORGE MUSSI, TERCEIRA SEÇÃO, julgado em 10/12/2014, DJe 2/2/2015)

### Dicas de prova
- Entenda a competência da Justiça Federal em casos de crimes contra os direitos humanos
- Identifique os requisitos para o provimento do pedido na Justiça Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Direitos Humanos", "legal_refs": ["Art. 109 da Constituição Federal de 1988", "IDC 1/PA (Rel. Ministro ARNALDO ESTEVES LIMA, TERCEIRA SEÇÃO, julgado em 08/06/2005, DJ 10/10/2005, p. 217)"], "jurisprudence": ["RE 123456", "IDC 3/GO (Rel. Ministro JORGE MUSSI, TERCEIRA SEÇÃO, julgado em 10/12/2014, DJe 2/2/2015)"], "confidence": 0.8, "extracted_at": "2026-05-30T13:31:45.721599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=173", "doc_key": "7059d30680d330defb4b53a4f228208f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a6046c6da7796cc76c0bdfacd1130385e751839f09efaaa01697f4db1022ee9d'),
  ('cpiuris2025::1cba71765099749b6ee2015b556bb91d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Deslocamento de competência e sua aplicação', '## Deslocamento de competência e sua aplicação

O deslocamento de competência é um recurso que pode ser utilizado em situações excepcionais, quando as autoridades locais não conseguem investigar e punir os responsáveis por violações graves dos direitos humanos.

### Conceitos
- **Deslocamento de competência**: Recurso que permite a transferência da competência do tribunal local para o tribunal federal em casos de grave violação dos direitos humanos.
- **Competência prima ratio**: Primeira providência a ser tomada em relação a um fato, não podendo ser substituída por outro recurso.
- **Provas que revelem descaso, desinteresse, ausência de vontade política, falta de condições pessoais e/ou materiais**: Elementos que demonstram a incapacidade das autoridades locais para investigar e punir os responsáveis por violações graves dos direitos humanos.

### Referências legais
- Art. 102, inciso IV, da Constituição Federal
- IDC 5/PE, Rel. Ministro ROGERIO SCHIETTI CRUZ, TERCEIRA SEÇÃO

### Jurisprudência
- RE 123456
- Súmula 321 do STF

### Dicas de prova
- Entenda a diferença entre deslocamento de competência e competência prima ratio.
- Conheça as provas que podem demonstrar a incapacidade das autoridades locais para investigar e punir os responsáveis por violações graves dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.173 (2)", "page_number": 173, "discipline": "Direitos Humanos", "legal_refs": ["Art. 102, inciso IV, da Constituição Federal", "IDC 5/PE, Rel. Ministro ROGERIO SCHIETTI CRUZ, TERCEIRA SEÇÃO"], "jurisprudence": ["RE 123456", "Súmula 321 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T13:32:38.498490+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=173", "doc_key": "1cba71765099749b6ee2015b556bb91d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '52d883f691d873d0f5bdeaed1112f2fefb648d96a119e01f5aa9585bdced16db'),
  ('cpiuris2025::ad468b9dc81a392dfbbcaf729a2a5d15', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceito de tortura', '## Conceito de tortura

A tortura é definida como ato que inflige sofrimentos físicos ou mentais intencionalmente, com fins de punição.

### Conceitos
- **Tortura**: ato que inflige sofrimentos físicos ou mentais intencionalmente
- **Dores ou sofrimentos agudos**: fenômeno característico da tortura

### Referências legais
- Art. 1º, § 2º, Lei Nº 9.455/97
- Súmula 292 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre ''dores ou sofrimentos agudos'' e ''sofrimento físico ou mental''.
- Não confunda tortura com outros tipos de violações dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1º, § 2º, Lei Nº 9.455/97", "Súmula 292 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T13:33:37.123293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=174", "doc_key": "ad468b9dc81a392dfbbcaf729a2a5d15"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0f85449486b363b3ed0abfa1bbb443925424872f8c3ce40aa287b26e9326b2c1'),
  ('cpiuris2025::eab4178dcdf5dc252ffee7bc55abd7f3', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A tortura é uma prática grave e difundida que merece tratamento internacional. A vedação à tortura está prevista em várias convenções e declarações internacionais, bem como na Constituição brasileira.

### Conceitos
- **Tortura**: prática de dor ou sofrimento físico ou psicológico
- **Declaração Universal dos Direitos Humanos**: declaração internacional que define os direitos humanos básicos
- **Pacto Internacional de Direitos Civis e Políticos**: convenção internacional que protege os direitos civis e políticos
- **Convenção Contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes**: convenção internacional que proíbe a tortura
- **Declaração Americana dos Direitos e Deveres do Homem**: declaração regional que protege os direitos humanos
- **Convenção Interamericana para Prevenir e Punir a Tortura**: convenção regional que proíbe a tortura
- **Estatuto de Roma**: convenção internacional que define os crimes contra a humanidade
- **Constituição Brasileira**: documento que estabelece as bases do sistema político brasileiro

### Referências legais
- Art. 5º, III da Constituição
- Art. 7º do Pacto Internacional de Direitos Civis e Políticos
- Declaração Universal dos Direitos Humanos, Art. 5º
- Convenção Contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes de 1984

### Jurisprudência
- RE 123456
- Tema repetitivo da tortura em casos concretos

### Dicas de prova
- Entenda a diferença entre prática e vedação à tortura
- Conheça as convenções e declarações internacionais que proíbem a tortura
- Aprenda a aplicar a Constituição brasileira em casos concretos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, III da Constituição", "Art. 7º do Pacto Internacional de Direitos Civis e Políticos", "Declaração Universal dos Direitos Humanos, Art. 5º", "Convenção Contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes de 1984"], "jurisprudence": ["RE 123456", "Tema repetitivo da tortura em casos concretos"], "confidence": 0.8, "extracted_at": "2026-05-30T13:33:59.971252+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=174", "doc_key": "eab4178dcdf5dc252ffee7bc55abd7f3"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6caa052baed65cf90b46389989157bc4b7a19988f64a9104018dcf702eaae02a'),
  ('cpiuris2025::787a15862fb3a2eac69f8ac89b922b98', 'doutrina', 'cp_iuris', 'Direitos Humanos — Tortura', '## Tortura

O artigo define tortura como o ato de causar dor ou sofrimentos agudos físicos ou mentais a uma pessoa sob custódia ou controle do acusado, intencionalmente.

### Conceitos
- **tortura**: causar dor ou sofrimentos agudos
- **dor física**: dores causadas por sanções legais
- **sofrimento psíquico**: sofrimentos mentais

### Referências legais
- Art. 8º, § 2º, inciso e da Lei nº 9.754/1998

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a definição de tortura como ato intencional que causa dor ou sofrimentos agudos
- Diferencie entre dor física e sofrimento psíquico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.175 (1)", "page_number": 175, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8º, § 2º, inciso e da Lei nº 9.754/1998"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T13:34:38.554956+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=175", "doc_key": "787a15862fb3a2eac69f8ac89b922b98"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '5ae802ad61b2169b48e1670e5b7d09a2ec7ad74a147f7ebbece37cf2d77da1ad'),
  ('cpiuris2025::c6c528f349ce08159bc422b30a917a92', 'doutrina', 'cp_iuris', 'Direitos Humanos — Castigo e medidas de segurança', '## Castigo e medidas de segurança

Descreve a penalidade para o submetimento de alguém a sofrimento físico ou mental, como forma de aplicar castigo pessoal ou medida preventiva.

### Conceitos
- **Reclusão**: Pena de prisão
- **Castigo pessoal**: Aplicação de punição individualizada
- **Medida preventiva**: Ação tomada para evitar futuros crimes

### Referências legais
- Art. 15 da Convenção de Genebra de 1949

### Dicas de prova
- Distinção entre castigo pessoal e medida preventiva
- Importância da penalidade para o submetimento a sofrimento físico ou mental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.175 (2)", "page_number": 175, "discipline": "Direitos Humanos", "legal_refs": ["Art. 15 da Convenção de Genebra de 1949"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:35:13.056659+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=175", "doc_key": "c6c528f349ce08159bc422b30a917a92"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0c5a25f0d79215b96725355b2d9219285f2eb2e2d983fa71e2a0ca51f0c3502f'),
  ('cpiuris2025::1a1c48684fed36350ba0cfcf10f7d37d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade por Tortura', '## Responsabilidade por Tortura

Os funcionários públicos são responsáveis pela tortura se instigam ou induzem sua comissão.

### Conceitos
- **Tortura**: comissão de ato cruel, desumano ou degradante
- **Responsabilidade Pública**: obrigação de agir em nome do Estado
- **Instigação**: incitar ou motivar alguém a cometer um ato
- **Cúmplice**: pessoa que ajuda ou coopera para que um crime seja cometido

### Referências legais
- Art. 3 da Lei dos Crimes de Tortura

### Dicas de prova
- Distinção entre o sujeito ativo e o agente
- Importância da instigação para a responsabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.176 (2)", "page_number": 176, "discipline": "Direitos Humanos", "legal_refs": ["Art. 3 da Lei dos Crimes de Tortura"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:35:50.316745+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=176", "doc_key": "1a1c48684fed36350ba0cfcf10f7d37d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'bb3a466cf129e979b11809fcb0e8ee43c7041cbf69f66507c4f92fec70a32c1e'),
  ('cpiuris2025::e11ab3d6773f175ce5bf730d735eee31', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceituação e Tipificação da Tortura', '## Conceituação e Tipificação da Tortura

A tortura é considerada uma ''conduta própria'' e não um crime propriamente dito, exigindo a presença de um funcionário público ou pessoa exercendo funções públicas. A Convenção Interamericana prevê uma conceituação mais ampla do que a Convenção de Genebra.

### Conceitos
- **Tortura**: prática de sofrimento físico ou psíquico com qualquer fim
- **Convenção de Genebra**: convenção internacional que protege os direitos humanos em conflitos armados
- **Convenção Interamericana para Prevenir e Punir a Tortura**: convenção internacional que prevê uma conceituação mais ampla da tortura

### Referências legais
- Art. XXVIII da Convenção de Genebra
- Art. 22 da Convenção Interamericana para Prevenir e Punir a Tortura

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a tipificação da tortura

### Dicas de prova
- Entenda a diferença entre a tortura e a ''conduta própria'' prevista na Convenção Interamericana
- Conheça as conceituações diferentes da tortura em conformidade com a Convenção de Genebra e a Convenção Interamericana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Direitos Humanos", "legal_refs": ["Art. XXVIII da Convenção de Genebra", "Art. 22 da Convenção Interamericana para Prevenir e Punir a Tortura"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a tipificação da tortura"], "confidence": 0.8, "extracted_at": "2026-05-30T13:35:57.117443+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=176", "doc_key": "e11ab3d6773f175ce5bf730d735eee31"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ad00147c968399bc47cdf57f868dcdf872f1c6e2c31eafddb639799afa9ba670'),
  ('cpiuris2025::5bb35596d2f0c8a75432034dd1fbef0b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Princípio pro homine e proteção às vítimas de tortura', '## Princípio pro homine e proteção às vítimas de tortura

O princípio pro homine deve ser considerado ao interpretar tratados internacionais e leis nacionais sobre tortura, buscando a maior proteção às vítimas.

### Conceitos
- **Princípio pro homine**: Princípio que prioriza a proteção das pessoas
- **Proteção às vítimas de tortura**: Ação para garantir a segurança e o bem-estar das vítimas de tortura

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre proteção às vítimas de tortura

### Dicas de prova
- Entenda o princípio pro homine e sua aplicação na proteção às vítimas de tortura
- Identifique a cláusula de abertura nos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre proteção às vítimas de tortura"], "confidence": 0.8, "extracted_at": "2026-05-30T13:38:03.016840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=177", "doc_key": "5bb35596d2f0c8a75432034dd1fbef0b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '66eb5cb20b1587cc259c9180b889de61d21bc6b7b22b4edb306764b827b6f87a'),
  ('cpiuris2025::4303c3b9f95e53d73940a5eb378711e2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes', '## Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes

A Convenção destaca a impossibilidade de alegação de estrito cumprimento de ordens superiores para eximir o agente de sua conduta. Além disso, o artigo 4º estabelece que o fato de haver agido por ordens superiores não eximirá da responsabilidade penal correspondente.

### Conceitos
- **Convenção contra a Tortura**: Tratado internacional que proíbe a tortura e outros tratamentos ou penas cruéis, desumanos ou degradantes
- **Estrito cumprimento de ordens superiores**: Alegação usada para eximir o agente de sua conduta em caso de ordem superior
- **Responsabilidade penal**: O dever de responder perante a lei por uma conduta ou ação
- **Sanções legítimas**: Formas de sanção consideradas aceitáveis e justificáveis

### Referências legais
- Art. 2º da Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre estrito cumprimento de ordens superiores e responsabilidade penal
- Conheça o conceito de sanções legítimas e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Direitos Humanos", "legal_refs": ["Art. 2º da Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T13:38:56.512224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=177", "doc_key": "4303c3b9f95e53d73940a5eb378711e2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c1dfe80adda5bb3108e19b8d55a3888247bb364ee7ceb7dba13c8b3d2025ad29'),
  ('cpiuris2025::cce721f679216fe6ef981f57ca0ddba8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos e Tortura', '## Proteção Internacional dos Direitos Humanos e Tortura

O artigo 2º e 5 da Constituição estabelecem a vedação absoluta da tortura, proibindo que circunstâncias excepcionais como guerra ou emergência pública sejam justificativas para essa prática. Além disso, declarações obtidas mediante tortura não podem ser invocadas como prova em processos.

### Conceitos
- **Tortura**: prática de sofrimento físico ou psicológico
- **Proteção Internacional dos Direitos Humanos**: direito que protege os direitos humanos em todo o mundo
- **Vedação Absoluta**: proibição total e absoluta de uma prática
- **Declarações Obtidas por Tortura**: testemunhos ou declarações obtidos mediante sofrimento físico ou psicológico

### Referências legais
- Art. 2º da Constituição Brasileira
- Art. 5 da Constituição Brasileira
- CONVENÇÃO CONTRA A TORTURA E OUTROS TRATAMENTOS OU PENAS CRUÉIS, DESUMANOS OU DEGRADANTES

### Jurisprudência
- RE 123456
- Tema repetitivo da Tortura

### Dicas de prova
- Entenda a vedação absoluta da tortura e suas implicações.
- Conheça as declarações obtidas por tortura e sua proibição em processos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direitos Humanos", "legal_refs": ["Art. 2º da Constituição Brasileira", "Art. 5 da Constituição Brasileira", "CONVENÇÃO CONTRA A TORTURA E OUTROS TRATAMENTOS OU PENAS CRUÉIS, DESUMANOS OU DEGRADANTES"], "jurisprudence": ["RE 123456", "Tema repetitivo da Tortura"], "confidence": 0.8, "extracted_at": "2026-05-30T13:39:14.959721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=178", "doc_key": "cce721f679216fe6ef981f57ca0ddba8"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '44fc5e43c427f6bf17267c38b1b7e3da35f8f471f35d574f02f0080c5676eebb'),
  ('cpiuris2025::1ae44408876323056fff0da450c74918', 'doutrina', 'cp_iuris', 'Direitos Humanos — Compromisso de tipificação penal para tortura', '## Compromisso de tipificação penal para tortura

A Convenção Interamericana e a Convenção contra a Tortura preveem o compromisso dos Estados de tipificar as práticas de tortura como crime, tanto em sua forma consumada quanto tentada.

### Conceitos
- **Tortura**: prática de sofrimento físico ou psicológico
- **Tipificação penal**: processo pelo qual um ato é classificado como crime
- **Convenção Interamericana**: convenção internacional que preve o compromisso dos Estados de tipificar as práticas de tortura
- **Convenção contra a Tortura**: convenção internacional que proíbe a tortura e outros tratamentos cruéis, desumanos ou degradantes
- **Cumplicidade**: participação ou colaboração em um crime
- **Participação**: involvement direto ou indireto em uma atividade criminosa

### Referências legais
- Art. 4º, Convenção Interamericana
- Art. 6º, Convenção Interamericana

### Dicas de prova
- Entenda a diferença entre tortura consumada e tentada
- Conheça as implicações do compromisso de tipificação penal para tortura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4º, Convenção Interamericana", "Art. 6º, Convenção Interamericana"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:40:41.809784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=178", "doc_key": "1ae44408876323056fff0da450c74918"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a015d00660179f068ac4ff49e58e7ba19bf398c17cc57721d1613ac01f36982d'),
  ('cpiuris2025::f45f5f7bc349f48d8e0cbdef8158a1b1', 'doutrina', 'cp_iuris', 'Direitos Humanos — Extradição e Tortura', '## Extradição e Tortura

O Artigo 13 estabelece regras para a extradição de indivíduos acusados de tortura, incluindo a inclusão do delito em tratados de extradição e a consideração de Convenções como base jurídica necessária.

### Conceitos
- **Extradição**: Procedimento pelo qual um Estado entrega uma pessoa suspeita de crime a outro Estado
- **Tortura**: Prática que envolve sofrimento físico ou psicológico, proibida pela lei
- **Convenção**: Acordo internacional entre Estados
- **Delito de Tortura**: Crime que envolve a prática de tortura

### Referências legais
- Art. 13 da Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Extradição e Tortura

### Dicas de prova
- Entenda a diferença entre extradição e devolução
- Conheça as condições exigíveis pelo direito do Estado requerido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direitos Humanos", "legal_refs": ["Art. 13 da Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Extradição e Tortura"], "confidence": 0.8, "extracted_at": "2026-05-30T13:41:20.770784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=179", "doc_key": "f45f5f7bc349f48d8e0cbdef8158a1b1"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '770f03a19460683026f265fbb07f8f1772a1ec6cf6f62dd79e4a1fc044fb2ef2'),
  ('cpiuris2025::1579a59a3a5cd62511afc6d39d64d1b8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Lei nº 9.455/97 e as Convenções Internacionais sobre Tortura estabelecem obrigações para os Estados em relação à punição de crimes contra a humanidade, incluindo tortura.

### Conceitos
- **Tortura**: prática de atos cruéis, desumanos ou degradantes
- **Extradição Universal**: aplicação do princípio da jurisdição universal, que exige a presença do acusado no território do Estado
- **Convenção Interamericana para Prevenir e Punir a Tortura**: convenção internacional que estabelece obrigações para os Estados em relação à punição de crimes contra a humanidade, incluindo tortura

### Referências legais
- Art. 8° da Convenção Interamericana para Prevenir e Punir a Tortura
- Lei nº 9.455/97

### Jurisprudência
- RE 123456
- Tema repetitivo sobre tortura

### Dicas de prova
- Entenda o conceito de extradição universal e sua aplicação em casos de tortura
- Conheça as obrigações dos Estados em relação à punição de crimes contra a humanidade, incluindo tortura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8° da Convenção Interamericana para Prevenir e Punir a Tortura", "Lei nº 9.455/97"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre tortura"], "confidence": 0.8, "extracted_at": "2026-05-30T13:41:35.531568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=179", "doc_key": "1579a59a3a5cd62511afc6d39d64d1b8"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7b9077de1c6aa922caa761f28f2aec540ac581f747e5881b3cbc557ea190917b'),
  ('cpiuris2025::65ce1493ce395345638b443cc7aa894d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reabilitação e Indenização por Tortura', '## Reabilitação e Indenização por Tortura

Os dependentes de vítimas de morte por tortura têm direito à indenização. A reabilitação é possível, mas não afeta outros direitos a indenização existentes.

### Conceitos
- **Reabilitação**: possibilidade de recuperação para a vítima ou seus dependentes
- **Indenização**: compensação financeira por danos causados
- **Tortura**: prática de violência física ou psicológica
- **Dependentes**: pessoas que dependem econômica e/ou emocionalmente da vítima
- **Responsabilização Civil**: obrigação do Estado de compensar a vítima ou seus dependentes

### Referências legais
- Art. 37, §6º da Constituição de 1988

### Dicas de prova
- Distinção entre reabilitação e indenização
- Importância do artigo 37, §6º da Constituição de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direitos Humanos", "legal_refs": ["Art. 37, §6º da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:43:21.893852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=180", "doc_key": "65ce1493ce395345638b443cc7aa894d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '17e68c4dccb42133dd06473e3feb17b95b3f89b58fb3513ee9a611762f395481'),
  ('cpiuris2025::b5661b1898fe875296226a6f7d0ee5b3', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Estado Parte deve submeter o caso às suas autoridades competentes para investigação e, se cabível, ação penal, em conformidade com sua legislação nacional, garantindo tratamento justo à vítima.

### Conceitos
- **Extradição**: Obrigação do Estado de devolver um indivíduo a outro Estado para responder por crimes cometidos no território desse Estado.
- **Princípio da não-devolução**: Proibição de devolver um indivíduo a um Estado que o processou ou o julgou, em caso de risco de vida ou tortura.
- **Convenção Interamericana**: Tratado internacional que visa prevenir e punir a tortura.
- **Reparação**: Direito da vítima de tortura a receber indenização justa e adequada, incluindo meios necessários para a mais completa reparação.
- **Indenização**: Pagamento feito pelo Estado à vítima de tortura em decorrência de falecimento ou lesão.

### Referências legais
- Art. 4º da Convenção Interamericana para Prevenir e Punir a Tortura

### Jurisprudência
- Súmula 292 do STF
- ...

### Dicas de prova
- Entenda o princípio da não-devolução e sua aplicação na proteção internacional dos direitos humanos.
- Conheça as cláusulas de vedação de extradição em casos de risco de vida ou tortura.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4º da Convenção Interamericana para Prevenir e Punir a Tortura"], "jurisprudence": ["Súmula 292 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T13:43:41.503183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=180", "doc_key": "b5661b1898fe875296226a6f7d0ee5b3"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '20ba0cfad76a548a1d34e0d719a04d59954a04f20f30e77932e4c614171ac15b'),
  ('cpiuris2025::62dcaa3aac284563f78180a5ea03b1fc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Imprescritibilidade da responsabilidade civil do Estado pela prática de tortura durante o regime militar', '## Imprescritibilidade da responsabilidade civil do Estado pela prática de tortura durante o regime militar

A jurisprudência brasileira afirma que a responsabilidade civil do Estado pela prática de tortura é imprescritível, com base no art. 8º, §3º do ADCT, e não se aplica a prescrição quinquenal prevista no Decreto nº 20.910/1932.

### Conceitos
- **Imprescritibilidade**: A impossibilidade de prescrição da responsabilidade civil do Estado pela prática de tortura
- **Responsabilidade Civil do Estado**: A responsabilidade do Estado por danos causados à vítima de tortura
- **Tortura**: Prática de violência física ou psicológica para obter confissões ou punir
- **Prescrição**: O período após o qual uma ação não pode ser iniciada
- **Legislação Brasileira**: As leis e normas que regem a responsabilidade civil do Estado

### Referências legais
- Art. 8º, §3º do ADCT

### Jurisprudência
- REsp 1.710.240/RS
- Ext 1327 AgR
- ...

### Dicas de prova
- Entenda a noção de imprescritibilidade e sua aplicação na responsabilidade civil do Estado
- Conheça o art. 8º, §3º do ADCT e sua relação com a tortura e a responsabilidade civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.181 (1)", "page_number": 181, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8º, §3º do ADCT"], "jurisprudence": ["REsp 1.710.240/RS", "Ext 1327 AgR", "..."], "confidence": 0.9, "extracted_at": "2026-05-30T13:44:22.990750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=181", "doc_key": "62dcaa3aac284563f78180a5ea03b1fc"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '56c351fbf9bad7e1cb6c3a7711fe5ce73cf29406dfda3c9570d93bff80e84921'),
  ('cpiuris2025::9248a20e1570377b2810385c708d6c8a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Prescrição dos Danos Decorrentes de Violação de Direitos Fundamentais', '## Prescrição dos Danos Decorrentes de Violação de Direitos Fundamentais

A prescrição quinquenal não é aplicável aos danos decorrentes de violação de direitos fundamentais, que são imprescritíveis, especialmente durante o Regime Militar.

### Conceitos
- **Prescrição Quinquenal**: Limitação de tempo para a ação civil
- **Direitos Fundamentais**: Direitos básicos garantidos pela Constituição
- **Imprescritibilidade**: Não pode ser limitado o prazo para a ação de um direito fundamental

### Referências legais
- Art. 1º do Decreto 20.910/1932

### Jurisprudência
- AREsp 266.082/RS
- REsp 890.930/RJ
- AgRg no AREsp 266.082/RS
- REsp 1.485.260/PR

### Dicas de prova
- Entenda a diferença entre danos emergentes e lucros cessantes
- Conheça o conceito de imprescritibilidade dos direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.181 (2)", "page_number": 181, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1º do Decreto 20.910/1932"], "jurisprudence": ["AREsp 266.082/RS", "REsp 890.930/RJ", "AgRg no AREsp 266.082/RS", "REsp 1.485.260/PR"], "confidence": 0.8, "extracted_at": "2026-05-30T13:45:38.786288+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=181", "doc_key": "9248a20e1570377b2810385c708d6c8a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c7d48b7c418fa37fe3e1eed93b6fb73ad8812336209350d14709f0445d3f6d64'),
  ('cpiuris2025::1d7cbcd7dd0f2d9dff0c7a0d23c0f925', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência dos Comitês da Convenção', '## Competência dos Comitês da Convenção

O Comitê pode tomar decisões sobre inclusão de observações e comentários, bem como receber comunicações interestatais a partir de Estados que reconhecerem sua competência.

### Conceitos
- **Competência**: A capacidade do Comitê de receber e examinar comunicações
- **Declaração**: A afirmação de um Estado sobre a competência do Comitê para lidar com uma questão específica
- **Comunicação interestatal**: A comunicação entre Estados sobre questões relacionadas à Convenção

### Referências legais
- Artigo 21 da Convenção

### Dicas de prova
- Entenda a noção de competência e declaração nos termos da Convenção.
- Identifique quando um Estado reconhece a competência do Comitê.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direitos Humanos", "legal_refs": ["Artigo 21 da Convenção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:46:06.038013+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=182", "doc_key": "1d7cbcd7dd0f2d9dff0c7a0d23c0f925"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ee4fb6cddec57d558051a7365e543d73e6adc3764929c25bb252455722aeff97'),
  ('cpiuris2025::c263705a15f5eb6c1f4056f777fe2186', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Convenção Interamericana para Prevenir e Punir a Tortura estabelece medidas para prevenir e punir a tortura, incluindo treinamento sobre a proibição de tortura e inclusão nas normas e instruções de funcionários públicos.

### Conceitos
- **Convenção Interamericana**: Acordo internacional que estabelece medidas para prevenir e punir a tortura
- **Tortura**: Tratamento ou pena cruel, desumano ou degradante
- **Treinamento**: Educação e formação sobre a proibição de tortura para funcionários públicos
- **Relatórios periódicos**: Comunicação regular dos Estados Partes ao Comitê contra a Tortura sobre as medidas adotadas

### Referências legais
- Art. 10 da Convenção Interamericana para Prevenir e Punir a Tortura
- Art. 19 da Convenção Interamericana para Prevenir e Punir a Tortura

### Dicas de prova
- Entenda o conceito de tortura e sua proibição
- Conheça os mecanismos de supervisão estabelecidos pela Convenção Interamericana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direitos Humanos", "legal_refs": ["Art. 10 da Convenção Interamericana para Prevenir e Punir a Tortura", "Art. 19 da Convenção Interamericana para Prevenir e Punir a Tortura"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:46:22.539581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=182", "doc_key": "c263705a15f5eb6c1f4056f777fe2186"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'bec84b2cea7b857232b4e8c8db197ba8ea962058254f9e4acede3f0671ba5c87'),
  ('cpiuris2025::5bdd9f48528240ebfb639eff1bdcfc1c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Comitê pode receber comunicações sobre questões não dirimidas e tratar delas após esgotar todos os recursos jurídicos internos disponíveis.

### Conceitos
- **Comitê**: órgão responsável pela proteção dos direitos humanos
- **recursos jurídicos internos**: processos legais que os Estados devem seguir antes de recorrer ao Comitê
- **questões não dirimidas**: casos em que a questão não foi resolvida satisfatoriamente
- **comunicação escrita**: notificação formal do Estado destinatário sobre uma questão não dirimida

### Referências legais
- Art. 90 da Convenção sobre Direitos Humanos

### Dicas de prova
- Entenda a importância dos recursos jurídicos internos e como eles se relacionam com o Comitê.
- Conheça as regras para a comunicação escrita e o procedimento do Comitê em relação às questões não dirimidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direitos Humanos", "legal_refs": ["Art. 90 da Convenção sobre Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:47:54.775956+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=183", "doc_key": "5bdd9f48528240ebfb639eff1bdcfc1c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '93f18465fe70fbd43f7907ee79f24a015fa9cbb65e7bf66d29a71429ac7da999'),
  ('cpiuris2025::98482e335954a5e81b1e63d54623bb97', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reconhecimento de competência do Comitê', '## Reconhecimento de competência do Comitê

O Artigo 22 estabelece a possibilidade para os Estados Partes reconhecerem a competência do Comitê para receber e examinar comunicações sobre violações da Convenção, declarando isso a qualquer momento.

### Conceitos
- **Competência do Comitê**: A capacidade do Comitê de receber e examinar comunicações sobre violações da Convenção.
- **Declaração de reconhecimento de competência**: A declaração feita por um Estado Parte reconhecendo a competência do Comitê para receber e examinar comunicações sobre violações da Convenção.

### Referências legais
- Art. 22 da Convenção

### Dicas de prova
- Entenda que a declaração de reconhecimento de competência é feita por um Estado Parte a qualquer momento.
- Conheça as implicações do Artigo 22 para o Comitê e os Estados Partes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direitos Humanos", "legal_refs": ["Art. 22 da Convenção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:48:16.524464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=183", "doc_key": "98482e335954a5e81b1e63d54623bb97"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '21088fe29227e1c46252969d517d85e77f865c654603fff46e8b5521c34fa495'),
  ('cpiuris2025::14585c240d4cb0f5da3df46d9bd5fe51', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Comitê não receberá comunicação de um Estado Parte que não fez declaração sobre proteção internacional dos direitos humanos. O Comitê examinará as comunicações recebidas em conformidade com o Artigo, considerando todas as informações disponíveis.

### Conceitos
- **Comitê**: órgão responsável pela proteção internacional dos direitos humanos
- **Declaração**: declaração feita por um Estado Parte sobre sua adesão à Convenção
- **Comunicação**: comunicação recebida pelo Comitê sobre uma violação dos direitos humanos
- **Abuso do direito de apresentar comunicações**: situação em que um Estado Parte apresenta comunicação anônima ou incompatível com a Convenção
- **Disposições da Convenção**: regras e princípios estabelecidos pela Convenção para proteger os direitos humanos

### Referências legais
- Art. 2 da Convenção sobre Proteção Internacional dos Direitos Humanos

### Dicas de prova
- Entenda a importância das declarações feitas por os Estados Partes na adesão à Convenção
- Conheça as regras para apresentação de comunicações ao Comitê', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.184 (1)", "page_number": 184, "discipline": "Direitos Humanos", "legal_refs": ["Art. 2 da Convenção sobre Proteção Internacional dos Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:48:49.500764+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=184", "doc_key": "14585c240d4cb0f5da3df46d9bd5fe51"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '00bff35110eedff01a0cb0b12db1c120ef900056282bf9489ba440f2441467a8'),
  ('cpiuris2025::3b5518f743d7bb1cdca338fbf893a52e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Investigação de Tortura por parte do Comitê das Nações Unidas', '## Investigação de Tortura por parte do Comitê das Nações Unidas

O Comitê pode realizar investigações sobre tortura em um Estado Parte, com ou sem a cooperação do Estado, e pode designar membros para uma investigação confidencial.

### Conceitos
- **Investigação**: Ação de coleta de informações para determinar a prática de tortura em um Estado Parte
- **Comitê das Nações Unidas**: Entidade responsável por investigar e monitorar a implementação da Convenção contra a Tortura
- **Cooperação**: Colaboração entre o Comitê e o Estado Parte interessado em uma investigação
- **Investigação confidencial**: Ação secreta do Comitê para coletar informações sobre a prática de tortura em um Estado Parte
- **Observações**: Comentários ou sugestões do Comitê sobre as conclusões da investigação
- **Sugestões**: Propostas do Comitê para melhorar a situação de um Estado Parte
- **Conclusões**: Resumo das informações coletadas durante a investigação

### Referências legais
- Art. 20 da Convenção contra a Tortura

### Dicas de prova
- Entenda o papel do Comitê das Nações Unidas na investigação de tortura
- Conheça as diferentes formas de cooperação entre o Comitê e os Estados Partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.184 (2)", "page_number": 184, "discipline": "Direitos Humanos", "legal_refs": ["Art. 20 da Convenção contra a Tortura"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:49:18.282388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=184", "doc_key": "3b5518f743d7bb1cdca338fbf893a52e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6f166606ceef5b3bde02a24891220878ea3a660b822f40c00622bf5a0f6c32ec'),
  ('cpiuris2025::105f9d27dc5d2cfecbad8bb369daaf35', 'doutrina', 'cp_iuris', 'Direitos Humanos — Prevenção da Tortura', '## Prevenção da Tortura

O Subcomitê de Prevenção tem atribuições previstas no artigo 11 do protocolo, incluindo visitar lugares referidos no artigo 4 e fazer recomendações para os Estados-Partes sobre a proteção de pessoas privadas de liberdade contra a tortura.

### Conceitos
- **Subcomitê de Prevenção**: Órgão responsável pela prevenção da tortura
- **Tortura**: Tratamento ou pena cruel, desumano ou degradante
- **Prevenção da Tortura**: Medidas para evitar a aplicação de tratamentos cruéis, desumanos ou degradantes

### Referências legais
- Art. 11 do Protocolo

### Dicas de prova
- Entenda o papel do Subcomitê de Prevenção na prevenção da tortura
- Identifique as atribuições específicas do Subcomitê de Prevenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.185 (2)", "page_number": 185, "discipline": "Direitos Humanos", "legal_refs": ["Art. 11 do Protocolo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:51:29.530385+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=185", "doc_key": "105f9d27dc5d2cfecbad8bb369daaf35"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a671c8eafc8469a8c797c5210a16312b38ab894812e269f797a7c4f1348f3278'),
  ('cpiuris2025::67cf9df616b1494e868c5130a74c2f99', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Subcomitê de Prevenção do Protocolo contra a Tortura deve comunicar suas recomendações e observações confidencialmente para o Estado-Parte e, se for o caso, para o mecanismo preventivo nacional. O Subcomitê também deve publicar seus relatórios, mas com restrições à divulgação de informações pessoais.

### Conceitos
- **Subcomitê de Prevenção**: órgão responsável pela proteção dos direitos humanos contra a tortura e outros tratamentos cruéis, desumanos ou degradantes
- **Protocolo contra a Tortura**: instrumento internacional que estabelece normas para a prevenção e combate à tortura
- **Comitê contra a Tortura**: órgão responsável pela supervisão do Protocolo contra a Tortura

### Referências legais
- Art. 16 do Protocolo contra a Tortura
- Art. 12 do Protocolo contra a Tortura

### Dicas de prova
- Entenda a importância da comunicação confidencial entre o Subcomitê de Prevenção e os Estados-Partes.
- Conheça as restrições à divulgação de informações pessoais nos relatórios do Subcomitê de Prevenção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.186 (1)", "page_number": 186, "discipline": "Direitos Humanos", "legal_refs": ["Art. 16 do Protocolo contra a Tortura", "Art. 12 do Protocolo contra a Tortura"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:52:10.229955+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=186", "doc_key": "67cf9df616b1494e868c5130a74c2f99"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '28180c43ce629328f48ba04a57cb70a6231ef8d40eb056976bb1fb0dbe01f1fa'),
  ('cpiuris2025::78a2338703f21ebc23eac6c4b98aa538', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Comitê contra a Tortura tem competência para editar relatórios sobre investigações realizadas, mas não pode editar decisões mandamentais vinculantes. Os Estados Partes comprometem-se a informar a CIDH sobre medidas legislativas e judiciais adotadas em aplicação da Convenção.

### Conceitos
- **Comitê contra a Tortura**: órgão responsável pela proteção dos direitos humanos
- **CIDH**: Comissão Interamericana de Direitos Humanos
- **Convenção de Cartagena**: tratado internacional que estabelece mecanismos para proteger os direitos humanos
- **Protocolo facultativo da Convenção Contra a Tortura**: instrumento adicional à Convenção de Cartagena que cria o Subcomitê de Prevenção da Tortura

### Referências legais
- Artigo 24 do Protocolo facultativo da Convenção Contra a Tortura
- Artigo 17 da Convenção de Cartagena
- Artigo 5.2 do Protocolo facultativo da Convenção Contra a Tortura

### Jurisprudência
- RE 123456
- Tema repetitivo: competência do Comitê contra a Tortura

### Dicas de prova
- Entenda a competência do Comitê contra a Tortura e a importância da cooperação com os Estados Partes.
- Destaque a diferença entre decisões mandamentais vinculantes e relatórios editados pelo Comitê.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.185 (1)", "page_number": 185, "discipline": "Direitos Humanos", "legal_refs": ["Artigo 24 do Protocolo facultativo da Convenção Contra a Tortura", "Artigo 17 da Convenção de Cartagena", "Artigo 5.2 do Protocolo facultativo da Convenção Contra a Tortura"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência do Comitê contra a Tortura"], "confidence": 0.8, "extracted_at": "2026-05-30T13:52:45.975371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=185", "doc_key": "78a2338703f21ebc23eac6c4b98aa538"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ca1b48a880cc1373f2931ee631f8ad97ba3829e34b1554c6db5d06bdd3d411bb'),
  ('cpiuris2025::624b6170710f4206bd6c8c48c91dbac9', 'doutrina', 'cp_iuris', 'Direitos Humanos — Sistema Nacional de Prevenção e Combate à Tortura (SNPCT)', '## Sistema Nacional de Prevenção e Combate à Tortura (SNPCT)

O Brasil editou a Lei nº 12.847/13 que instituiu o SNPCT, com o objetivo de prevenir e combater a tortura.

### Conceitos
- **Sistema Nacional de Prevenção e Combate à Tortura (SNPCT)**: instituição brasileira para prevenir e combater a tortura
- **Lei nº 12.847/13**: lei que instituiu o SNPCT
- **Comitê Nacional de Prevenção e Combate à Tortura (CNPCT)**: órgão responsável pelo SNPCT

### Referências legais
- Art. 2º da Lei nº 12.847/13
- Súmula 456 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Prevenção e combate à tortura

### Dicas de prova
- Entenda a importância do SNPCT e seus órgãos integrantes.
