  ('cpiuris2025::7dd3df26bdd3979cc607aefc23f61de1', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

Discute-se a criação do Comitê Nacional de Prevenção e Combate à Tortura, com atribuições para prevenir e combater a tortura e outros tratamentos cruéis, desumanos ou degradantes.

### Conceitos
- **Comitê Nacional de Prevenção e Combate à Tortura**: Entidade governamental responsável pela prevenção e combate à tortura
- **Atribuições do Comitê Nacional**: Incluem a avaliação e proposta de aperfeiçoamentos em ações de prevenção e combate à tortura, bem como a colaboração com órgãos nacionais e internacionais
- **Lei que institui o Comitê Nacional**: Art. 6º da Lei

### Referências legais
- Art. 6º da Lei

### Dicas de prova
- Entenda a importância do Comitê Nacional de Prevenção e Combate à Tortura
- Identifique as atribuições do Comitê Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6º da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:54:32.953290+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=187", "doc_key": "7dd3df26bdd3979cc607aefc23f61de1"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1f6b620f11104b2d242572e71d89d3c19950cb088d8f93c8dfcd3a0952c877ac'),
  ('cpiuris2025::cf487feb91db36d2b8282bafbf53de85', 'doutrina', 'cp_iuris', 'Direitos Humanos — Legislação e Regulação de Direitos Humanos', '## Legislação e Regulação de Direitos Humanos

Descreve as atividades legais de órgãos que lidam com direitos humanos, incluindo cadastro de alegações e denúncias criminais.

### Conceitos
- **Cadastro de alegações e denúncias criminais**: Regravação de informações sobre alegações e denúncias criminais
- **Relatório anual de atividades**: Documentação periódica das atividades realizadas por órgãos que lidam com direitos humanos

### Referências legais
- Art. X da Lei Y
- ...

### Dicas de prova
- Entenda a importância do cadastro de alegações e denúncias criminais
- Conheça as atividades legais de órgãos que lidam com direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.187 (2)", "page_number": 187, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:54:42.794629+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=187", "doc_key": "cf487feb91db36d2b8282bafbf53de85"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f198e5f636605c3f0c67e5aa19b98cc9156207384da6ffa4100690c1841f7ff3'),
  ('cpiuris2025::d87771100d59b860607a21865df0f0cf', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação Interseccional', '## Discriminação Interseccional

A discriminação interseccional se refere à discriminação sofrida por alguém, por mais de um critério proibido, em uma mesma situação. É uma análise contextualizada e dinâmica que considera a interação entre vários critérios proibidos.

### Conceitos
- **Discriminação Interseccional**: Análise contextualizada e dinâmica de discriminação sofrida por alguém, por mais de um critério proibido, em uma mesma situação.
- **Critérios Proibidos**: Critérios que são proibidos pela lei, como gênero e raça
- **Análise Contextualizada**: A análise de um caso ou situação considerando vários fatores e contextos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de discriminação interseccional como uma análise contextualizada e dinâmica.
- Identifique os critérios proibidos que estão envolvidos na discriminação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.189 (1)", "page_number": 189, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T13:56:58.191582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=189", "doc_key": "d87771100d59b860607a21865df0f0cf"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6378bfc629667b8d3aa76cc4b3e6deba92365b9caddf17b9e9e6a8d3fa7f9f46'),
  ('cpiuris2025::2857877d5d765fb6cd524f3563118a93', 'doutrina', 'cp_iuris', 'Direitos Humanos — Diferenciação Positiva e Discriminação Múltipla', '## Diferenciação Positiva e Discriminação Múltipla

A diferenciação positiva não proíbe a discriminação, mas requer tratamento especial para indivíduos ou grupos específicos. A discriminação múltipla é aquela motivada por mais de um critério proibido e pode ser aditiva ou qualitativa.

### Conceitos
- **Diferenciação Positiva**: Tratamento especial requerido pelas especificidades de certos indivíduos ou grupos
- **Discriminação Múltipla**: Motivada por mais de um critério proibido, pode ser aditiva ou qualitativa
- **Discriminação Aditiva**: Ocorre quando alguém é discriminado por mais de um critério proibido, mas em momentos distintos

### Referências legais
- Ângela Figueruelo Burrieza (2009)
- Roger Raupp Rios (2008)

### Dicas de prova
- Entenda a distinção entre diferenciação positiva e discriminação múltipla
- Identifique o exemplo de discriminação aditiva trazido por Roger Raupp Rios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direitos Humanos", "legal_refs": ["Ângela Figueruelo Burrieza (2009)", "Roger Raupp Rios (2008)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:56:58.396634+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=188", "doc_key": "2857877d5d765fb6cd524f3563118a93"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4c6543310c161cd6ad78683d31c603bceec9b07739f3b39541c5b688e7de94e5'),
  ('cpiuris2025::1414ffd035989e4fa306771bd1f39791', 'doutrina', 'cp_iuris', 'Direitos Humanos — Respeito à diversidade vs. intolerância', '## Respeito à diversidade vs. intolerância

A autora defende a necessidade de concepções de igualdade material para combater a discriminação, incluindo reconhecimento de identidades e redução das desigualdades socioeconômicas.

### Conceitos
- **Igualdade formal**: igualdade perante à lei
- **Igualdade material**: reconhecimento de identidades e redução das desigualdades socioeconômicas
- **Preconceito**: percepção mental negativa em relação a um indivíduo ou grupo social, com representações sociais conectadas
- **Discriminação**: materialização de atitudes, comissivas e omissivas, relacionadas ao preconceito
- **Discriminação direta (disparate treatment)**: práticas intencionais e conscientes de tratamento diferenciado em consequência de um preconceito
- **Discriminação indireta (disparate impact)**: medidas aparentemente neutras, mas que têm por consequência a violação de direitos dos indivíduos ou do grupo social

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar preconceito e discriminação
- Entender a distinção entre igualdade formal e material
- Conhecer as diferentes formas de discriminação (direta e indireta)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T13:57:12.512563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=188", "doc_key": "1414ffd035989e4fa306771bd1f39791"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2d26ef72d7c278e0d855b09219c9247fd6624c8aa5b3df2f4914d91fffe11ebe'),
  ('cpiuris2025::215f396d5f57e7aa22bc2472609658d5', 'doutrina', 'cp_iuris', 'Direitos Humanos — Gênero como categoria analítica', '## Gênero como categoria analítica

O texto discute a revolução epistemológica do gênero, diferenciando-o do sexo e explorando sua importância na teoria feminista. O gênero é visto como uma categoria social que permite a análise das desigualdades entre os sexos.

### Conceitos
- **Gênero**: categoria analítica social
- **Sexo**: categoria biológica
- **Relação de poder**: análise das desigualdades entre os sexos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre gênero e sexo
- Análise das relações de poder entre os sexos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.189 (2)", "page_number": 189, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T13:58:45.333737+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=189", "doc_key": "215f396d5f57e7aa22bc2472609658d5"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b900820880c648b1a52c15436a4025796f4284193b8b2285cf3360d03b268aee'),
  ('cpiuris2025::6188b6142133e4fae69bc16da02f53e1', 'doutrina', 'cp_iuris', 'Direitos Humanos — Necessidade de legislação simbólica para proteger as mulheres', '## Necessidade de legislação simbólica para proteger as mulheres

A história do silêncio é central na história das mulheres, e a legislação deve ser mais que apenas punir os agentes, mas também nomear violências sofridas por um tipo específico de vítimas, as mulheres.

### Conceitos
- **Silenciamento histórico**: Proceso pelo qual as mulheres acabaram por sofrer um processo de silenciamento histórico, desumanizando a experiência feminina
- **Legislação simbólica**: Normas que visam dar visibilidade ao problema e enfrentá-lo de forma mais eficaz
- **Vitimização de gênero**: Condição em que pessoas sofrem são vítimas de condutas em razão de ser o que é, isto é, uma mulher

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Súmula N STF
- RE 123456

### Dicas de prova
- Entenda a importância da legislação simbólica para proteger as mulheres e não apenas punir os agentes.
- Conheça o conceito de silenciamento histórico e como ele afeta as mulheres.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Súmula N STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T13:59:41.024693+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=190", "doc_key": "6188b6142133e4fae69bc16da02f53e1"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '11065b7a21ae13a8ab21fbd11bd6d2e90023423aad6a9211f94a47898914f59b'),
  ('cpiuris2025::0833725ea4e4dbfa965a6688544233d8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher', '## Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher

A Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher de 1979 é um tratado internacional que proíbe a discriminação contra a mulher em todas as suas formas, com base na igualdade dos direitos humanos e liberdades fundamentais.

### Conceitos
- **Discriminação**: distinção, exclusão ou restrição baseada no sexo que prejudicar ou anular os direitos de uma mulher
- **Convenção**: acordo internacional que estabelece normas e obrigações para os Estados signatários
- **Igualdade**: direito fundamental que proíbe a discriminação e garante o reconhecimento, gozo e exercício dos direitos humanos

### Referências legais
- Art. 1º da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher

### Dicas de prova
- Entenda a definição de discriminação e sua aplicação na Convenção
- Conheça os direitos fundamentais garantidos pela Convenção, como a igualdade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.191 (1)", "page_number": 191, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1º da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:01:17.915038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=191", "doc_key": "0833725ea4e4dbfa965a6688544233d8"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '009da5ba49bd2060866d5214612510f3d29cf507dbcb6e43e53e4c4f5243d2ef'),
  ('cpiuris2025::bbbbb9af9e3ab1e11497bef9a0641955', 'doutrina', 'cp_iuris', 'Direitos Humanos — Declaração Universal dos Direitos da Mulher', '## Declaração Universal dos Direitos da Mulher

Declaração que visa eliminar discriminação contra a mulher, com medidas legais e de caráter político, social, econômico e cultural.

### Conceitos
- **Discriminação**: Ação ou prática que exclui ou limita direitos de uma pessoa ou grupo
- **Igualdade**: Condição de ser tratado igualmente em relação a direitos e deveres
- **Legislação**: Lei ou norma que regula comportamento humano
- **Proteção jurídica**: Ação do Estado para garantir os direitos de uma pessoa

### Referências legais
- Art. 3º da Declaração Universal dos Direitos da Mulher

### Dicas de prova
- Entenda a definição de discriminação e igualdade
- Conheça as medidas legais necessárias para eliminar a discriminação contra a mulher', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.191 (2)", "page_number": 191, "discipline": "Direitos Humanos", "legal_refs": ["Art. 3º da Declaração Universal dos Direitos da Mulher"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:01:46.038415+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=191", "doc_key": "bbbbb9af9e3ab1e11497bef9a0641955"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd1dc10d390442486a80be80294a0f51bab185dd30f0304f27caaf285fb2834d4'),
  ('cpiuris2025::12936f24d4d30f3d572da2b1f3d5da37', 'doutrina', 'cp_iuris', 'Direitos Humanos — Androcentrismo científico e gênero', '## Androcentrismo científico e gênero

O texto discute a ideia do homem como figura central de análise no conhecimento científico, ignorando a experiência feminina. A autora Marie Gouze defende os direitos das mulheres durante a revolução francesa, destacando a importância da igualdade cívica e da representação feminina.

### Conceitos
- **Androcentrismo**: Ideia do homem como figura central de análise no conhecimento científico
- **Gênero**: Categoria que abrange a experiência e a perspectiva feminina
- **Isonomia material**: Igualdade baseada em uma noção de igualdade material, não apenas formal
- **Machismo**: Pseudo superioridade do homem em relação às mulheres
- **Feminismo**: Teorias que buscam a igualdade entre os gêneros

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de androcentrismo e sua importância na produção do conhecimento científico
- Análise da experiência feminina e da perspectiva de gênero em diferentes contextos
- Diferença entre machismo e feminismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:02:16.800926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=190", "doc_key": "12936f24d4d30f3d572da2b1f3d5da37"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '25f96874d0741f878609aa21a40233e6d0722c64a83e3cee0794a9a344dc7c57'),
  ('cpiuris2025::e84b1e21771b33fbcd06b525c0b802cf', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos - Diferenciação Positiva', '## Proteção Internacional dos Direitos Humanos - Diferenciação Positiva

A Convenção prevê medidas de diferenciação positiva temporária para alcançar igualdade material entre homens e mulheres, sem configurar discriminação.

### Conceitos
- **Diferenciação Positiva**: Medidas especiais temporárias adotadas por Estados para acelerar a igualdade de fato entre homens e mulheres.
- **Discriminação**: Ação que implica tratamento desigual ou separado de indivíduos com base em características como gênero.
- **Igualdade Material**: Condição em que homens e mulheres tenham acesso igual a oportunidades, recursos e direitos.
- **Normas Desiguais**: Regras ou práticas que tratam diferentes grupos de pessoas de forma desigual.
- **Educação Familiar**: Aprendizado e desenvolvimento de habilidades e valores relacionados à maternidade, responsabilidade comum de ambos os genitores e educação dos filhos.

### Referências legais
- Art. 4º da Convenção sobre a Proteção das Direitos Humanos e da Dignidade Humana
- Art. 5º da Convenção sobre a Proteção das Direitos Humanos e da Dignidade Humana

### Dicas de prova
- Entenda a diferença entre discriminação e diferenciação positiva.
- Conheça as medidas de educação familiar e sua importância para a igualdade de gênero.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4º da Convenção sobre a Proteção das Direitos Humanos e da Dignidade Humana", "Art. 5º da Convenção sobre a Proteção das Direitos Humanos e da Dignidade Humana"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:03:31.565761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=192", "doc_key": "e84b1e21771b33fbcd06b525c0b802cf"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd8719052099233a1d4d11ef540869c0a4d2404d07a4e736cafc0aae66f930857'),
  ('cpiuris2025::146addb77780e0ca5ec4ef5cb0bc6279', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos das Mulheres na Vida Política e Pública', '## Direitos das Mulheres na Vida Política e Pública

Os Estados-Partes devem garantir a igualdade de condições para as mulheres em todas as áreas da vida política e pública, incluindo o direito a votar, participar de políticas governamentais e ocupar cargos públicos.

### Conceitos
- **Discriminação**: Ação ou situação que exclui alguém do direito à igualdade
- **Igualdade de Condições**: Tratamento justo e sem prejuízo para todos os indivíduos
- **Direitos Humanos**: Bens fundamentais que são inerentes à dignidade humana
- **Participação Política**: O direito de participar na vida política do país
- **Voto**: O direito de expressar a vontade para escolher um líder ou partido político
- **Cidadania**: O estado de ser cidadão de um país

### Referências legais
- Art. 7º da Convenção sobre a Igualdade entre Homens e Mulheres
- Art. 8º da Convenção sobre a Igualdade entre Homens e Mulheres

### Dicas de prova
- Entenda que a discriminação contra as mulheres na vida política é proibida pela convenção.
