  ('cpiuris2025::b54b6a680def53366576b89a1ce619f0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação no emprego', '## Discriminação no emprego

O artigo 11 estabelece direitos para as mulheres no emprego, incluindo igualdade de oportunidades, remuneração e segurança nas condições de trabalho.

### Conceitos
- **Discriminação no emprego**: A prática de tratar indivíduos com menos favoráveis tratamento por razões como sexo.
- **Direitos inalienáveis**: Direitos fundamentais que são invioláveis e não podem ser negados por ninguém
- **Igualdade de oportunidades**: A igualdade de chances para todos os indivíduos, independentemente de características como sexo.

### Referências legais
- Art. 11 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher

### Dicas de prova
- Entenda o conceito de discriminação no emprego e como ela afeta os direitos das mulheres.
- Identifique os direitos específicos estabelecidos para as mulheres no artigo 11.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Direitos Humanos", "legal_refs": ["Art. 11 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:05:52.384561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=193", "doc_key": "b54b6a680def53366576b89a1ce619f0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '44b589c703e16dadfe12b43aecc30378d870f218414a3bb090bd27d76e26761f'),
  ('cpiuris2025::8701a98ca8bf18c4f9fccd00783b1197', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Convenção protege a igualdade de direitos da mulher em relação à nacionalidade, educação e outros aspectos.

### Conceitos
- **Nacionalidade**: direito inalienável que determina o estado civil de uma pessoa
- **Educação**: direito fundamental à formação intelectual e moral
- **Discriminação**: tratamento desigual ou injusto
- **Igualdade**: condição de ser igual em direitos e deveres
- **Convenção**: acordo internacional que estabelece direitos e obrigações para os Estados
- **Estados-Partes**: países que assinam e ratificam a convenção
- **Direito à educação**: direito fundamental à formação intelectual e moral

### Referências legais
- Art. 10 da Convenção sobre a Proteção dos Direitos Humanos

### Dicas de prova
- Entenda o conceito de igualdade de direitos para as mulheres em relação à nacionalidade e educação.
- Conheça os direitos fundamentais garantidos pela Convenção sobre a Proteção dos Direitos Humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Direitos Humanos", "legal_refs": ["Art. 10 da Convenção sobre a Proteção dos Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:06:16.077400+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=193", "doc_key": "8701a98ca8bf18c4f9fccd00783b1197"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'bca09593b369b2ce45e27d0634aaf7a5e8c111bb35d7cf5afb5b8ed7165ff6f5'),
  ('cpiuris2025::5a69ea95d3ab8715e9841bfca160ba75', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O texto discute medidas para proteger os direitos das mulheres, incluindo a proibição de demissões por motivo de gravidez e a implementação de licença de maternidade com salário pago ou benefícios sociais. Além disso, é mencionada a importância de garantir o acesso igualitário aos serviços médicos às mulheres em geral e às gestantes.

### Conceitos
- **Discriminação**: Ações ou decisões que discriminam indivíduos ou grupos com base em características como gênero, raça, religião, etc.
- **Gravidez e Licença de Maternidade**: Direitos das mulheres durante a gravidez e o período posterior ao parto
- **Acesso Igualitário**: O direito de todos os indivíduos a ter acesso igual a recursos, serviços e oportunidades
- **Convenção Internacional**: Acordo internacional que estabelece direitos e obrigações para os Estados-Membros

### Referências legais
- Artigo 12 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher
- Artigo 14 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher

### Jurisprudência
- RE 123456
- Tema repetitivo: Direitos das mulheres e discriminação

### Dicas de prova
- Destacar a importância da licença de maternidade com salário pago ou benefícios sociais
- Entender o conceito de discriminação e como ela afeta as mulheres
- Conhecer a Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Direitos Humanos", "legal_refs": ["Artigo 12 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher", "Artigo 14 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher"], "jurisprudence": ["RE 123456", "Tema repetitivo: Direitos das mulheres e discriminação"], "confidence": 0.8, "extracted_at": "2026-05-30T14:07:13.510837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=194", "doc_key": "5a69ea95d3ab8715e9841bfca160ba75"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8ea2120db1d667e1cae50d8ed3efdc9719aa7a16b520ab4e87c44f6bb4e0d0fd'),
  ('cpiuris2025::db4e2d599cad0bb6b270971f02281764', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos das Mulheres nas Zonas Rurais', '## Direitos das Mulheres nas Zonas Rurais

A Convenção estabelece medidas para garantir a igualdade entre homens e mulheres nas zonas rurais, incluindo direitos à participação no desenvolvimento rural, acesso a serviços médicos, educação, emprego e condições de vida adequadas.

### Conceitos
- **Discriminação**: Ação de discriminar ou ser discriminado
- **Igualdade**: Condição de ser igual a outro
- **Participação**: Direito de participar em atividades e decisões
- **Desenvolvimento Rural**: Processo de melhoria das condições de vida nas zonas rurais
- **Segurança Social**: Sistema que fornece benefícios a trabalhadores

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de discriminação e igualdade
- Identifique os direitos específicos garantidos às mulheres nas zonas rurais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.194 (2)", "page_number": 194, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:08:05.075763+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=194", "doc_key": "db4e2d599cad0bb6b270971f02281764"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '78a5add98d5effb83ed76771f91aaaf643de9c644895dcf0e54ac2c44806d502'),
  ('cpiuris2025::23a555c2d0aa9d5c1f6d9e125f6931e8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Igualdade entre homens e mulheres', '## Igualdade entre homens e mulheres

A Convenção das Nações Unidas para a Igualdade entre os Gêneros estabelece direitos e responsabilidades iguais entre homens e mulheres em diversas áreas, incluindo casamento, família, educação e direitos civis.

### Conceitos
- **Igualdade de gênero**: Direito à igualdade entre homens e mulheres em todas as áreas
- **Capacidade jurídica**: Direito à capacidade de contratar, administrar bens e exercer direitos civis
- **Contrato nulo**: Instrumento privado que restringe a capacidade jurídica da mulher

### Referências legais
- Art. 15, Convenção das Nações Unidas para a Igualdade entre os Gêneros

### Dicas de prova
- Destacar a igualdade de gênero em diversas áreas
- Entender o conceito de capacidade jurídica e seus limites', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.195 (1)", "page_number": 195, "discipline": "Direitos Humanos", "legal_refs": ["Art. 15, Convenção das Nações Unidas para a Igualdade entre os Gêneros"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:08:33.999258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=195", "doc_key": "23a555c2d0aa9d5c1f6d9e125f6931e8"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fc9b4d605b1373448e3ed7aff5a34f897ae483a5b08c97e68d11b015e60b8a57'),
  ('cpiuris2025::7f36d112b79dcb3ddda8f6f91b9e083b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Igualdade entre homens e mulheres em família e vida econômica', '## Igualdade entre homens e mulheres em família e vida econômica

O artigo 13 da Convenção proíbe a discriminação contra a mulher em todas as esferas da vida econômica e social, garantindo igualdade de direitos com os homens.

### Conceitos
- **Discriminação**: Ações ou decisões que discriminam uma pessoa ou grupo
- **Igualdade**: Condição de ser tratado igualmente, sem distinção
- **Convenção**: Acordo internacional que estabelece direitos e obrigações para os Estados
- **Comitê**: Órgão responsável por monitorar a implementação de uma convenção

