  ('cpiuris2025::74f2df8e1b6b153693ce30a29a16b162', 'doutrina', 'cp_iuris', 'Direitos Humanos — Eleição e mandato dos membros do Comitê', '## Eleição e mandato dos membros do Comitê

Regulamentação da eleição e mandato dos membros do Comitê, incluindo a duração do mandato e as condições de remuneração.

### Conceitos
- **Mandato**: Prazo durante o qual um membro do Comitê exerce suas funções
- **Eleição**: Proceso pelo qual os membros do Comitê são escolhidos
- **Remuneração**: Pagamento recebido pelos membros do Comitê por suas funções

### Referências legais
- Art. 18 da Convenção

### Dicas de prova
