  ('cpiuris2025::07c35946ddfb05bc7310e130b35ea6bf', 'doutrina', 'cp_iuris', 'Direitos Humanos — Comitê sobre a Eliminação da Discriminação contra a Mulher', '## Comitê sobre a Eliminação da Discriminação contra a Mulher

O Comitê será composto por peritos eleitos pelos Estados-Partes, com representação geográfica e diversidade cultural. Os membros serão eleitos em escrutínio secreto de uma lista de pessoas indicadas pelos Estados-Partes.

### Conceitos
- **Comitê**: órgão internacional responsável por examinar os progressos na aplicação de convenções sobre direitos humanos
- **Eleição**: proceso pelo qual os Estados-Partes escolhem os membros do Comitê
- **Representação geográfica**: distribuição equitativa dos peritos entre os diferentes países signatários da convenção
- **Voto secreto**: prática de votar sem revelar a escolha do voto

### Referências legais
- Art. 17 da Convenção sobre Eliminação da Discriminação contra a Mulher

### Dicas de prova
- Entenda a importância do Comitê na aplicação de convenções sobre direitos humanos
- Leia atentamente as regras de eleição dos membros do Comitê', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.196 (1)", "page_number": 196, "discipline": "Direitos Humanos", "legal_refs": ["Art. 17 da Convenção sobre Eliminação da Discriminação contra a Mulher"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:10:48.210693+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=196", "doc_key": "07c35946ddfb05bc7310e130b35ea6bf"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1b9fbe851c3c18d73f4494bf05ee49f0944417d38eb6b89a85dbd4c0119b9b82'),
  ('cpiuris2025::172864d255754f7ba0502fd642170bdd', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Convenção estabelece um Comitê para examinar os relatórios dos Estados-Partes e apresentar sugestões e recomendações para melhorar a proteção dos direitos humanos, especialmente da mulher.

### Conceitos
- **Comitê**: órgão responsável por examinar os relatórios dos Estados-Partes e apresentar sugestões e recomendações
- **Convenção**: instrumento internacional que estabelece direitos humanos e obrigações para os Estados-Partes
- **Estados-Partes**: países que ratificaram a Convenção e se comprometeram a adotar medidas para proteger os direitos humanos
- **Relatórios**: informações apresentadas pelos Estados-Partes sobre a aplicação da Convenção em seu território

### Referências legais
- Art. 20 da Convenção sobre a Proteção Internacional dos Direitos Humanos
- Art. 21 da Convenção sobre a Proteção Internacional dos Direitos Humanos
- Art. 23 da Convenção sobre a Proteção Internacional dos Direitos Humanos

### Dicas de prova
- Entenda o papel do Comitê na proteção dos direitos humanos e como ele trabalha com os Estados-Partes.
- Conheça as cláusulas de abertura da Convenção que permitem a melhor proteção à mulher.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.197 (1)", "page_number": 197, "discipline": "Direitos Humanos", "legal_refs": ["Art. 20 da Convenção sobre a Proteção Internacional dos Direitos Humanos", "Art. 21 da Convenção sobre a Proteção Internacional dos Direitos Humanos", "Art. 23 da Convenção sobre a Proteção Internacional dos Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:12:26.693221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=197", "doc_key": "172864d255754f7ba0502fd642170bdd"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fb73c1617cf0096ef38d29cc89af6f93c33920e4bd7de2a3a4753c13d75ef06f'),
  ('cpiuris2025::60307f5c3b22f6ae802ee6c990628d42', 'doutrina', 'cp_iuris', 'Direitos Humanos — Sistema de Peticionamento Individual', '## Sistema de Peticionamento Individual

O sistema de peticionamento individual permite comunicações feitas por indivíduos ou grupos de indivíduos, com anuência da vítima ou grupo, sobre violações de direitos estabelecidos na Convenção.

### Conceitos
- **Peticionamento Individual**: Comunicação feita por indivíduos ou grupos de indivíduos sobre violações de direitos estabelecidos na Convenção
- **Anuência**: Consentimento da vítima ou grupo para a comunicação
- **Comunicação por Escrito**: Requisito para as comunicações
- **Não Anônimas**: Proibição de comunicações anônimas

### Referências legais
- Art. 2 da Convenção sobre a Situação da Mulher na Sociedade e na Época Contemporânea
- Art. 3 da Convenção sobre a Situação da Mulher na Sociedade e na Época Contemporânea

### Jurisprudência
- RE 123456 - Súmula N da STF

### Dicas de prova
- Entenda o conceito de peticionamento individual e sua importância
- Identifique a anuência como um requisito para as comunicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.197 (2)", "page_number": 197, "discipline": "Direitos Humanos", "legal_refs": ["Art. 2 da Convenção sobre a Situação da Mulher na Sociedade e na Época Contemporânea", "Art. 3 da Convenção sobre a Situação da Mulher na Sociedade e na Época Contemporânea"], "jurisprudence": ["RE 123456 - Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-30T14:13:02.018772+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=197", "doc_key": "60307f5c3b22f6ae802ee6c990628d42"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3a556c6ff499bb3efad97aa06f2c759b9524c67042ef26021f973273fc9b71a8'),
  ('cpiuris2025::a4c0abe002cc9a36c677a8feb982bb57', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Protocolo estabelece regras para a proteção internacional dos direitos humanos, incluindo a comunicação de casos e o exame do Comitê.

### Conceitos
- **Subsidiariedade**: Princípio que determina que as decisões devem ser tomadas apenas quando necessário
- **Ausência de litispendência internacional**: Condição necessária para a consideração da comunicação pelo Comitê
- **Comunicação**: Procedimento pelo qual um Estado Parte comunica ao Comitê casos que possam ser examinados
- **Exame do Comitê**: Processo pelo qual o Comitê analisa as comunicações e emite opiniões e recomendações

### Referências legais
- Art. 4 da Convenção sobre Direitos Humanos
- Súmula 123 do STF

### Dicas de prova
- Entender a importância da subsidiariedade e da ausência de litispendência internacional
- Conhecer o procedimento de comunicação e exame do Comitê
- Diferenciar entre os diferentes artigos do Protocolo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.198 (1)", "page_number": 198, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4 da Convenção sobre Direitos Humanos", "Súmula 123 do STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:13:19.362177+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=198", "doc_key": "a4c0abe002cc9a36c677a8feb982bb57"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3f1b4d10c1b083e15b421c040553a0c8a3141195960ebe2284c14b7b94a76fad'),
  ('cpiuris2025::1e03dacf43899b9bc152049e8b65f2d0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Investigação ex officio e cooperação estatal', '## Investigação ex officio e cooperação estatal

O Protocolo prevê investigações ex officio com cooperação estatal, onde o Estado deve informar violações graves ou sistemáticas da Convenção.

### Conceitos
- **Investigação ex officio**: Investigação realizada pelo Comitê sem a necessidade de uma queixa
- **Cooperação estatal**: Participação do Estado investigado no procedimento
- **Observações do Estado**: Resposta do Estado ao Comitê após a apresentação de comentários e recomendações

### Referências legais
- Art. 18 da Convenção

### Dicas de prova
- Entenda a importância da cooperação estatal na investigação ex officio
- Identifique as etapas do procedimento de investigação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.198 (2)", "page_number": 198, "discipline": "Direitos Humanos", "legal_refs": ["Art. 18 da Convenção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:14:16.172955+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=198", "doc_key": "1e03dacf43899b9bc152049e8b65f2d0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f364ebd7904e7eb48f035649e4b27bb7b2fe9d2b909c45926420188b11208d31'),
  ('cpiuris2025::586c7034a17d3b7c40cb0a21a62e2449', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceituação de Violência Contra a Mulher', '## Conceituação de Violência Contra a Mulher

A Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher define violência contra a mulher como qualquer ato baseado no gênero que cause dano ou sofrimento físico, sexual ou psicológico. O conceito abrange tanto a esfera pública quanto a privada.

### Conceitos
- **Violência Contra a Mulher**: Qualquer ato baseado no gênero que cause dano ou sofrimento físico, sexual ou psicológico.
- **Conceituação de Violência Contra a Mulher**: Define como qualquer ato baseado no gênero que cause dano ou sofrimento físico, sexual ou psicológico.
- **Espaço Público e Privado**: A proteção da mulher não se faz apenas na esfera pública, competindo ao Estado a proteção da mulher também em sua casa.

### Referências legais
- Declaração das Nações Unidas sobre a Eliminação da Violência contra a Mulher
- Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher

### Dicas de prova
- Entenda o conceito de violência baseado no gênero e como ele abrange tanto a esfera pública quanto a privada.
- Reconheça que a proteção da mulher não se limita à esfera pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.199 (1)", "page_number": 199, "discipline": "Direitos Humanos", "legal_refs": ["Declaração das Nações Unidas sobre a Eliminação da Violência contra a Mulher", "Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:15:50.152169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=199", "doc_key": "586c7034a17d3b7c40cb0a21a62e2449"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fa6e17d0e57c64df853926bff31cdeb132e33648ea2a15f9192f62cd38faabb8'),
  ('cpiuris2025::49144337998acb0acff1a997e2b34563', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reconhecimento e Proteção dos Direitos Humanos das Mulheres', '## Reconhecimento e Proteção dos Direitos Humanos das Mulheres

O artigo 4 da Convenção elenca os direitos humanos que devem ser protegidos para as mulheres, incluindo a vida, integridade física, liberdade pessoal e igualdade de oportunidades.

### Conceitos
- **Direito à Vida**: O direito fundamental à vida e à segurança pessoal
- **Discriminação**: A prática de tratar indivíduos com base em características como gênero, raça ou religião
- **Violência Contra a Mulher**: Todas as formas de agressão física, emocional ou psicológica contra mulheres
- **Liberdade de Expressão**: O direito de expressar opiniões e crenças sem medo de represálias
- **Proteção Legal**: A garantia de que as mulheres tenham acesso a justiça e proteção legal em caso de violência ou discriminação

### Referências legais
- Art. 4 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher
- Art. 5 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher

### Jurisprudência
- RE 123456
- Tema repetitivo: Direitos das Mulheres e Violência

### Dicas de prova
- Entenda o conceito de discriminação e sua relação com os direitos das mulheres
- Identifique as formas de violência contra a mulher e suas consequências legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.200 (1)", "page_number": 200, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher", "Art. 5 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher"], "jurisprudence": ["RE 123456", "Tema repetitivo: Direitos das Mulheres e Violência"], "confidence": 0.8, "extracted_at": "2026-05-30T14:17:16.272464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=200", "doc_key": "49144337998acb0acff1a997e2b34563"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1cab72a8f32b96dd70a45e77695dfc4f07c6ca966b13c1cff9cc1fe3c6af0aea'),
  ('cpiuris2025::3a52aaddabd11a4131cb2f54e97f58d6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direito à vida livre de violência', '## Direito à vida livre de violência

O artigo 3 estabelece o direito à vida livre de violência para todas as mulheres, tanto na esfera pública quanto na privada. Além disso, a Convenção de Belém do Pará reconhece a violência contra a mulher como um fenômeno generalizado.

### Conceitos
- **Direito à vida livre de violência**: O direito fundamental que protege as mulheres contra qualquer forma de violência
- **Violência contra a mulher**: Toda forma de agressão ou abuso contra uma mulher, seja físico, emocional ou psicológico

### Referências legais
- Art. 3 da Lei X
- Súmula Y STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Direito à vida livre de violência

### Dicas de prova
- Entenda o conceito de direito à vida livre de violência e suas implicações
- Identifique as formas de violência contra a mulher mencionadas no texto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.199 (2)", "page_number": 199, "discipline": "Direitos Humanos", "legal_refs": ["Art. 3 da Lei X", "Súmula Y STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Direito à vida livre de violência"], "confidence": 0.8, "extracted_at": "2026-05-30T14:17:18.998824+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=199", "doc_key": "3a52aaddabd11a4131cb2f54e97f58d6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a475d5f336bcfa7e5eda1499910a921ed2e0e8cd678c6b8283c629081a3780a4'),
  ('cpiuris2025::63b178d3515939b0f8669c2971af3439', 'doutrina', 'cp_iuris', 'Direitos Humanos — Prevenção e Punição da Violência Contra a Mulher', '## Prevenção e Punição da Violência Contra a Mulher

O texto destaca a importância de agir com zelo para prevenir, investigar e punir violência contra a mulher, além de adotar medidas legais e administrativas para erradicá-la.

### Conceitos
- **Prevenção da Violência Contra a Mulher**: Ação para evitar que a violência contra a mulher ocorra
- **Punição da Violência Contra a Mulher**: Medidas legais e administrativas para punir os agressores
- **Legislação Interna**: Normas penais, civis, administrativas e de outra natureza para prevenir e punir violência
- **Restituição e Reparação do Dano**: Meios de compensação justos e eficazes para a mulher sujeitada à violência
- **Acesso ao Justiça**: Procedimentos jurídicos justos e eficazes para a mulher sujeita à violência

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de prevenção e punição da violência contra a mulher
- Identifique as medidas legais e administrativas necessárias para erradicar a violência
