  ('cpiuris2025::792bed7c26c3bed6a297daad6f9ffb45', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção da Mulher Sujeita a Violência', '## Proteção da Mulher Sujeita a Violência

O artigo 9 da Convenção prevê a necessidade de identificar e proteger mulheres vulneráveis à violência, considerando situações discriminatórias como raça, religião ou condição migratória.

### Conceitos
- **Vulnerabilidade Interseccional**: Situação em que a situação de vulnerabilidade é ampliada por outra situação discriminatória
- **Raça**: Um dos motivos que podem caracterizar violência contra a mulher
- **Condição Migratória**: Um dos motivos que podem caracterizar violência contra a mulher

### Referências legais
- Art. 9 da Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher

