  ('cpiuris2025::dea9e0bdb408255edfc14d8fffdac09a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

Descreve o artigo 12 da Convenção Americana sobre Direitos Humanos, que permite petições individuais à Comissão Interamericana de Direitos Humanos e a importância das Regras de Bangkok para o tratamento de mulheres encarceradas.

### Conceitos
- **Convenção Americana sobre Direitos Humanos**: Acordo internacional que estabelece direitos humanos básicos
- **Comissão Interamericana de Direitos Humanos**: Órgão da ONU responsável por investigar violações dos direitos humanos na América do Sul
- **Regras de Bangkok**: Resolução da ONU que estabelece diretrizes para o tratamento de mulheres encarceradas

### Referências legais
- Art. 12 da Convenção Americana sobre Direitos Humanos
- Resolução nº 2010/16 das Nações Unidas

