Regra que proíbe discriminação entre homens e mulheres nas prisões, especialmente em relação à guarda de crianças.

### Conceitos
- **Discriminação**: Tratamento desigual ou injusto
- **Vulnerabilidade**: Situação de risco ou exposição a danos
- **Interseccionalidade**: Análise das interações entre diferentes formas de discriminação
- **Princípio do melhor interesse da criança**: Consideração que prioriza o bem-estar e a segurança das crianças

