  ('cpiuris2025::05029a325feb0a4fb7d6938f32e59ce6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção das Prisões e Tratamento de Detentas', '## Proteção das Prisões e Tratamento de Detentas

Regras para garantir dignidade e respeito às detentas durante revistas pessoais, desenvolvimento de métodos de inspeção alternativos e proteção de crianças em situações específicas.

### Conceitos
- **Dignidade**: Direito fundamental que deve ser respeitado às detentas
- **Respeito**: Dever do funcionário para tratar as detentas com consideração e cortesia
- **Revista Pessoal**: Procedimento de inspeção física das detentas durante a prisão
- **Métodos de Inspeção Alternativos**: Técnicas não invasivas para substituir revistas pessoais, como escâneres

### Referências legais
- Art. 35 da Lei nº 7.210/82 (Código de Processo Penal)

### Dicas de prova
- Reconheça a importância da dignidade e do respeito às detentas durante as revistas pessoais.
- Entenda a necessidade de métodos de inspeção alternativos para evitar danos psicológicos e físicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.203 (2)", "page_number": 203, "discipline": "Direitos Humanos", "legal_refs": ["Art. 35 da Lei nº 7.210/82 (Código de Processo Penal)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:22:41.510382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=203", "doc_key": "05029a325feb0a4fb7d6938f32e59ce6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f36e3f01bf7079a25cc7acdf6bb2261674b51993da469c63ab9f0cd061ef3c03'),
  ('cpiuris2025::dd448c91c4570d99200dade29eb28338', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos em Prisões', '## Proteção Internacional dos Direitos Humanos em Prisões

As regras estabelecem normas para a proteção das mulheres presas, incluindo o registro de informações confidenciais sobre as crianças, a localização e situação de custódia ou guarda, bem como a necessidade de fornecer absorventes higiênicos gratuitos e água.

### Conceitos
- **Proteção Internacional dos Direitos Humanos**: Regras para garantir os direitos das mulheres presas
- **Confidencialidade**: Uso de informações sobre crianças com o objetivo de garantir seu melhor interesse
- **Higiene e Saúde**: Fornecimento de absorventes higiênicos gratuitos e água para as detentas e crianças
- **Dignidade**: Respeito à dignidade das mulheres presas durante revistas e medidas de segurança

