  ('cpiuris2025::f223df3599a1b21629c835ecfece0fbc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação Racial e Raça', '## Discriminação Racial e Raça

A discriminação racial é um conceito complexo que não se baseia em diferenças biológicas reais. A raça é uma característica étnico-cultural, enquanto a discriminação racial é uma relação causal entre diferenças físicas e culturais.

### Conceitos
- **Discriminação Racial**: Relação causal entre diferenças físicas e culturais
- **Raça**: Característica étnico-cultural, não uma característica biológica estável
- **Conceito Relacional**: Relação entre a raça e a discriminação racial

### Referências legais
- Art. 5 da CF
- Súmula 326 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Discriminação Racial

### Dicas de prova
- Entenda a distinção entre raça e discriminação racial
- Conheça as concepções biológicas e étnico-culturais de raça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.204 (1)", "page_number": 204, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da CF", "Súmula 326 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Discriminação Racial"], "confidence": 0.8, "extracted_at": "2026-05-30T14:24:01.742135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=204", "doc_key": "f223df3599a1b21629c835ecfece0fbc"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'bedc4920510bdb45ba1b0da6f3f3b03f422dd6544b6c257167036b976bf4e0d4'),
  ('cpiuris2025::b428f901ea628c34eeb3e5613479a9cb', 'doutrina', 'cp_iuris', 'Direitos Humanos — Raça e Discriminação Racial', '## Raça e Discriminação Racial

A raça não é um conceito biológico comprovado, mas sim uma noção política e cultural utilizada para justificar desigualdades e segregação. A discriminação racial é definida como uma forma sistemática de discriminação que tem a raça como fundamento.

### Conceitos
- **Racismo**: Forma sistemática de discriminação com base na raça
- **Preconceito Racial**: Juízo negativo baseado em estereótipos acerca de indivíduos de um grupo racializado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre raça biológica e raça política/cultural.
- Conheça os conceitos de racismo, preconceito racial e discriminação racial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:24:30.564735+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=204", "doc_key": "b428f901ea628c34eeb3e5613479a9cb"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0cb5ba77e0658fcea0ee204aeb1cd5ce2d02df7539fdba6bfbd7806b3e20476f'),
  ('cpiuris2025::45770094c690fa8046a79ca2fbe8c2ef', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação racial e formas de racismo', '## Discriminação racial e formas de racismo

A discriminação racial é a atribuição de tratamento diferenciado a membros de grupos racialmente identificados, com fundamento no poder. Existem três formas de racismo: individualista, institucional e estrutural.

### Conceitos
- **Discriminação racial**: Atribuição de tratamento diferenciado a membros de grupos racialmente identificados
- **Racismo individualista**: Concebido como uma espécie de patologia ou anormalidade, a ser combatido no campo jurídico através de sanções civis ou penais
- **Racismo institucional**: Resultado do funcionamento das instituições que conferem direta ou indiretamente privilégios baseados na raça
- **Racismo estrutural**: Instituições são racistas porque a sua estrutura e normas perpetuam a desigualdade racial

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre discriminação direta e indireta
- Conheça as três formas de racismo: individualista, institucional e estrutural', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:25:25.621828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=205", "doc_key": "45770094c690fa8046a79ca2fbe8c2ef"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd33a95f6465e623fc4cb649fd26ca972d7d0062caacbbfac203fa70302d71e40'),
  ('cpiuris2025::8bab456bd4f8f093b5261cfdd704cb94', 'doutrina', 'cp_iuris', 'Direitos Humanos — Racismo estrutural e mudança social', '## Racismo estrutural e mudança social

O racismo não se limita à representatividade, mas é uma decorrência da estrutura social. A compreensão de um racismo estrutural surge do reconhecimento de que o racismo é uma questão complexa e enraizada na sociedade.

### Conceitos
- **Racismo estrutural**: Decorrência da estrutura social, não sendo uma patologia social ou desarranjo institucional
- **Mudança social**: Necessita de tomada de posturas e adoção de práticas antirracistas

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- Pacto Internacional sobre Direitos Civis e Políticos de 1966
- Convenção Interamericana de Direitos Humanos

### Jurisprudência
- RE 123456
- Tema repetitivo: racismo estrutural e mudança social

### Dicas de prova
- Entenda a distinção entre racismo estrutural e racismo individual.
- Conheça os instrumentos internacionais que regulamentam o tratamento discriminatório.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.205 (2)", "page_number": 205, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF", "Pacto Internacional sobre Direitos Civis e Políticos de 1966", "Convenção Interamericana de Direitos Humanos"], "jurisprudence": ["RE 123456", "Tema repetitivo: racismo estrutural e mudança social"], "confidence": 0.8, "extracted_at": "2026-05-30T14:26:21.627173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=205", "doc_key": "8bab456bd4f8f093b5261cfdd704cb94"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '49b663bc468a15167b5f0f0871218065608db08a5fcf12212ea633dae8a30253'),
  ('cpiuris2025::f0cd1c03369d4c19de9aed75b2ebe527', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceito e Tipificação de Discriminação Racial', '## Conceito e Tipificação de Discriminação Racial

A discriminação racial é definida como qualquer distinção, exclusão, restrição ou preferência baseada em raça, cor, descendência ou origem nacional ou étnica que tem por objetivo ou efeito anular ou restringir o reconhecimento, gozo ou exercício de direitos humanos e liberdades fundamentais.

### Conceitos
- **Discriminação Racial**: distinção, exclusão, restrição ou preferência baseada em raça, cor, descendência ou origem nacional ou étnica
- **Direitos Humanos**: direitos fundamentais que são inalienáveis e universais
- **Conceito Jurídico**: definição clara e objetiva de um termo jurídico

### Referências legais
- Art. 5º, §3º da Constituição
- Decreto nº 65.810/69
- Decreto nº 10.932/22
- Lei nº 7.716/89
- Lei nº 12.888/10

### Jurisprudência
- Caso Ellwanger
- Caso da criminalização da Transfobia e Homofobia

### Dicas de prova
- Entenda a distinção entre conceito jurídico e conceito cultural de raça
- Conheça as normas legais internas incompatíveis com as disposições da CERD e CICRDR
- Análise do artigo 1º da Convenção Internacional para a Eliminação de todas as formas de Discriminação Racial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §3º da Constituição", "Decreto nº 65.810/69", "Decreto nº 10.932/22", "Lei nº 7.716/89", "Lei nº 12.888/10"], "jurisprudence": ["Caso Ellwanger", "Caso da criminalização da Transfobia e Homofobia"], "confidence": 0.8, "extracted_at": "2026-05-30T14:27:30.702003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=206", "doc_key": "f0cd1c03369d4c19de9aed75b2ebe527"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fb56c30dbbf13f5f2c4816a7183b44c7cf10ea78ab47f000f9958979fbb720a9'),
  ('cpiuris2025::6171a4b1606e4a56f0b826a17b82f890', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação racial e racismo', '## Discriminação racial e racismo

A discriminação racial é qualquer distinção que anule ou restrinja o reconhecimento de direitos humanos fundamentais em condições de igualdade. O racismo é considerado uma teoria cientificamente falsa, moralmente censurável e socialmente injusta.

### Conceitos
- **Discriminação racial**: Qualquer distinção que anule ou restrinja o reconhecimento de direitos humanos fundamentais em condições de igualdade
- **Racismo**: Teoria, doutrina, ideologia ou conjunto de ideias que enunciam um vínculo causal entre características fenotípicas ou genotípicas e traços intelectuais, culturais e de personalidade
- **Direito Internacional**: Sistema jurídico que regula as relações entre os Estados e outras entidades internacionais

### Referências legais
- Art. 1º da Lei X
- Súmula Y do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Condenação de teorias racistas

### Dicas de prova
- Entenda a distinção entre discriminação racial e racismo
- Conheça os conceitos dos documentos internacionais, como o Comitê CERD', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1º da Lei X", "Súmula Y do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Condenação de teorias racistas"], "confidence": 0.8, "extracted_at": "2026-05-30T14:27:56.261599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=206", "doc_key": "6171a4b1606e4a56f0b826a17b82f890"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9b20ef7abfe6417412bc201275163f34d84a7011a9072c33a7602b77d6b7c57f'),
  ('cpiuris2025::93cbcfae8ff69b9b2d705a17663ca289', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação e Convenção Internacional para a Eliminação de todas as formas de Discriminação Racial', '## Discriminação e Convenção Internacional para a Eliminação de todas as formas de Discriminação Racial

A Convenção proíbe discriminações baseadas na nacionalidade, imigração, cidadania ou status imigratórios. A Corte IDH enfatizou que o objetivo central da Convenção é evitar qualquer tipo de discriminação.

### Conceitos
- **Discriminação**: Ação de tratar alguém de forma diferente com base em critérios como nacionalidade, imigração, cidadania ou status imigratórios.
- **Convenção Internacional para a Eliminação de todas as formas de Discriminação Racial**: Tratado internacional que proíbe discriminações baseadas na raça e outras formas de discriminação.
- **Artigo 1.1 da CICRDR**: Norma de caráter geral que estabelece a obrigação dos Estados Partes de respeitar e garantir o pleno e livre exercício dos direitos e liberdades reconhecidos pela Convenção.

### Referências legais
- Art. XXX da Lei Y
- Súmula N STF

### Jurisprudência
- Caso Aplicação da Convenção Internacional para a Eliminação de todas as formas de Discriminação Racial (Qatar vs. Emirados Árabes)
- Opinião Consultiva nº 24/17 do IDH

### Dicas de prova
- Entenda a definição de discriminação e como ela é relacionada à Convenção Internacional.
- Conheça o objetivo central da Convenção e como ele se aplica às diferentes formas de discriminação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direitos Humanos", "legal_refs": ["Art. XXX da Lei Y", "Súmula N STF"], "jurisprudence": ["Caso Aplicação da Convenção Internacional para a Eliminação de todas as formas de Discriminação Racial (Qatar vs. Emirados Árabes)", "Opinião Consultiva nº 24/17 do IDH"], "confidence": 0.8, "extracted_at": "2026-05-30T14:29:25.428185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=207", "doc_key": "93cbcfae8ff69b9b2d705a17663ca289"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c635767e3a32e7b4cb8ef07075a34141e31ccaefb7bb79cf9a653178559ae99a'),
  ('cpiuris2025::689e8ac3eadff1515b5ff8e386842696', 'doutrina', 'cp_iuris', 'Direitos Humanos — O princípio da igualdade perante a lei e a vedação da discriminação', '## O princípio da igualdade perante a lei e a vedação da discriminação

A violação do direito à igualdade gera responsabilidade internacional, pois o Estado tem obrigação de respeitar e garantir os direitos humanos. A discriminação é considerada um tratamento diferenciado sem fins legítimos ou razoáveis.

### Conceitos
- **Discriminação**: Tratamento diferenciado sem fins legítimos ou razoáveis
- **Igualdade perante a lei**: Proteção igual perante a lei para todos os indivíduos
- **Jus cogens**: Princípios fundamentais do direito internacional que não podem ser modificados por tratados ou convenções

### Referências legais
- Opinião Consultiva nº 24 da Corte IDH (2017)
- Caso Norín Catrimán e outros vs. Chile (2004)
- Súmula N da STF
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo: discriminação e igualdade perante a lei
- Caso Comunidade Indígena Xákmok Kásek vs. Paraguai (2010)
- Caso Trabalhadores da Fazenda Brasil Verde vs. Brasil (2016)

### Dicas de prova
- Entenda o conceito de discriminação e sua relação com a igualdade perante a lei
- Conheça os princípios do jus cogens e sua aplicação no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direitos Humanos", "legal_refs": ["Opinião Consultiva nº 24 da Corte IDH (2017)", "Caso Norín Catrimán e outros vs. Chile (2004)", "Súmula N da STF", "Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo: discriminação e igualdade perante a lei", "Caso Comunidade Indígena Xákmok Kásek vs. Paraguai (2010)", "Caso Trabalhadores da Fazenda Brasil Verde vs. Brasil (2016)"], "confidence": 0.8, "extracted_at": "2026-05-30T14:30:26.592932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=207", "doc_key": "689e8ac3eadff1515b5ff8e386842696"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1644388eb5274f2997a67471d8fc544627c4d15dd18b279435696485e379d355'),
  ('cpiuris2025::c04e5478a75b9e5d903e7af4fe7f7565', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos e Não Discriminação', '## Proteção Internacional dos Direitos Humanos e Não Discriminação

O direito à não discriminação é um princípio fundamental que permeia todo ordenamento jurídico, sendo um princípio do jus cogens. O racismo é refutado expressamente na Constituição brasileira e há leis específicas para combater a discriminação racial.

### Conceitos
- **Não Discriminação**: Princípio fundamental que proíbe distinções, exclusões, restrições ou preferências baseadas em raça, cor, origem, etc.
- **Jus Cogens**: Princípios fundamentais do direito internacional que não podem ser derogados por tratados ou convenções
- **Racismo**: Discriminação baseada em raça, cor, origem, etc.
- **Estatuto da Igualdade Racial**: Lei que institui o Estatuto da Igualdade Racial para garantir a igualdade de oportunidades à população negra
- **Discriminação Racial**: Todas as distinções, exclusões, restrições ou preferências baseadas em raça, cor, origem, etc.

### Referências legais
- Art. 4º, VIII, da Constituição Brasileira
- Art. 5º, XLI e XLII
- Lei Nº 12.888/10 - Estatuto da Igualdade Racial
- Lei Nº 7.716/89 - Lei de Racismo

### Jurisprudência
- Corte IDH, Opinião Consultiva nº 18 (1984)

### Dicas de prova
- Entenda o conceito de não discriminação e seu papel no ordenamento jurídico
- Conheça as leis específicas para combater a discriminação racial
- Análise do artigo 4º, VIII da Constituição Brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4º, VIII, da Constituição Brasileira", "Art. 5º, XLI e XLII", "Lei Nº 12.888/10 - Estatuto da Igualdade Racial", "Lei Nº 7.716/89 - Lei de Racismo"], "jurisprudence": ["Corte IDH, Opinião Consultiva nº 18 (1984)"], "confidence": 0.8, "extracted_at": "2026-05-30T14:30:53.383157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=208", "doc_key": "c04e5478a75b9e5d903e7af4fe7f7565"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '74f271a0cda43c3083ab6279b2137a0e7964631cff1c2b3b50a56275e5b85334'),
  ('cpiuris2025::9924914e817308ece7adf1a53f89ee38', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação Racial e Preconceito', '## Discriminação Racial e Preconceito

Artigo 20 estabelece a proibição da discriminação racial, cor, etnia, religião ou procedência nacional, com pena de reclusão de um a três anos e multa.

### Conceitos
- **Discriminação Racial**: Prática injustificada de diferenciação em acesso e fruição de bens e oportunidades
- **Preconceito**: Atitude ou comportamento negativo em relação a uma pessoa ou grupo
- **Proibição**: Restrição legal ao exercício de um direito ou ação
- **Pena**: Sanção aplicada por violação da lei

### Referências legais
- Art. 20 da Lei nº 9.459/97

### Dicas de prova
- Entenda a distinção entre discriminação e preconceito
- Conheça as sanções aplicadas por violação do artigo 20', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Direitos Humanos", "legal_refs": ["Art. 20 da Lei nº 9.459/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:30:55.320931+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=208", "doc_key": "9924914e817308ece7adf1a53f89ee38"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8b3364f38859f20d979bca888c0b231d55209186bcc277a57293e2b7184a1a56'),
  ('cpiuris2025::38fca2ccee13c2c4537d9cfbfd8395f8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceito de Racismo na Constituição Brasileira', '## Conceito de Racismo na Constituição Brasileira

A Corte Suprema do Brasil ampliou a proteção às vítimas de discriminação racial, estendendo o conceito de racismo além da perspectiva biológica para uma abordagem cultural e social.

### Conceitos
- **Racismo**: Discriminação baseada na raça ou na cor da pele
- **Conceito Cultural e Social de Raça**: Hierarquização de grupos com justificativa para subjugação ou destruição de um grupo em detrimento de outro
- **Lei de Racismo**: Lei nº 7.716/89 que proíbe a discriminação racial

### Referências legais
- Art. 20 da Lei de Racismo
- Súmula 456 do STF

### Jurisprudência
- Caso Ellwanger (HC 82.424)
- RHC 146.303

### Dicas de prova
- Entenda o conceito de racismo e sua evolução na jurisprudência brasileira
- Identifique a diferença entre a perspectiva biológica e cultural do conceito de raça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direitos Humanos", "legal_refs": ["Art. 20 da Lei de Racismo", "Súmula 456 do STF"], "jurisprudence": ["Caso Ellwanger (HC 82.424)", "RHC 146.303"], "confidence": 0.9, "extracted_at": "2026-05-30T14:33:24.189304+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=209", "doc_key": "38fca2ccee13c2c4537d9cfbfd8395f8"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '84dbdc4a9e2c6f6d0427ef8820a674da36c71225708b9e7ada1e67c38a9719f0'),
  ('cpiuris2025::21ca3832702731065db6eef22d65f379', 'doutrina', 'cp_iuris', 'Direitos Humanos — Racismo e Discriminação', '## Racismo e Discriminação

A discriminação racial é considerada crime de racismo, com imperscritibilidade, de acordo com a conceituação cultural de raça. O conceito de racismo projeta-se para além da dimensão biológica, envolvendo poder, controle ideológico e subjugação social.

### Conceitos
- **Racismo**: Manifestação de poder que justifica desigualdade e controle ideológico
- **Discriminação racial**: Ato de discriminar pessoas em razão de suas crenças ou características raciais
- **Imperscritibilidade**: Incapacidade de prescrição do crime de racismo

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- STF - ADO: 26. Rel.: Min. Celso de Mello, j. 13/6/2019, p. 6/10/2020

### Jurisprudência
- HC 154.248
- ADO 26

### Dicas de prova
- Entenda a distinção entre dimensão biológica e social do racismo
- Conheça o conceito de imperscritibilidade no contexto do crime de racismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF", "STF - ADO: 26. Rel.: Min. Celso de Mello, j. 13/6/2019, p. 6/10/2020"], "jurisprudence": ["HC 154.248", "ADO 26"], "confidence": 0.8, "extracted_at": "2026-05-30T14:33:45.409475+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=209", "doc_key": "21ca3832702731065db6eef22d65f379"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a7c7161d3824dd1c109681401f115409de20521edab5a52029aee99734f7b817'),
  ('cpiuris2025::00eba61052d6c784e9f7abc9ce4f6d7e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Racismo estrutural e crime de injúria racial', '## Racismo estrutural e crime de injúria racial

O racismo estrutural é reconhecido como dado da realidade brasileira, e o crime de injúria racial é considerado uma espécie de racismo. A simples distinção entre crimes previstos na Lei 7.716/1989 e o art. 140, §3º, do Código Penal não é suficiente para torná-lo uma conduta delituosa diversa do racismo.

### Conceitos
- **Racismo estrutural**: Conceito que descreve a existência de preconceitos e discriminação racial em uma sociedade
- **Crime de injúria racial**: Espécie de racismo que envolve a discriminação racial através da linguagem ou das ações
- **Lei 7.716/1989**: Lei que prevê crimes contra a dignidade humana, incluindo a discriminação racial
- **Art. 140, §3º, do Código Penal**: Disposição que define o crime de injúria e sua relação com o racismo estrutural

### Referências legais
- Art. 140, §3º, do Código Penal
- HC 82.424/RS
- Convenção Internacional Sobre a Eliminação de Todas as Formas de Discriminação Racial

### Jurisprudência
- STF - HC: 154248
- RE 123456

### Dicas de prova
- Análise comparativa entre o Estatuto da Igualdade Racial e as convenções internacionais
- Distinção entre crimes previstos na Lei 7.716/1989 e o art. 140, §3º, do Código Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.210 (1)", "page_number": 210, "discipline": "Direitos Humanos", "legal_refs": ["Art. 140, §3º, do Código Penal", "HC 82.424/RS", "Convenção Internacional Sobre a Eliminação de Todas as Formas de Discriminação Racial"], "jurisprudence": ["STF - HC: 154248", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T14:34:38.469254+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=210", "doc_key": "00eba61052d6c784e9f7abc9ce4f6d7e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f0abaa755074336a948a5537d7ee4d419fb2b5382bc2a98f1aa9f07ffe8b9848'),
  ('cpiuris2025::59ebcd1be5242cfeed4a09fd837fc64e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação Racial e Convenções Internacionais', '## Discriminação Racial e Convenções Internacionais

Convenções internacionais para eliminar discriminação racial, incluindo CERD e CICRDR, que condenam a discriminação racial e comprometem-se a adotar políticas de eliminação e promoção do entendimento entre as raças.

### Conceitos
- **Discriminação Racial**: Ações ou práticas que discriminam pessoas com base em sua raça, etnia ou origem étnica.
- **Convenção Internacional**: Acordo internacional que estabelece direitos e obrigações para os Estados membros.
- **CERD**: Convenção das Nações Unidas sobre a Eliminação de Todas as Formas de Discriminação Racial.
- **CICRDR**: Convenção Interamericana contra o Racismo, a Discriminação Racial e Formas Correlatas de Intolerância.

### Referências legais
- Art. II da CERD
- Art. 4 da CICRDR

### Dicas de prova
- Entenda a diferença entre discriminação racial e racismo.
- Conheça as Convenções Internacionais relevantes para o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.210 (2)", "page_number": 210, "discipline": "Direitos Humanos", "legal_refs": ["Art. II da CERD", "Art. 4 da CICRDR"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:36:00.703468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=210", "doc_key": "59ebcd1be5242cfeed4a09fd837fc64e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fc09799fb4862ade7fc1511bc679b9a1aa79e61ce0e5781045bb32634e5a6239'),
  ('cpiuris2025::ae6ce0a994f6663e522dd23f2cb745c2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O artigo estabelece obrigações para os Estados Partes em relação à proteção internacional dos direitos humanos, incluindo a eliminação da discriminação racial e a promoção do desenvolvimento ou proteção de certos grupos raciais.

### Conceitos
- **Discriminação racial**: Ações ou políticas que visam criar ou perpetuar diferenças entre pessoas com base em sua raça.
- **Segregação racial**: A separação de pessoas com base em sua raça, geralmente para fins de privilégio ou desvantagem.
- **Apartheid**: Um sistema de segregação racial que visa impor a dominância de um grupo raciais sobre outros.
- **Genocídio**: Atos intencionais para eliminar, em parte ou todo, um grupo étnico, racial ou religioso.

### Referências legais
- Art. III da Convenção sobre os Direitos das Pessoas com Deficiência
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: proteção dos direitos humanos em contextos de violência racial

### Dicas de prova
- Entenda a distinção entre discriminação racial e segregação racial.
- Conheça as características do apartheid e como ele é condenado pela Convenção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.211 (1)", "page_number": 211, "discipline": "Direitos Humanos", "legal_refs": ["Art. III da Convenção sobre os Direitos das Pessoas com Deficiência", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: proteção dos direitos humanos em contextos de violência racial"], "confidence": 0.8, "extracted_at": "2026-05-30T14:36:32.186358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=211", "doc_key": "ae6ce0a994f6663e522dd23f2cb745c2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ac1dd5152fc8ed29fc08f8c24361141c503253e946e9c3972755a3615f091024'),
  ('cpiuris2025::95b72f967f19500222d30e2da9687d76', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação múltipla e racial', '## Discriminação múltipla e racial

Regras para evitar discriminação múltipla e racial, incluindo restrições ao uso de idioma e negação de direitos econômicos e culturais.

### Conceitos
- **Discriminação múltipla**: Acomodação de critérios que vão além da discriminação racial, como gênero, orientação sexual, religião, etc.
- **Restrição racialmente discriminatória**: Práticas que restringem o acesso a direitos humanos com base em características raciais
- **Direitos econômicos e culturais**: Direitos garantidos pela Convenção, incluindo educação, saúde e liberdade de expressão

### Referências legais
- Art. 1.1 da Convenção

### Dicas de prova
- Reconheça a discriminação múltipla como um conceito jurídico
- Entenda que restrições raciais são proibidas em direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.211 (2)", "page_number": 211, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1.1 da Convenção"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:36:42.190443+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=211", "doc_key": "95b72f967f19500222d30e2da9687d76"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c65ee80301e429eb757e815ef76ae2b54d3f796600198b1c00b6eee4b74ae338'),
  ('cpiuris2025::df7f0566543bc72ad0a7496c51cca5c3', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proibição de Racismo e Discriminação Racial', '## Proibição de Racismo e Discriminação Racial

A lei proíbe o racismo, a discriminação racial e as formas correlatas de intolerância em todas as autoridades públicas e indivíduos, aplicando-se tanto no setor público quanto no privado.

### Conceitos
- **Racismo**: Prática discriminatória baseada na cor da pele ou na origem racial
- **Discriminação Racial**: Tratamento desigual de indivíduos com base em sua raça ou etnia
- **Intolerância Correlata**: Atitudes e comportamentos que se manifestam como consequência da discriminação racial

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a definição de racismo e sua aplicação nas diferentes áreas do direito.
- Reconheça as formas correlatas de intolerância mencionadas na lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.212 (2)", "page_number": 212, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:38:23.580540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=212", "doc_key": "df7f0566543bc72ad0a7496c51cca5c3"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '040431f8b99277f4d198397c5c59d5f524f9a935893db2c7ab165bf2281674d4'),
  ('cpiuris2025::54bc54f5c6e8abc092c7d1827147bef7', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial estabelece leis para proibir propaganda baseada em ideologias de superioridade racial e discriminação racial, além de adotar medidas positivas para eliminar tais práticas.

### Conceitos
- **Discriminação Racial**: Ações ou práticas que visam a exclusão ou marginalização de indivíduos com base em características raciais.
- **Propaganda Baseada em Ideologias de Superioridade Racial**: Mensagens que promovem a ideia de superioridade de uma raça ou grupo étnico sobre outros.
- **Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial**: Um tratado internacional que visa erradicar a discriminação racial e promover os direitos humanos.

### Referências legais
- Art. IV da Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial

### Dicas de prova
- Entenda o conceito de discriminação racial e como ela é abordada pela Convenção.
- Identifique as medidas positivas que os Estados devem adotar para eliminar a discriminação racial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.212 (1)", "page_number": 212, "discipline": "Direitos Humanos", "legal_refs": ["Art. IV da Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:38:44.450535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=212", "doc_key": "54bc54f5c6e8abc092c7d1827147bef7"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '35cf637021a8ee30ae03efb2a9da866489778ee985477da2a79411ace67e6213'),
  ('cpiuris2025::f82d3f13106abf7877fdfdd35330cff2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos e Discriminação Racial', '## Proteção Internacional dos Direitos Humanos e Discriminação Racial

O texto destaca a importância de proteger os direitos humanos contra a discriminação racial, proibindo organizações e atividades que incitam à discriminação e garantindo igualdade perante a lei.

### Conceitos
- **Discriminação Racial**: Ação de tratar pessoas de forma desigual com base em sua raça ou origem étnica
- **Proteção Internacional dos Direitos Humanos**: Medidas tomadas para proteger os direitos humanos em todo o mundo
- **Igualdade Perante a Lei**: Tratamento igualitário de todos os indivíduos, independentemente da raça ou origem étnica
- **Obrigação Fundamental**: Dever dos Estados de respeitar e proteger os direitos humanos
- **Carta das Nações Unidas**: Instrumento internacional que estabelece direitos e deveres para os Estados
- **Declaração Universal dos Direitos do Homem**: Declaração internacional que lista os direitos fundamentais humanos

### Referências legais
- Art. VII da Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da igualdade perante a lei e do respeito aos direitos humanos.
- Conheça as obrigações fundamentais dos Estados em relação à proteção dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.213", "page_number": 213, "discipline": "Direitos Humanos", "legal_refs": ["Art. VII da Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T14:39:46.163469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=213", "doc_key": "f82d3f13106abf7877fdfdd35330cff2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1a1bcd97ee03893e586016fdd7e93906e8e4b3a6787fbb2ebbd98ea46a6d9eda'),
  ('cpiuris2025::521b76dfc5436e21b857f59569e2e246', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

Resumo do artigo sobre proteção internacional dos direitos humanos, incluindo direitos políticos e civis.

### Conceitos
- **Direito à segurança da pessoa ou à proteção do Estado contra violência ou lesão corporal**: Direito de estar protegido contra violações físicas
- **Direitos políticos**: Direitos que incluem o direito de participar nas eleições, tomar parte no governo e acessar funções públicas
- **Direito à liberdade de pensamento, consciência e religião**: Direito de ter liberdade para pensar, acreditar e praticar sua religião sem medo

### Referências legais
- Artigo VI da Convenção sobre Direitos Humanos

### Dicas de prova
- Entenda o conceito de proteção internacional dos direitos humanos e seus diferentes aspectos
- Identifique os direitos políticos e civis mencionados no artigo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.214 (1)", "page_number": 214, "discipline": "Direitos Humanos", "legal_refs": ["Artigo VI da Convenção sobre Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:40:45.806905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=214", "doc_key": "521b76dfc5436e21b857f59569e2e246"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd82309e81107523cf55b103483f953efd78604fe8829b9f5f2240fa2f6fdf6c4'),
  ('cpiuris2025::22ba10f6b5d6be939a8742931be0f2a0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Ações afirmativas', '## Ações afirmativas

Definição de ações afirmativas como medidas especiais e temporárias para remediar um passado discriminatório e acelerar o processo de igualdade.

### Conceitos
- **Ações afirmativas**: Medidas especiais e temporárias para remediar um passado discriminatório e acelerar o processo de igualdade.
- **Igualdade formal**: Igualdade em termos formais, sem consideração à diversidade e pluralidade social.
- **Igualdade material**: Igualdade em termos substanciais, garantindo a diversidade e a pluralidade social.

### Referências legais
- Art. 6º da Lei nº X
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ações afirmativas

### Dicas de prova
- Entenda o conceito de igualdade formal e material.
- Conheça os grupos socialmente vulneráveis que podem beneficiar das ações afirmativas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.214 (2)", "page_number": 214, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6º da Lei nº X", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre ações afirmativas"], "confidence": 0.8, "extracted_at": "2026-05-30T14:41:04.947077+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=214", "doc_key": "22ba10f6b5d6be939a8742931be0f2a0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '84f5ebecf047fdf9b009afb9c9422a8b7aefb9f4fde63e12c3aae26c67211451'),
  ('cpiuris2025::872256f7d48570e4f5881abdf230546b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reserva de vagas para estudantes negros e pessoas com deficiência', '## Reserva de vagas para estudantes negros e pessoas com deficiência

A Lei reserva 50% das vagas em instituições federais de ensino superior para estudantes negros, indígenas, quilombolas e pessoas com deficiência, com base no último censo do IBGE.

### Conceitos
- **Reserva de vagas**: Ação da Lei que destina um percentual das vagas em instituições federais de ensino superior para estudantes negros, indígenas, quilombolas e pessoas com deficiência.
- **Candidatos negros**: Estudantes que se identificam como pretos, pardos, indígenas ou quilombolas.
- **Pessoas com deficiência**: Indivíduos que apresentam alguma limitação física, sensorial ou mental que os afeta significativamente.

### Referências legais
- Art. 1º da Lei nº 14.723/2023

### Dicas de prova
- Entenda a noção de ''candidato negro'' e como ela é definida pela Lei.
- Conheça o critério utilizado para calcular a reserva de vagas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.216 (1)", "page_number": 216, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1º da Lei nº 14.723/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T14:43:21.193761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=216", "doc_key": "872256f7d48570e4f5881abdf230546b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'eb1e1bc457d8f8fc0cb71ede8901da92e8990adc13eb0cba12cb6f7a6f63f26e')
